// بيانات السور
Object.assign(quranData, {
    7: { // سورة الأعراف
        name: "الأعراف",
        basmalaTafsir: ``,
        verses: [
            { text: "الٓمٓصٓ", tafsir: `قد تقدم تفسير فواتح السور المقطعة ، وأنها رموز بين الله والرسول صلى‌الله‌عليه‌وآله‌وسلم ، أو أن من جنس هذه الحروف.` },
            { text: "كِتَٰبٌ أُنزِلَ إِلَيْكَ فَلَا يَكُن فِى صَدْرِكَ حَرَجٌ مِّنْهُ لِتُنذِرَ بِهِۦ وَذِكْرَىٰ لِلْمُؤْمِنِينَ", tafsir: `وهو القرآن فليس حروفه أمرا خارقا ، وإنما التركيب أمر خارق ( فَلا يَكُنْ فِي صَدْرِكَ ) يا رسول الله ( حَرَجٌ ) وضيق ( مِنْهُ ) أي من هذا الكتاب ، حيث ترى أن قومك يكذبوك ويؤذوك في سبيله ، بل اطمئن بنصر الله سبحانه وحسن ثوابه ، وإنما أنزل الكتاب إليك ( لِتُنْذِرَ بِهِ ) أي بهذا الكتاب ، الكافرين والعصاة ، بعقاب الله تعالى ( وَ ) ليكون ( ذِكْرى ) وتذكرة ( لِلْمُؤْمِنِينَ ) فيتذكرون به الدين والأصول والفروع ، ليعملوا بما فيه.` },
            { text: "ٱتَّبِعُوا۟ مَآ أُنزِلَ إِلَيْكُم مِّن رَّبِّكُمْ وَلَا تَتَّبِعُوا۟ مِن دُونِهِۦٓ أَوْلِيَآءَ قَلِيلًا مَّا تَذَكَّرُونَ", tafsir: `أيها الناس ( ما أُنْزِلَ إِلَيْكُمْ مِنْ رَبِّكُمْ ) من القرآن والأحكام ( وَلا تَتَّبِعُوا مِنْ دُونِهِ ) أي غير ربكم تعالى ( أَوْلِياءَ ) كالأوثان ، والكفار ( قَلِيلاً ما تَذَكَّرُونَ ) أي قليل ـ أيها البشر ـ تذكركم واتعاظكم.` },
            { text: "وَكَم مِّن قَرْيَةٍ أَهْلَكْنَٰهَا فَجَآءَهَا بَأْسُنَا بَيَٰتًا أَوْ هُمْ قَآئِلُونَ", tafsir: `أي كثيرا من أهل القرى ( أَهْلَكْناها ) عبّر بالقرية وأريد أهلها بعلاقة الحال والمحل ، والمراد بالإهلاك إرادته ، فإنه كثيرا ما يقال الفعل ويراد مقدماته ـ كما قرّر في علم البلاغة ـ ( فَجاءَها بَأْسُنا ) أي عذابنا ( بَياتاً ) أي بالليل ( أَوْ هُمْ قائِلُونَ ) أي في وقت القيلولة وهي نصف النهار ، من « أقال » بمعنى « أراح » ، ومن المعلوم أن العذاب فَما كانَ دَعْواهُمْ إِذْ جاءَهُمْ بَأْسُنا إِلاَّ أَنْ قالُوا إِنَّا كُنَّا ظالِمِينَ (5) فَلَنَسْئَلَنَّ الَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْئَلَنَّ الْمُرْسَلِينَ (6) فَلَنَقُصَّنَّ عَلَيْهِمْ بِعِلْمٍ وَما كُنَّا غائِبِينَ (7) وَالْوَزْنُ يَوْمَئِذٍ الْحَقُّ فَمَنْ ثَقُلَتْ مَوازِينُهُ فَأُولئِكَ هُمُ الْمُفْلِحُونَ (8) في هذين الوقتين أشد وقعا لغفلة الناس وراحتهم.` },
            { text: "فَمَا كَانَ دَعْوَىٰهُمْ إِذْ جَآءَهُم بَأْسُنَآ إِلَّآ أَن قَالُوٓا۟ إِنَّا كُنَّا ظَٰلِمِينَ", tafsir: `أي دعاء هؤلاء الذين أهلكناهم ، وكلامهم ( إِذْ جاءَهُمْ بَأْسُنا ) وقت مجيء العذاب ( إِلَّا ) الاعتراف بذنبهم ب ( أَنْ قالُوا إِنَّا كُنَّا ظالِمِينَ ) فاعترفوا بما كان منهم حين رأوا العذاب. [7] لكن الاعتراف لم ينفعهم ( فَلَنَسْئَلَنَّ الَّذِينَ أُرْسِلَ إِلَيْهِمْ ) أي الأمم الذين أرسل الله إليهم الرسل ، يسألهم عن أعمالهم ، وما أجابوا به الرسل لما بعثوا إليهم ( وَلَنَسْئَلَنَّ الْمُرْسَلِينَ ) أي الأنبياء ، فإن كل واحد من الرسل والأمم لا بد وأن يحضر في محضر الحساب. [8] وليس السؤال لجهلنا بما صدر من الطرفين ( فَلَنَقُصَّنَّ عَلَيْهِمْ بِعِلْمٍ ) أي نقص ما كان من الطرفين قصة صادرة عن علمنا بأحوالهم ، فليس السؤال إلا التقرير والتأكيد على أنفسهم ( وَما كُنَّا غائِبِينَ ) عن أعمالهم حين عملوها بل كنّا شهودا عليهم حاضرين ـ علما ـ عند أعمالهم.` },
            { text: "فَلَنَسْـَٔلَنَّ ٱلَّذِينَ أُرْسِلَ إِلَيْهِمْ وَلَنَسْـَٔلَنَّ ٱلْمُرْسَلِينَ", tafsir: `` },
            { text: "فَلَنَقُصَّنَّ عَلَيْهِم بِعِلْمٍ وَمَا كُنَّا غَآئِبِينَ", tafsir: `` },
            { text: "وَٱلْوَزْنُ يَوْمَئِذٍ ٱلْحَقُّ فَمَن ثَقُلَتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ", tafsir: `للأعمال ( يَوْمَئِذٍ ) يوم القيامة ( الْحَقُ ) فلا ينقص حق ولا يزاد على حق ، وإنما توزن الأعمال بموازين عادلة ( فَمَنْ ثَقُلَتْ مَوازِينُهُ ) الصالحة ، وإنما جمع « الميزان » ، باعتبار كل عمل عمل ( فَأُولئِكَ ) الذين ثقلت موازينهم ( هُمُ الْمُفْلِحُونَ ) الذين فازوا بالسعادة الأبدية. وَمَنْ خَفَّتْ مَوازِينُهُ فَأُولئِكَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ بِما كانُوا بِآياتِنا يَظْلِمُونَ (9) وَلَقَدْ مَكَّنَّاكُمْ فِي الْأَرْضِ وَجَعَلْنا لَكُمْ فِيها مَعايِشَ قَلِيلاً ما تَشْكُرُونَ (10)` },
            { text: "وَمَنْ خَفَّتْ مَوَٰزِينُهُۥ فَأُو۟لَٰٓئِكَ ٱلَّذِينَ خَسِرُوٓا۟ أَنفُسَهُم بِمَا كَانُوا۟ بِـَٔايَٰتِنَا يَظْلِمُونَ", tafsir: `الصالحة بأن ثقلت موازين سيئاته ( فَأُولئِكَ الَّذِينَ خَسِرُوا أَنْفُسَهُمْ ) فإن النفس كانت لتحصيل الجنة ، فقد حصل الإنسان بها النار ( بِما كانُوا ) أي بسبب كونهم ( بِآياتِنا يَظْلِمُونَ ) أي بسبب جحودهم بما جاء به الرسل من الآيات. وهنا سؤال : ما هي طبيعة « الموازين » في الآية ؟ والجواب : من المحتمل أن يراد بها الموازين المعقولة لا المحسوسة ، كما يقال : وزنت فلان ، أو فلان خفيف الوزن ، أو فلان له وزن ، وهكذا. والله سبحانه يعلم قيمة الأعمال ، كما أنّا نعرف قيم بعض الأعمال ، فنقدر المهندس وعمله أكثر مما نقدر العامل. كما أن من المحتمل أن يراد بها الموازين المحسوسة بأن تتجسّم الأعمال ، فللصلاة صورة ووزن ، وهكذا لسائر الأعمال الخيرية والشرية ، ثم توزن في موازين كموازين الدنيا.` },
            { text: "وَلَقَدْ مَكَّنَّٰكُمْ فِى ٱلْأَرْضِ وَجَعَلْنَا لَكُمْ فِيهَا مَعَٰيِشَ قَلِيلًا مَّا تَشْكُرُونَ", tafsir: `كيف لا تخضعون لله سبحانه ، والحال أنه بالإضافة إلى نعمة إرسال الرسل والهداية ، ابتدأ عليكم بنعمة الحياة ؟ ف ( لَقَدْ مَكَّنَّاكُمْ ) أيها البشر ( فِي الْأَرْضِ ) بأن جعلنا الأرض تحت إرادتكم تبنون وتزرعون وتخرجون كنوزها ( وَجَعَلْنا لَكُمْ فِيها مَعايِشَ ) أي ما تعيشون به من أنواع الرزق ( قَلِيلاً ما تَشْكُرُونَ ) أي أن شكركم للنعم قليل. وَلَقَدْ خَلَقْناكُمْ ثُمَّ صَوَّرْناكُمْ ثُمَّ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ فَسَجَدُوا إِلاَّ إِبْلِيسَ لَمْ يَكُنْ مِنَ السَّاجِدِينَ (11) قالَ ما مَنَعَكَ أَلاَّ تَسْجُدَ إِذْ أَمَرْتُكَ قالَ` },
            { text: "وَلَقَدْ خَلَقْنَٰكُمْ ثُمَّ صَوَّرْنَٰكُمْ ثُمَّ قُلْنَا لِلْمَلَٰٓئِكَةِ ٱسْجُدُوا۟ لِـَٔادَمَ فَسَجَدُوٓا۟ إِلَّآ إِبْلِيسَ لَمْ يَكُن مِّنَ ٱلسَّٰجِدِينَ", tafsir: `قبل ذلك ( لَقَدْ خَلَقْناكُمْ ) أي أوجدنا أصلكم الذي هو التراب ، أو المني ، أو الدم ، بعد العدم ( ثُمَّ صَوَّرْناكُمْ ) أفضنا عليكم الصورة الإنسانية ، في رحم الأمهات ( ثُمَّ قُلْنا لِلْمَلائِكَةِ اسْجُدُوا لِآدَمَ ) إن أريد ب « ثم » معناها الظاهر ، كان المراد من « خلقناكم » خلقنا أسلافكم ، أي آدم عليه‌السلام ، ومن البلاغة أن ينسب الإنسان ما للآباء إلى الأبناء ، كما قال : ( فَلِمَ تَقْتُلُونَ أَنْبِياءَ اللهِ مِنْ قَبْلُ ) (1) ، بالنسبة إلى اليهود المعاصرين للرسول صلى‌الله‌عليه‌وآله‌وسلم ، وإن أريد بها الترتيب في الكلام ، نحو « إن من ساد ثم ساد أبوه » كان الخطاب في « خلقناكم » على ظاهره. وقد كان أمرنا بالسجود لآدم ـ جدكم ـ نعمة وتشريفا لكم ( فَسَجَدُوا إِلَّا إِبْلِيسَ ) الشيطان ، ويسمى إبليسا لأنه « أبلس » وحرم من رحمة الله سبحانه ( لَمْ يَكُنْ مِنَ السَّاجِدِينَ ) فإنه أبى واستكبر ، وهو لم يكن من الملائكة ، وإنما كان معهم فشمله الخطاب.` },
            { text: "قَالَ مَا مَنَعَكَ أَلَّا تَسْجُدَ إِذْ أَمَرْتُكَ قَالَ أَنَا۠ خَيْرٌ مِّنْهُ خَلَقْتَنِى مِن نَّارٍ وَخَلَقْتَهُۥ مِن طِينٍ", tafsir: `الله تعالى لإبليس ( ما مَنَعَكَ أَلَّا تَسْجُدَ ) « لا » زائدة في الكلام ، أي ما منعك أن تسجد ، وإنما يؤتى بها لنكتة بديعة ، هي قطع الكلام عما سبقه والابتداء بالكلام التالي ، ليتكرر التوبيخ كأنه قال « ما منعك » ؟ وحذف المتعلق ثم سكت هنيئة ، وابتدأ « أن لا تسجد » . ومثل هذا في المحاورات كثير ( إِذْ أَمَرْتُكَ ) بالسجود ( قالَ ) إبليس : ( 1) البقرة : 92. أَنَا خَيْرٌ مِنْهُ خَلَقْتَنِي مِنْ نارٍ وَخَلَقْتَهُ مِنْ طِينٍ (12) قالَ فَاهْبِطْ مِنْها فَما يَكُونُ لَكَ أَنْ تَتَكَبَّرَ فِيها فَاخْرُجْ إِنَّكَ مِنَ الصَّاغِرِينَ (13) قالَ أَنْظِرْنِي إِلى يَوْمِ يُبْعَثُونَ (14) قالَ إِنَّكَ مِنَ الْمُنْظَرِينَ (15) ( أَنَا خَيْرٌ مِنْهُ ) أي من آدم ، فلا ينبغي للأرفع أن يسجد ويتواضع للأخفض ، ثم علل كونه خيرا بقوله : ( خَلَقْتَنِي مِنْ نارٍ وَخَلَقْتَهُ ) أي خلقت آدم ( مِنْ طِينٍ ) والنار مضيئة والطين كدر. لكن قياسه كان باطلا إذ مجرد الإضاءة لا تكون سبب الأفضلية ، وإنما الأشياء بالكسر والانكسار ، وإعدام النار للأشياء بعكس الأرض المحيية لها جهة نقص فيها ، سبب لرفعة الأرض عليها ، بالإضافة إلى أن التواضع كان للآمر لا لآدم ، فمن أمر عبده بأن يحمل طبقا من طين على رأسه كان عمل العبد امتثالا للسيد لا تواضعا للطين.` },
            { text: "قَالَ فَٱهْبِطْ مِنْهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخْرُجْ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ", tafsir: `الله سبحانه لإبليس : ( فَاهْبِطْ ) أي اخرج خروجا انحداريا ـ إما منزلة أو حقيقة ـ ( مِنْها ) أي من الجنة ( فَما يَكُونُ لَكَ ) أي ليس لك حق ( أَنْ تَتَكَبَّرَ فِيها ) أي في الجنة لأنها ليست موضع المتكبرين ( فَاخْرُجْ إِنَّكَ مِنَ الصَّاغِرِينَ ) من « الصغار » وهو « الذلة » ، فإنك ذليل في مقام قربنا ، حقير عندنا.` },
            { text: "قَالَ أَنظِرْنِىٓ إِلَىٰ يَوْمِ يُبْعَثُونَ", tafsir: `إبليس لله سبحانه : ( أَنْظِرْنِي ) أي أمهلني لأن أبقى حيا ( إِلى يَوْمِ يُبْعَثُونَ ) أي يوم القيامة الذي يبعث فيه الخلق للجزاء.` },
            { text: "قَالَ إِنَّكَ مِنَ ٱلْمُنظَرِينَ", tafsir: `الله سبحانه : ( إِنَّكَ ) يا إبليس ( مِنَ الْمُنْظَرِينَ ) أي من الذين يمهلون ولا يعجل لهم بالموت ، ولعلّ المراد بسائر المنظرين « الملائكة » ـ أي أنت أيضا مثلهم في الإمهال ـ ولكن من المعلوم أنه قالَ فَبِما أَغْوَيْتَنِي لَأَقْعُدَنَّ لَهُمْ صِراطَكَ الْمُسْتَقِيمَ (16) ثُمَّ لَآتِيَنَّهُمْ مِنْ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمانِهِمْ وَعَنْ شَمائِلِهِمْ وَلا تَجِدُ أَكْثَرَهُمْ شاكِرِينَ (17) ليس الإنظار إلى يوم القيامة بل ( إِلى يَوْمِ الْوَقْتِ الْمَعْلُومِ ) .` },
            { text: "قَالَ فَبِمَآ أَغْوَيْتَنِى لَأَقْعُدَنَّ لَهُمْ صِرَٰطَكَ ٱلْمُسْتَقِيمَ", tafsir: `إبليس بعد إمهال الله سبحانه له ( فَبِما أَغْوَيْتَنِي ) أي بسبب إغوائك لي ، وليس المراد إغواءه سبحانه ، بل المراد الإتيان بسبب ، وأمره بأمر سبب غوايته ، وقد ذكرنا سابقا أن الأفعال إنما تنسب إليه سبحانه لأنه الخالق المهيئ للأسباب والوسائل ( لَأَقْعُدَنَّ لَهُمْ ) أي للبشر ( صِراطَكَ الْمُسْتَقِيمَ ) أي أقعد في طريقك لأغوي البشر عنه إلى الضلال والانحراف ، فإن إغوائي للبشر مقابل إغوائك لي ، وقد كان هذا القياس من الشيطان أيضا باطلا ، وهو مثل أن يعطي الأب ولديه رأس مال ، فيأخذ أحدهما رأس المال ويذهب به نحو الفساد ، ثم لما أتم ماله ، وبقي رأس مال أخيه يقول لأبيه ، كما سببت فسادي أسبب فساد أخي ، وهذا الكلام خارج عن المنطق ، إذ الأب لم يسبب فساده وإنما أراد صلاحه ، بخلاف عمله في فساد أخيه فإن الفاسد يسبب فساده.` },
            { text: "ثُمَّ لَـَٔاتِيَنَّهُم مِّنۢ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَٰنِهِمْ وَعَن شَمَآئِلِهِمْ وَلَا تَجِدُ أَكْثَرَهُمْ شَٰكِرِينَ", tafsir: `أي من قدامهم ( وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمانِهِمْ وَعَنْ شَمائِلِهِمْ ) وهذا من باب تشبيه المعقول بالمحسوس ، فكما يجلس اللص في طريق المسافرين ، ثم يهاجمهم من جميع جوانبهم الأربعة ليسرق ما معهم ، كذلك الشيطان يطوّق الإنسان ليضله عن طريق الله سبحانه ( وَلا تَجِدُ ) يا رب ( أَكْثَرَهُمْ ) أي أكثر البشر ( شاكِرِينَ ) لك ولنعمك ، بل يتبعون طريق الكفران ، فإن من عصى قالَ اخْرُجْ مِنْها مَذْؤُماً مَدْحُوراً لَمَنْ تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنْكُمْ أَجْمَعِينَ (18) وَيا آدَمُ اسْكُنْ أَنْتَ وَزَوْجُكَ الله سبحانه فقد كفر بنعمه وفضله. وهنا سؤال : لم أطلق الله سبحانه إبليس ليضل البشر ؟ والجواب : لأن الدنيا وضعت للاختبار ، ولو لم يكن الآمر بالشر كانت دنيا جبر وإكراه ، ولم يكن للمطيع فضل يستحق به الجنة. وسؤال ثان : أليس من الممكن أن يتفضل الله بالجنة على البشر بدون اختبار ؟ والجواب : كلّا ، إن الإنسان بالإطاعة يكون قابلا للدرجات ، كالتلميذ الذي يكون قابلا للتعليم ـ بالقراءة والامتحان ـ فلو لم تكن إطاعة لم تكن قابلية ، ومن المعلوم أن حرمان القابل لأجل غيره ظلم ، ألا ترى لو أن الحكومة لم تفتح المدرسة لتهذيب النفوس المستقيمة الذكية ، إشفاقا على البليد الذي يرسب ، كان ظلما للذكي النابه. والكلام طويل مذكور في كتب الكلام والفلسفة.` },
            { text: "قَالَ ٱخْرُجْ مِنْهَا مَذْءُومًا مَّدْحُورًا لَّمَن تَبِعَكَ مِنْهُمْ لَأَمْلَأَنَّ جَهَنَّمَ مِنكُمْ أَجْمَعِينَ", tafsir: `الله تعالى لإبليس : ( اخْرُجْ مِنْها ) أي من الجنة ( مَذْؤُماً ) من « ذأم يذأم » فهو « مذءوم » بمعنى : عاب ، فإن الذأم والذيم أشد العيب ( مَدْحُوراً ) أي مطرودا ، من « دحر » بمعنى : طرد ( لَمَنْ تَبِعَكَ مِنْهُمْ ) أي : أؤكد أن من تبعك من البشر ( لَأَمْلَأَنَ ) أي أملأ بالتأكيد ( جَهَنَّمَ مِنْكُمْ ) من التابع والمتبوع ( أَجْمَعِينَ ) بلا استثناء. [20] وبعد تمام الكلام مع الشيطان توجه الخطاب إلى آدم عليه‌السلام الذي خلقه سبحانه للاستخلاف في الأرض ( وَيا آدَمُ اسْكُنْ أَنْتَ وَزَوْجُكَ ) حواء الْجَنَّةَ فَكُلا مِنْ حَيْثُ شِئْتُما وَلا تَقْرَبا هذِهِ الشَّجَرَةَ فَتَكُونا مِنَ الظَّالِمِينَ (19) فَوَسْوَسَ لَهُمَا الشَّيْطانُ لِيُبْدِيَ لَهُما ما وُورِيَ عَنْهُما مِنْ سَوْآتِهِما وَقالَ ما نَهاكُما رَبُّكُما عَنْ هذِهِ ( الْجَنَّةَ ) هو أمر من « السكن » دون السكون ، والتقدير « ولتسكن زوجك » ( فَكُلا مِنْ حَيْثُ شِئْتُما ) من ثمار الجنة ( وَلا تَقْرَبا هذِهِ الشَّجَرَةَ ) بالأكل ، والنهي عن الاقتراب مبالغة في عدم الأكل ، نحو قوله سبحانه : ( وَلا تَقْرَبُوا مالَ الْيَتِيمِ ) (1) ، وقد تقدم الكلام حول ماهية الشجرة ، في سورة البقرة ( فَتَكُونا مِنَ الظَّالِمِينَ ) لأنفسكما ، والظلم كان لأجل أن الأكل يسبب خروجهما.` },
            { text: "وَيَٰٓـَٔادَمُ ٱسْكُنْ أَنتَ وَزَوْجُكَ ٱلْجَنَّةَ فَكُلَا مِنْ حَيْثُ شِئْتُمَا وَلَا تَقْرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "فَوَسْوَسَ لَهُمَا ٱلشَّيْطَٰنُ لِيُبْدِىَ لَهُمَا مَا وُۥرِىَ عَنْهُمَا مِن سَوْءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنْ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيْنِ أَوْ تَكُونَا مِنَ ٱلْخَٰلِدِينَ", tafsir: `أي لآدم وحواء ، ومعنى الوسوسة : الإلقاء في الذهن إلقاء مردّدا ، هل يفعل أو لا يفعل ( الشَّيْطانُ ) في أكل الشجرة ( لِيُبْدِيَ لَهُما ) أي ليظهر لهما ، و « اللام » للعاقبة ، نحو : ( فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَناً ) (2) ، ( ما وُورِيَ ) أي ما ستر من « وارى » على وزن « فاعل » ( عَنْهُما ) أي عن آدم وحواء ( مِنْ سَوْآتِهِما ) أي عورتيهما ، فقد كان آدم وحواء مستورين بألبسة الجنة وكان لازم إخراجهما إذا أكلا من الشجرة أن ينزع عنهما اللباس ، فكان عاقبة أكلهما إظهار عورتيهما ، وسميت العورة « سوءة » لأنها يسوء الإنسان ظهورها. ( وَقالَ ) الشيطان في وسوسته لهما ( ما نَهاكُما رَبُّكُما عَنْ هذِهِ ( 1) الإسراء : 35. ( 2) القصص : 9. الشَّجَرَةِ إِلاَّ أَنْ تَكُونا مَلَكَيْنِ أَوْ تَكُونا مِنَ الْخالِدِينَ (20) وَقاسَمَهُما إِنِّي لَكُما لَمِنَ النَّاصِحِينَ (21) فَدَلاَّهُما بِغُرُورٍ فَلَمَّا ذاقَا الشَّجَرَةَ بَدَتْ لَهُما سَوْآتُهُما وَطَفِقا يَخْصِفانِ عَلَيْهِما مِنْ وَرَقِ الْجَنَّةِ وَناداهُما رَبُّهُما أَ لَمْ الشَّجَرَةِ ) أي عن أكلها ( إِلَّا أَنْ تَكُونا مَلَكَيْنِ ) فليس النهي لأجل تحريم الأكل عليكما ، بل لأجل أن تبقيا في صورة البشر ـ المحببة إليكما ـ أما إذا لم تشاءا فلا مانع لله سبحانه عن أكلكما من الشجرة ، والحاصل أنه أوهمهما أن النهي ليس وراءه لوم ، وإنما هو نهي صلاح ( أَوْ تَكُونا مِنَ الْخالِدِينَ ) فمن أكل من الشجرة إما أن يصبح ملكا ، أو يكون إنسانا خالدا.` },
            { text: "وَقَاسَمَهُمَآ إِنِّى لَكُمَا لَمِنَ ٱلنَّٰصِحِينَ", tafsir: `أي حلف لهما بالله تعالى ، فإن « قاسم » و « أقسم » بمعنى الحلف ( إِنِّي لَكُما ) يا آدم وحواء ( لَمِنَ النَّاصِحِينَ ) فإني أنصحكم بالأكل لتكونا كسائر الملائكة ، أو تبقيا مخلدين في الجنة.` },
            { text: "فَدَلَّىٰهُمَا بِغُرُورٍ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمْ أَنْهَكُمَا عَن تِلْكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيْطَٰنَ لَكُمَا عَدُوٌّ مُّبِينٌ", tafsir: `أي دلّى الشيطان آدم وحواء ، من « تدلية الدلو » وهو أن ترسلها في البئر ، بمعنى دلاهما من الجنة إلى الأرض ( بِغُرُورٍ ) أي بما غرّهما من الكلام والقسم ( فَلَمَّا ذاقَا الشَّجَرَةَ ) بأن أكلا منها شيئا يسيرا انتزعت ملابسهما و ( بَدَتْ لَهُما سَوْآتُهُما ) أي ظهرت عورتاهما ( وَطَفِقا ) أي شرعا ( يَخْصِفانِ ) أي يجمعان من « الخصف » بمعنى الجمع ( عَلَيْهِما ) أي على أنفسهما ( مِنْ وَرَقِ الْجَنَّةِ ) فقد أخذا من أوراق شجرة التين ، وجعلا يلفان على عورتيهما ( وَناداهُما رَبُّهُما أَ لَمْ أَنْهَكُما عَنْ تِلْكُمَا الشَّجَرَةِ وَأَقُلْ لَكُما إِنَّ الشَّيْطانَ لَكُما عَدُوٌّ مُبِينٌ (22) قالا رَبَّنا ظَلَمْنا أَنْفُسَنا أَنْهَكُما عَنْ تِلْكُمَا الشَّجَرَةِ ) أي عن تناول هذه الشجرة ، فلما ذا أكلتما منها ؟ ( وَ ) ألم ( أَقُلْ لَكُما إِنَّ الشَّيْطانَ لَكُما عَدُوٌّ مُبِينٌ ) ؟ أي عدو ظاهر ، فلم سمعتما كلامه ؟ وهنا سؤال : كيف يمكن لمثل آدم النبي المعصوم عليه‌السلام أن يترك قول الله سبحانه : ( لا تَقْرَبا هذِهِ الشَّجَرَةَ فَتَكُونا مِنَ الظَّالِمِينَ ) (1) ، ويأخذ بقول الشيطان القائل : ( إِلَّا أَنْ تَكُونا مَلَكَيْنِ أَوْ تَكُونا مِنَ الْخالِدِينَ ) ؟ والجواب : إن الظلم هو وضع الشيء في غير موضعه ، ولعل آدم وحواء ظنا أن المراد بالظلم أن يكونا ملكين وبالأخص لما حلف الشيطان لهما ، فإنهما لم يكونا يحتملان أن أحدا يحلف بالله كاذبا ـ كما في الحديث ـ. وقد تكرر استعمال الظلم لوضع الشيء غير موضعه ، وإن لم يكن فيه غضاضة أصلا ، كما قال سبحانه حكاية عن موسى : ( ظَلَمْتُ نَفْسِي ) (2) ، ولعلهما ظنا أن الأصلح بحالهما أن يبقيا بشرا ـ حسب كلام الله ـ لكنهما شاءا الجائز ، كما يترك الإنسان كثيرا ما الأصلح لما يجده أوفق بحاله ، وهذا مما لا ينافي مقام العصمة إطلاقا.` },
            { text: "قَالَا رَبَّنَا ظَلَمْنَآ أَنفُسَنَا وَإِن لَّمْ تَغْفِرْ لَنَا وَتَرْحَمْنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ", tafsir: `أي قال آدم وحواء عليهما‌السلام : ( رَبَّنا ظَلَمْنا أَنْفُسَنا ) بارتكاب ( 1) البقرة : 36. ( 2) القصص : 17. وَإِنْ لَمْ تَغْفِرْ لَنا وَتَرْحَمْنا لَنَكُونَنَّ مِنَ الْخاسِرِينَ (23) المنهي عنه وأكل الشجرة ( وَإِنْ لَمْ تَغْفِرْ لَنا ) أي تستر علينا ، وهو كناية عن العفو عما صدر ( وَتَرْحَمْنا ) أي تتفضل علينا برحمتك ( لَنَكُونَنَّ مِنَ الْخاسِرِينَ ) الذين خسروا بعض درجاتهم. وحيث تقرر عقلا ونقلا أن الأنبياء معصومون ، كان اللازم القول بعدم كون أكل الشجرة معصية إطلاقا ، وإنما كان النهي للإرشاد ، كما يقول الطبيب للمريض : « لا تشرب هذا المائع فيطول مرضك » ، فإنه نهي للإرشاد ، ويكون ارتكابه موجبا لطول المرض فقط ، وليس هذا مما يوجب العقاب. وكذلك كان النهي بالنسبة إلى أكل الشجرة ، لأنه كان لإرشادهما إلى البقاء في الجنة أبدا ، كما قال سبحانه : ( إِنَّ لَكَ أَلَّا تَجُوعَ فِيها وَلا تَعْرى * وَأَنَّكَ لا تَظْمَؤُا فِيها وَلا تَضْحى ) (1) ، وكان الأكل موجبا للخروج من الجنة ، ولقاء مشاكل الدنيا ، والظلم ـ كما تقدم ـ هو وضع الشيء في غير موضعه ويلائم ارتكاب المنهي إرشادا ، كما يلائم القبيح ، كما أن الغفران هو الستر ، وهو يلائم العصيان ويلائم ارتكاب المنهي الإرشادي ، والخسران يلائم عدم الربح المتوقع ، ولذا يقول التاجر : « خسرت » فيما إذا لم يربح المتوقع. ألا ترى أن المريض إذا ارتكب ما يسبب طول مرضه ، يقول للطبيب : « اشتبهت ، فتدارك الأمر ، وإلا خسرت صحتك في هذه المدة » ولم يكن ذلك عصيانا إطلاقا. ومن هنا اشتهر في تسمية هذا النوع من الخلاف ب « ترك الأولى » أي أن الأولى كان عدم الارتكاب ، وهنا سؤالان : ( 1) طه : 119 و 120. قالَ اهْبِطُوا بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِي الْأَرْضِ مُسْتَقَرٌّ وَمَتاعٌ الأول : كيف يصدر مثل هذا الترك من الأنبياء ولهم المقام الرفيع ؟ الثاني : إن هذا فتح لباب التأويل وارتكاب خلاف الظاهر ولا داعي له ؟ والجواب عن الأول : أن ذلك لئلّا يعتقد البشر ألوهية الأنبياء ، فإن من عادة البشر الغلو بالنسبة إلى القديسين ، وذلك ضد الغلو ، وإن غالى بعض الضعاف أيضا. والجواب عن الثاني : إن فتح هذا الباب مما لا بد منه ، فإن الكلام مشتمل على المجاز والكناية وما أشبه ـ حتّى بالنسبة إلى كلام البشر العادي ، فكيف بالبلغاء ـ وإلّا لزم القول بالتجسيم لقوله سبحانه : ( إِلى رَبِّها ناظِرَةٌ ) (1) ، والظلم لقوله : ( مَنْ يُضْلِلِ اللهُ ) (2) ، والكذب لقوله : ( وَما رَمَيْتَ إِذْ رَمَيْتَ ) (3) ، إلى غير ذلك. وقد جرت قوانين البلاغة على أن يصرف الكلام إلى المراد منه ، وإن كان خلاف الظاهر اللفظي ، إذا دل دليل من العقل والنقل على المراد ، أما إذا لم يكن هناك دليل ، أخذ بظاهر الألفاظ.` },
            { text: "قَالَ ٱهْبِطُوا۟ بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ وَلَكُمْ فِى ٱلْأَرْضِ مُسْتَقَرٌّ وَمَتَٰعٌ إِلَىٰ حِينٍ", tafsir: `الله سبحانه لآدم وحواء وإبليس : ( اهْبِطُوا ) من الجنة هبوطا نحو الأسفل حيث كانت الجنة أعلى من الأرض ، أو هبوطا رتبيّا ، إن كانت من جنان الدنيا ( بَعْضُكُمْ لِبَعْضٍ عَدُوٌّ ) فالشيطان عدوّ لهما وهما عدوّان له ، وبين المرأة والرجل تنافس وتجاذب ( وَلَكُمْ ) جميعا ( فِي الْأَرْضِ مُسْتَقَرٌّ ) أي محل قرار ( وَمَتاعٌ ) تتمتعون به من المأكل ( 1) القيامة : 24. ( 2) النساء : 89. ( 3) الأنفال : 18. إِلى حِينٍ (24) قالَ فِيها تَحْيَوْنَ وَفِيها تَمُوتُونَ وَمِنْها تُخْرَجُونَ (25) يا بَنِي آدَمَ قَدْ أَنْزَلْنا عَلَيْكُمْ لِباساً يُوارِي سَوْآتِكُمْ وَرِيشاً وَلِباسُ التَّقْوى والملبس وغيرهما ( إِلى حِينٍ ) الموت أو حين البعث.` },
            { text: "قَالَ فِيهَا تَحْيَوْنَ وَفِيهَا تَمُوتُونَ وَمِنْهَا تُخْرَجُونَ", tafsir: `الله تعالى ثانيا : ( فِيها ) أي في الأرض ( تَحْيَوْنَ ) أي تعيشون ، أو المراد يحيى لك نسل ( وَفِيها تَمُوتُونَ ) جميعا ( وَمِنْها ) أي من الأرض ( تُخْرَجُونَ ) يوم القيامة للحساب والجزاء. [27] ثم خاطب الله سبحانه البشر ، بمناسبة نزع الشيطان لباس أبويهم ، وبمناسبة ما وعد من أن لهم في الأرض متاع ، بقوله : ( يا بَنِي آدَمَ ) والخطاب بهذا اللفظ للتذكير بجدّهم آدم عليه‌السلام ـ لمناسبة الموضوع ـ ( قَدْ أَنْزَلْنا عَلَيْكُمْ لِباساً ) إما المراد « الإنزال » حقيقة ، بأن أنزل اللباس من الجنة ، أو « الإنزال » مجازا بنزول المطر الذي هو سبب نبات القطن وما أشبه ، ورعي الحيوانات ذات الأصواف ، أو المراد « التعظيم » لعظم المعطي ، كما يقال : « رفعت عريضتي إلى القاضي » تعظيما لمقامه وأنه أرفع منزلة من صاحب العريضة ، ومثله ( وَأَنْزَلَ لَكُمْ مِنَ الْأَنْعامِ ثَمانِيَةَ أَزْواجٍ ) (1) ، ( وَأَنْزَلْنَا الْحَدِيدَ ) (2) ، ( أَنْزَلَ اللهُ إِلَيْكُمْ ذِكْراً* رَسُولاً ) (3) ، ( يُوارِي ) أي يستر ( سَوْآتِكُمْ ) أي عوراتكم ( وَ ) أنزلنا عليكم ( رِيشاً ) أي أثاثا مما تحتاجون إليه ، و « الريش » ما فيه الجمال ، ومنه ريش الطائر ( وَلِباسُ التَّقْوى ) أي الاجتناب عن معاصي الله سبحانه ، وسمي لباسا لأنه يستر الشر الكامن في نفس الإنسان ، كما يستر اللباس ( 1) الزمر : 7. ( 2) الحديد : 26. ( 3) الطلاق : 11 و 12. ذلِكَ خَيْرٌ ذلِكَ مِنْ آياتِ اللهِ لَعَلَّهُمْ يَذَّكَّرُونَ (26) يا بَنِي آدَمَ لا يَفْتِنَنَّكُمُ الشَّيْطانُ كَما أَخْرَجَ أَبَوَيْكُمْ مِنَ الْجَنَّةِ يَنْزِعُ عَنْهُما لِباسَهُما لِيُرِيَهُما سَوْآتِهِما مواضع القبح من بدن الإنسان ، فمثلا من يغتاب غيره يظهر قبح نفسه ، فإذا اتقى سترت هذه التقوى قبحه النفسي ( ذلِكَ خَيْرٌ ) من جميع أنواع اللباس الظاهرة ، إذ القبائح النفسية أكثر وأبشع من القبائح البدنية ، لأن القبائح الكامنة إذا ظهرت توجب النار والخزي بخلاف قبائح الجسد ( ذلِكَ ) أي لباس التقوى ( مِنْ آياتِ اللهِ ) « من » إما للإنشاء ، أي أن لباس التقوى ينشأ من الآيات والحجج التي أنزلها الله سبحانه ، وإما تبعيضية أي أن التقوى من جملة آيات الله وعلاماته ، لأنه هو الذي أمر بالتقوى ( لَعَلَّهُمْ يَذَّكَّرُونَ ) أي جعل الله التقوى آية لكي يتفكر الإنسان ، ويتذكر فيما أودع في فطرته ، فيسعد.` },
            { text: "يَٰبَنِىٓ ءَادَمَ قَدْ أَنزَلْنَا عَلَيْكُمْ لِبَاسًا يُوَٰرِى سَوْءَٰتِكُمْ وَرِيشًا وَلِبَاسُ ٱلتَّقْوَىٰ ذَٰلِكَ خَيْرٌ ذَٰلِكَ مِنْ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمْ يَذَّكَّرُونَ", tafsir: `` },
            { text: "يَٰبَنِىٓ ءَادَمَ لَا يَفْتِنَنَّكُمُ ٱلشَّيْطَٰنُ كَمَآ أَخْرَجَ أَبَوَيْكُم مِّنَ ٱلْجَنَّةِ يَنزِعُ عَنْهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوْءَٰتِهِمَآ إِنَّهُۥ يَرَىٰكُمْ هُوَ وَقَبِيلُهُۥ مِنْ حَيْثُ لَا تَرَوْنَهُمْ إِنَّا جَعَلْنَا ٱلشَّيَٰطِينَ أَوْلِيَآءَ لِلَّذِينَ لَا يُؤْمِنُونَ", tafsir: `أي لا يضلنّكم بأن يدعوكم إلى المعاصي فتجيبوه فيحرمكم من السعادة والجنة ( كَما أَخْرَجَ أَبَوَيْكُمْ ) آدم وحواء ( مِنَ الْجَنَّةِ ) ونسبة الإخراج إليه لأنه كان بإغوائه ووسوسته ، إخراجا بصورة بشعة حيث كان ( يَنْزِعُ عَنْهُما لِباسَهُما ) والنزع وإن كان من فعله سبحانه ، إلّا أنه حيث كان بسبب الوسوسة ، صح الانتساب إليه ، كما قال سبحانه عن فرعون : ( يُذَبِّحُ أَبْناءَهُمْ ) (1) ، مع أن الذبح كان من فعل جنود فرعون ( لِيُرِيَهُما سَوْآتِهِما ) أي عورتيهما. ولعل السر في تكرار هذه اللفظة تركيز البشاعة في نفس السامع ، فمن يرغب في أن تبدو سوءته ؟ ( 1) القصص : 5. إِنَّهُ يَراكُمْ هُوَ وَقَبِيلُهُ مِنْ حَيْثُ لا تَرَوْنَهُمْ إِنَّا جَعَلْنَا الشَّياطِينَ أَوْلِياءَ لِلَّذِينَ لا يُؤْمِنُونَ (27) وَإِذا فَعَلُوا فاحِشَةً قالُوا وَجَدْنا وحيث كان هنا محل سؤال : أنه كيف يفتن الشيطان الإنسان ولا يراه ؟ قال سبحانه : ( إِنَّهُ يَراكُمْ هُوَ وَقَبِيلُهُ ) أي نسله ، فإن للشيطان نسلا كما للإنسان ، كما قال سبحانه ( أَ فَتَتَّخِذُونَهُ وَذُرِّيَّتَهُ أَوْلِياءَ ) (1) ، ( مِنْ حَيْثُ لا تَرَوْنَهُمْ ) فإنهم من جنس لطيف لا يرى بالعين المجردة ، كالهواء اللطيف الذي لا يرى ، وإن أحس به الإنسان. ومن قال : إنه كيف يأمر بذلك ؟ فالجواب : إن هذه الإلقاءات في القلب بالشر ، كلها منه ، كما أن الإلقاءات الخيرة من الملائكة ـ كما في الأحاديث ـ وإلا فمن أين هذه الإلقاءات ؟! ( إِنَّا جَعَلْنَا الشَّياطِينَ أَوْلِياءَ لِلَّذِينَ لا يُؤْمِنُونَ ) ومعنى « جعله » سبحانه : التخلية بينهم وبين الشياطين ، ومعنى كونهم أولياء : أنهم يتبعونهم ، ويتخذونهم محل الولي الحميم في التصادق معهم دون المؤمنين. [29] والذين لا يؤمنون بالإضافة إلى أنهم اتخذوا الشيطان وليا ، إنهم مقلّدون تقليدا أعمى ، كاذبون في أقوالهم ، عالمون بالفحشاء ، فهم مجمع الرذائل حيث تركوا الإيمان ( وَإِذا فَعَلُوا ) أي فعل الذين لا يؤمنون ( فاحِشَةً ) أي خصلة فاحشة ، متعدية عن الحق ، فإن « فحش » بمعنى « تعدّى » ، وهذا عام شامل لجميع المعاصي ( قالُوا وَجَدْنا ( 1) الكهف : 51. عَلَيْها آباءَنا وَاللهُ أَمَرَنا بِها قُلْ إِنَّ اللهَ لا يَأْمُرُ بِالْفَحْشاءِ أَ تَقُولُونَ عَلَى اللهِ ما لا تَعْلَمُونَ (28) قُلْ أَمَرَ رَبِّي بِالْقِسْطِ وَأَقِيمُوا وُجُوهَكُمْ عِنْدَ كُلِّ مَسْجِدٍ عَلَيْها ) أي على هذه الفاحشة ( آباءَنا ) فإنا نقلّدهم في عملهم هذا ( وَاللهُ أَمَرَنا بِها ) أي بهذه الفاحشة ـ وكان قولهم هذا كذبا ـ ( قُلْ ) يا رسول الله لهم : ( إِنَّ اللهَ لا يَأْمُرُ بِالْفَحْشاءِ ) ثم ردّ عليهم من وجه آخر هو : ( أَ تَقُولُونَ عَلَى اللهِ ما لا تَعْلَمُونَ ) على نحو الاستفهام الإنكاري. وقد ورد في التفسير : أن الآية نزلت بمناسبة ما كان يفعله المشركون ، فإنهم كانوا يبدون سوءاتهم في طوافهم ، فكان يطوف الرجال والنساء عراة ، يقولون : نطوف كما ولدتنا أمهاتنا ولا نطوف في الثياب التي قارفنا فيها الذنوب ، وكانت المرأة تضع على قبلها النسعة في الطواف وتقول : اليوم يبدو بعضه أو كلّه و ما بدا منه فلا أحلّه تعني « العورة » ، فكان التذكير بذلك بمناسبة إنعام الله على بني آدم باللباس ، وفي سياق نزع إبليس لباس آدم وحواء عليهما‌السلام .` },
            { text: "وَإِذَا فَعَلُوا۟ فَٰحِشَةً قَالُوا۟ وَجَدْنَا عَلَيْهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ ٱللَّهَ لَا يَأْمُرُ بِٱلْفَحْشَآءِ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `` },
            { text: "قُلْ أَمَرَ رَبِّى بِٱلْقِسْطِ وَأَقِيمُوا۟ وُجُوهَكُمْ عِندَ كُلِّ مَسْجِدٍ وَٱدْعُوهُ مُخْلِصِينَ لَهُ ٱلدِّينَ كَمَا بَدَأَكُمْ تَعُودُونَ", tafsir: `يا رسول الله لهؤلاء الذين إذا فعلوا الفاحشة قالوا إن الله أمرنا بها : ( أَمَرَ رَبِّي بِالْقِسْطِ ) أي بالعدل والحق ، لا بالفحش والتجاوز ( وَأَقِيمُوا وُجُوهَكُمْ عِنْدَ كُلِّ مَسْجِدٍ ) فلا تتخذوا الشيطان وليا ، كالمشركين ، وهذا إما عطف على « أمر ربي » أي قل : أقيموا ، وإما عطف على « لا يفتننكم الشيطان » . ولعله المناسب للمعنى ، وهو أن وَادْعُوهُ مُخْلِصِينَ لَهُ الدِّينَ كَما بَدَأَكُمْ تَعُودُونَ (29) فَرِيقاً هَدى وَفَرِيقاً حَقَّ عَلَيْهِمُ الضَّلالَةُ إِنَّهُمُ اتَّخَذُوا الشَّياطِينَ أَوْلِياءَ مِنْ دُونِ اللهِ وَيَحْسَبُونَ أَنَّهُمْ مُهْتَدُونَ (30) الله يأمر بالقسط ، وبالإخلاص ، أو للقصة ، وهو أن اللازم إقامة الوجه ، لا إقامة الفرج ـ كما كانوا يطوفون عراة ـ. وذكر بعض المفسرين أن هذه الآية هدم لما كان أهل الجاهلية يلتزمون به من اختصاص الشعائر بقبيلة دون قبيلة ، فكان لهذا صنم ولذاك صنم ولهذه كعبة ولتلك كعبة ، فإن الإسلام يرى المساجد كلها لله ، واللازم على المسلم أن لا يفرق بينها ، أو أنه في قبال المسيحيين الذين كان لكل طائفة منهم كنيسة. ( وَادْعُوهُ ) أي ادعوا الله ( مُخْلِصِينَ لَهُ الدِّينَ ) أي ليكن دعاؤكم في حال كونكم أخلصتم له دينكم ( كَما بَدَأَكُمْ ) أي خلقكم ( تَعُودُونَ ) فهو وحده الذي خلق ويعيد ، فلا معنى لأن يشرك به غيره. [31] إنكم ستعودون فريقين ( فَرِيقاً هَدى ) أي هداه الله سبحانه ( وَفَرِيقاً حَقَ ) أي ثبت ( عَلَيْهِمُ الضَّلالَةُ ) لأنهم أعرضوا عن الهداية وسلكوا سبيل الغواية ، وإنما ضلوا بسبب ( إِنَّهُمُ اتَّخَذُوا الشَّياطِينَ أَوْلِياءَ مِنْ دُونِ اللهِ ) فكانوا يتبعون أوامر الشياطين لا أوامر الله سبحانه ، ولذا ضلوا ( وَ ) من اللطيف أنهم ( يَحْسَبُونَ ) أي يظنون ويزعمون ( أَنَّهُمْ مُهْتَدُونَ ) وأن طريقتهم حق. [32] وبمناسبة ذكر المسجد يأتي الحكم حول أمر مرتبط بالمسجد كما أن بمناسبة ذكر المحرمات سابقا يأتي بيان الحرام والحلال ، وبيان أن يا بَنِي آدَمَ خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ وَكُلُوا وَاشْرَبُوا وَلا تُسْرِفُوا إِنَّهُ لا يُحِبُّ الْمُسْرِفِينَ (31) الطيب غير محرم وإنما حرّم الخبيث لمصلحة الإنسان ( يا بَنِي آدَمَ ) خطاب لكل مكلف من أبناء آدم وحواء ( خُذُوا زِينَتَكُمْ عِنْدَ كُلِّ مَسْجِدٍ ) أي ثيابكم التي تتزيّنون بها ، خذوها وألبسوها إذا أردتم الذهاب إلى المسجد. روي أن الحسن بن علي عليهما‌السلام كان إذا قام إلى الصلاة لبس أجود ثيابه. فقيل له : يا بن رسول الله ! لم تلبس أجود ثيابك ؟ فقال : « إن الله جميل يحب الجمال فأتجمل لربي ، وهو يقول : خذوا زينتكم عند كل مسجد ، فأحب أن ألبس أجود ثيابي » (1) . والظاهر أن الآية عامة تشمل غير الثياب أيضا ولذا روي عن الصادق عليه‌السلام ، تفسيرها ب « التمشيط » (2) . ( وَكُلُوا وَاشْرَبُوا ) أي مباح لكم المأكول والمشروب ، فإن الأمر هنا للإباحة ( وَلا تُسْرِفُوا ) في الأكل والشرب ، أو في كل شيء ، والإسراف هو التجاوز ، فقد يصل إلى حد المكروه ، وقد يصل إلى حد الحرام ( إِنَّهُ ) تعالى ( لا يُحِبُّ الْمُسْرِفِينَ ) أي يكرههم ويبغضهم. ولعل التعبير ب « لا يحب » لبيان أن الله سبحانه لعلوّ مقامه وعظمته فيجب على الإنسان أن يجتنب ما لا يحبّه ، فكيف بما يكرهه ، وقد جرى ديدن العظماء أن يعبروا ب « لا أحب » فيما لا يريدونه. ( 1) وسائل الشيعة : ج 4 ص 455. ( 2) وسائل الشيعة : ج 2 ص 122. قُلْ مَنْ حَرَّمَ زِينَةَ اللهِ الَّتِي أَخْرَجَ لِعِبادِهِ وَالطَّيِّباتِ مِنَ الرِّزْقِ قُلْ هِيَ لِلَّذِينَ آمَنُوا فِي الْحَياةِ الدُّنْيا خالِصَةً يَوْمَ الْقِيامَةِ كَذلِكَ نُفَصِّلُ الْآياتِ لِقَوْمٍ يَعْلَمُونَ (32)` },
            { text: "فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيْهِمُ ٱلضَّلَٰلَةُ إِنَّهُمُ ٱتَّخَذُوا۟ ٱلشَّيَٰطِينَ أَوْلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحْسَبُونَ أَنَّهُم مُّهْتَدُونَ", tafsir: `` },
            { text: "يَٰبَنِىٓ ءَادَمَ خُذُوا۟ زِينَتَكُمْ عِندَ كُلِّ مَسْجِدٍ وَكُلُوا۟ وَٱشْرَبُوا۟ وَلَا تُسْرِفُوٓا۟ إِنَّهُۥ لَا يُحِبُّ ٱلْمُسْرِفِينَ", tafsir: `` },
            { text: "قُلْ مَنْ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِىٓ أَخْرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزْقِ قُلْ هِىَ لِلَّذِينَ ءَامَنُوا۟ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا خَالِصَةً يَوْمَ ٱلْقِيَٰمَةِ كَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَعْلَمُونَ", tafsir: `يا رسول الله : ( مَنْ حَرَّمَ زِينَةَ اللهِ الَّتِي أَخْرَجَ لِعِبادِهِ ) جميع أنواع الزينة من المساكن والمتنزهات والحليّ والملابس والمراكب وغيرها ( وَالطَّيِّباتِ مِنَ الرِّزْقِ ) المأكل الحلال ، أو المراد : كل رزق ، والاستفهام على سبيل الإنكار ، أي أنها ليست بمحرمة ولا حق لأحد في تحريمها ، فما يفعله الرهبان ليس صحيحا. ( قُلْ ) يا رسول الله ( هِيَ ) أي الزينة والطيبات ـ باعتبار كل واحد منهما ـ ( لِلَّذِينَ آمَنُوا فِي الْحَياةِ الدُّنْيا ) فما يتناوله الكفار منها حرام لا يجوز ، في حال كونها ( خالِصَةً ) للمؤمنين بلا مشاركة الكافرين لهم إطلاقا ـ حتى على وجه الحرام ـ ( يَوْمَ الْقِيامَةِ ) فإن الطيبات للمؤمنين في الدنيا وفي الآخرة ، لكن الكفار يشاركون المؤمنين زورا في الدنيا ، ولا يقدرون على ذلك في الآخرة ، وهناك احتمال آخر : أي أن الطيبات خالصة في الآخرة لمن آمن في الدنيا ، فتكون جملة واحدة ، لا جملتان ، ثم لا يخفى أن كون الطيبات للمؤمن في الدنيا ـ على المعنى الأول ـ لا يقتضي جواز تناولها من يد الكافر غير الحربي ، بحجة أنها ليست له ، فإن الله سبحانه جعل في الدنيا لغير الحربي حرمة ، لأجل استقامة أمور العالم. ( كَذلِكَ ) أي كما فصلنا الأمور السابقة ، واضحة لا لبس فيها ( نُفَصِّلُ الْآياتِ ) الدالة على الأصول والفروع ( لِقَوْمٍ يَعْلَمُونَ ) فإن العلماء هم الذين يستفيدون من هذه الآيات. قُلْ إِنَّما حَرَّمَ رَبِّيَ الْفَواحِشَ ما ظَهَرَ مِنْها وَما بَطَنَ وَالْإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللهِ ما لَمْ يُنَزِّلْ بِهِ سُلْطاناً وَأَنْ تَقُولُوا عَلَى اللهِ ما لا تَعْلَمُونَ (33) [34] ولما بيّن سبحانه المحللات عطف عليها المحرمات ، فقال : ( قُلْ ) يا رسول الله : ( إِنَّما حَرَّمَ رَبِّيَ الْفَواحِشَ ) جمع « فاحشة » أي الخصلة الفاحشة ، المتعدّية عن الحق ، من « فحش » بمعنى تعدّى ، والمراد بها : كل منكر ( ما ظَهَرَ مِنْها وَما بَطَنَ ) أي ما أعلن أو أخفي. ثم بيّن سبحانه بعض أفراد الفاحشة لأهميتها ( وَالْإِثْمَ ) أي الخمر ، فإنه من أسمائها قال الشاعر : شربت الإثم حتى زال عقلي كذاك الإثم يفعل بالعقول ( وَالْبَغْيَ ) أي الظلم ( بِغَيْرِ الْحَقِ ) هذا قيد توضيحي ، لإفادة أن البغي ليس بحق ، كقوله سبحانه : ( وَيَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ حَقٍ ) (1) ، ( وَأَنْ تُشْرِكُوا بِاللهِ ) أي حرّم سبحانه الشرك ( ما لَمْ يُنَزِّلْ بِهِ سُلْطاناً ) أي لم يقم له دليل ، وكل شرك كذلك ، فالقيد توضيحي لبيان أن الإشراك ليس بأمر الله ، خلافا لما كان المشركون ينسبون شركهم إليه سبحانه ( وَأَنْ تَقُولُوا عَلَى اللهِ ما لا تَعْلَمُونَ ) أي أنه تعالى حرم نسبة ما لا تعلمون إليه ، خلافا للكفار حيث أنهم كانوا يفعلون المعاصي ويقولون : « أمرنا الله بها » . [35] ثم سلّى سبحانه نبيه ، بأن لا يضيق صدره بما يفعله الكفار ، من ( 1) آل عمران : 22. وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذا جاءَ أَجَلُهُمْ لا يَسْتَأْخِرُونَ ساعَةً وَلا يَسْتَقْدِمُونَ (34) يا بَنِي آدَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِنْكُمْ يَقُصُّونَ عَلَيْكُمْ آياتِي اقتراف هذه الجرائم كلها بقوله تعالى : ( وَلِكُلِّ أُمَّةٍ أَجَلٌ ) أي لكل جماعة وأهل عصر ومصر مدة لا يتجاوزونها ، ولهؤلاء مدة ، ثم يلفّهم الموت ، وينسيهم البلى ، وستطهر الأرض منهم ( فَإِذا جاءَ أَجَلُهُمْ ) بأن توجه الأجل إليهم ( لا يَسْتَأْخِرُونَ ساعَةً ) أي لا يتأخرون مقدارا من الزمن ، فإن « الساعة » في اللغة بمعنى : مقدار الزمان قصر أم طال ( وَلا يَسْتَقْدِمُونَ ) أي لا يتقدمون على موعدهم ، فإذا قدّر هلاك أمة في الساعة الرابعة من يوم الجمعة ، فإذا توجه الأجل إليهم في الصباح لا يتأخرون إلى الساعة الخامسة ، ولا يتقدمون إلى الساعة الثالثة. والظاهر أن الفعلين بمعنى « الاستفعال » ، أي لا يطلبون ـ طلبا مفيدا ـ التقديم والتأخير ، وليس « جاء » بمعنى « وقع » حتى يقال : إن التقديم والتأخير لا يعقل بالنسبة إلى الأمر الواقع ، وليس في الكلام مجاز المشارفة ، إذ « جاء » لفظ يقع بالنسبة إلى الواصل ، وبالنسبة إلى من في الطريق.` },
            { text: "قُلْ إِنَّمَا حَرَّمَ رَبِّىَ ٱلْفَوَٰحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَٱلْإِثْمَ وَٱلْبَغْىَ بِغَيْرِ ٱلْحَقِّ وَأَن تُشْرِكُوا۟ بِٱللَّهِ مَا لَمْ يُنَزِّلْ بِهِۦ سُلْطَٰنًا وَأَن تَقُولُوا۟ عَلَى ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `` },
            { text: "وَلِكُلِّ أُمَّةٍ أَجَلٌ فَإِذَا جَآءَ أَجَلُهُمْ لَا يَسْتَأْخِرُونَ سَاعَةً وَلَا يَسْتَقْدِمُونَ", tafsir: `` },
            { text: "يَٰبَنِىٓ ءَادَمَ إِمَّا يَأْتِيَنَّكُمْ رُسُلٌ مِّنكُمْ يَقُصُّونَ عَلَيْكُمْ ءَايَٰتِى فَمَنِ ٱتَّقَىٰ وَأَصْلَحَ فَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ", tafsir: `خطاب لعموم المكلفين ( إِمَّا يَأْتِيَنَّكُمْ ) أي إن أتاكم ، فإن « إما » مركبة من « إن » الشرطية و « ما » الزائدة ( رُسُلٌ مِنْكُمْ ) لا يقال : لا رسول بعد النبي صلى‌الله‌عليه‌وآله‌وسلم فما معنى ذلك ؟ قلت : إن الشرط قد يصاغ لإفادة التحقيق ، فهو إنشاء مفهوم الشرط لغرض آخر ، كما ينشأ مفهوم التعجب والأمر والاستفهام ، لأغراض أخرى ، فالمراد ـ هنا ـ أن الرسل تأتي لتبين للناس ، فمن أطاع سعد ، ومن خالف شقي ( يَقُصُّونَ عَلَيْكُمْ ) أي يخبرونكم ( آياتِي ) وأحكامي فإن « قص » بمعنى « اتبع فَمَنِ اتَّقى وَأَصْلَحَ فَلا خَوْفٌ عَلَيْهِمْ وَلا هُمْ يَحْزَنُونَ (35) وَالَّذِينَ كَذَّبُوا بِآياتِنا وَاسْتَكْبَرُوا عَنْها أُولئِكَ أَصْحابُ النَّارِ هُمْ فِيها خالِدُونَ (36) فَمَنْ أَظْلَمُ مِمَّنِ افْتَرى عَلَى اللهِ كَذِباً أَوْ كَذَّبَ بِآياتِهِ أُولئِكَ يَنالُهُمْ نَصِيبُهُمْ مِنَ الْكِتابِ الأثر » ، فالنقل عن الله سبحانه قصة عنه ( فَمَنِ اتَّقى ) إنكار الرسل والآيات ، أو اتقى المعاصي ( وَأَصْلَحَ ) عمل صالحا ( فَلا خَوْفٌ عَلَيْهِمْ ) كخوف سائر الناس ( وَلا هُمْ يَحْزَنُونَ ) كحزنهم ، فإن أهل التقوى يعلمون أن ما يصيبهم إنما هو بإذن الله ، وأن الله أعدّ لهم أعظم الجزاء ، ولذا لا يكون للكوارث عليهم وقع ، كما أنهم يكونون مطمئنين بثواب الله في الآخرة ورحمته ، ولذا لا يكون لهم خوف من العقاب كخوف غيرهم.` },
            { text: "وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلنَّارِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `أي حججنا ودلائلنا ، وأنكروا الأنبياء والرسل ( وَاسْتَكْبَرُوا عَنْها ) بأن رأوا أنفسهم فوق الرسل ، وفوق الإذعان لآيات الله ( أُولئِكَ أَصْحابُ النَّارِ ) الملازمون لها ، فإن الملازم للشيء يقال له الصاحب ( هُمْ فِيها خالِدُونَ ) إلى الأبد.` },
            { text: "فَمَنْ أَظْلَمُ مِمَّنِ ٱفْتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوْ كَذَّبَ بِـَٔايَٰتِهِۦٓ أُو۟لَٰٓئِكَ يَنَالُهُمْ نَصِيبُهُم مِّنَ ٱلْكِتَٰبِ حَتَّىٰٓ إِذَا جَآءَتْهُمْ رُسُلُنَا يَتَوَفَّوْنَهُمْ قَالُوٓا۟ أَيْنَ مَا كُنتُمْ تَدْعُونَ مِن دُونِ ٱللَّهِ قَالُوا۟ ضَلُّوا۟ عَنَّا وَشَهِدُوا۟ عَلَىٰٓ أَنفُسِهِمْ أَنَّهُمْ كَانُوا۟ كَٰفِرِينَ", tafsir: `أي لا أحد أظلم منه ، فهو إخبار في صورة استفهام ، ليكون أبلغ ، إذ السامع يعدّ نفسه ليجيب بجواب يرضي المتكلم ، فهو إخبار مع أخذ الموافقة من السامع ( أَوْ كَذَّبَ بِآياتِهِ ) الدالة على الألوهية ، أو الرسالة ، أو المعاد ، أو سائر الشؤون الحقة ( أُولئِكَ يَنالُهُمْ نَصِيبُهُمْ مِنَ الْكِتابِ ) فينالهم جميع ما كتب لهم من الخير والشر ، والرزق والعمر ، في دار الدنيا ، فلا يقطع حَتَّى إِذا جاءَتْهُمْ رُسُلُنا يَتَوَفَّوْنَهُمْ قالُوا أَيْنَ ما كُنْتُمْ تَدْعُونَ مِنْ دُونِ اللهِ قالُوا ضَلُّوا عَنَّا وَشَهِدُوا عَلى أَنْفُسِهِمْ أَنَّهُمْ كانُوا كافِرِينَ (37) قالَ ادْخُلُوا فِي أُمَمٍ قَدْ خَلَتْ مِنْ قَبْلِكُمْ مِنَ الْجِنِّ وَالْإِنْسِ فِي النَّارِ كُلَّما دَخَلَتْ أُمَّةٌ لَعَنَتْ أُخْتَها عنهم ما كتب لهم ، بسبب كفرهم ( حَتَّى إِذا جاءَتْهُمْ رُسُلُنا ) أي ملائكة الموت لتقبض أرواحهم ، بعد أن أتموا مدّتهم المكتوبة لهم ( يَتَوَفَّوْنَهُمْ ) أي يقبضون أرواحهم ( قالُوا ) أي الملائكة ، لهم : ( أَيْنَ ما كُنْتُمْ تَدْعُونَ مِنْ دُونِ اللهِ ) ؟ أي أين ذهبت أصنامكم التي تجعلونها شريكة لله ؟ وهذا الاستفهام للتوبيخ والتقريع ، وبيان أنها لم تنفعكم في دفع العذاب الآن ( قالُوا ) يعني الكفار : ( ضَلُّوا ) تلك الأصنام ( عَنَّا ) فقد افتقدناهم فلا يقدرون على دفع العذاب عنا ( وَشَهِدُوا ) أي الكفار ( عَلى أَنْفُسِهِمْ أَنَّهُمْ كانُوا كافِرِينَ ) وأخذ بإقرارهم ليجزون بكفرهم. [39] وإذا كان يوم القيامة ( قالَ ) الله سبحانه لهم : ( ادْخُلُوا فِي أُمَمٍ ) أي جماعات وطوائف من الكفار السابقين ( قَدْ خَلَتْ ) أي مضت وسبقتكم ( مِنْ قَبْلِكُمْ مِنَ الْجِنِّ وَالْإِنْسِ فِي النَّارِ ) وهذا نوع من عذاب آخر لأن الإنسان بحشره مع المجرمين يعذّب نفسيا ، كما يعذب جسديّا بإدخاله النار ، وهؤلاء لا صفاء بينهم ، فاجتماعهم في الدنيا على الكفر لا يسبب ارتياح بعضهم مع بعض هناك ، بل بالعكس ، ف ( كُلَّما دَخَلَتْ أُمَّةٌ ) من تلك الأمم الكافرة ، النار ( لَعَنَتْ أُخْتَها ) أي الأمة السابقة التي هي أختها في الكفر ، فإن النار محل حَتَّى إِذَا ادَّارَكُوا فِيها جَمِيعاً قالَتْ أُخْراهُمْ لِأُولاهُمْ رَبَّنا هؤُلاءِ أَضَلُّونا فَآتِهِمْ عَذاباً ضِعْفاً مِنَ النَّارِ قالَ لِكُلٍّ ضِعْفٌ وَلكِنْ لا تَعْلَمُونَ (38) خصام وتضارب بعكس الجنة التي ( دَعْواهُمْ فِيها سُبْحانَكَ اللهُمَّ وَتَحِيَّتُهُمْ فِيها سَلامٌ ) (1) ، ( إِخْواناً عَلى سُرُرٍ مُتَقابِلِينَ ) (2) . ( حَتَّى إِذَا ادَّارَكُوا ) أي تلاحقوا واجتمعوا ، أصله « تدارك » قلبت التاء دالا ، وأدغمت الدال في الدال ، وجيء بهمزة الوصل لتعذر الابتداء بالساكن ( فِيها ) أي في النار ( جَمِيعاً ) أي جميع الأمم الكافرة ( قالَتْ أُخْراهُمْ ) أي الطائفة التي دخلت النار متأخرة وهم الأتباع ( لِأُولاهُمْ ) أي بالنسبة إلى الرؤساء الذين دخلوا أولا : ( رَبَّنا هؤُلاءِ ) الطائفة الأولى ( أَضَلُّونا ) حيث أغرونا لنتخذ معك شريكا ونخالف أوامر رسلك ( فَآتِهِمْ ) أي أعطهم ( عَذاباً ضِعْفاً ) أي مضاعفا : عذابا لكفرهم ، وعذابا لإغوائهم إيانا ( مِنَ النَّارِ ) وبهذا يريدون الانتقام من القادة المغوين. ( قالَ ) الله تعالى في جوابهم : ( لِكُلٍ ) منهم ومنكم ( ضِعْفٌ ) أي عذاب مضاعف ، فللرؤساء الضعف للكفر والإغواء ، وللتابعين الضعف للكفر وتقوية مكانة الرؤساء ، فإنه لو لا التابعين لم يتمكن المتبوعون من السيطرة وإقصاء الحق ، كما قال الإمام عليه‌السلام لتابعي بني أمية « لو لا أنتم لما غصبوا حقنا » ( وَلكِنْ لا تَعْلَمُونَ ) أيها الضالون ( 1) يونس : 11. ( 2) الحجر : 48. وَقالَتْ أُولاهُمْ لِأُخْراهُمْ فَما كانَ لَكُمْ عَلَيْنا مِنْ فَضْلٍ فَذُوقُوا الْعَذابَ بِما كُنْتُمْ تَكْسِبُونَ (39) إِنَّ الَّذِينَ كَذَّبُوا بِآياتِنا وَاسْتَكْبَرُوا عَنْها لا تُفَتَّحُ لَهُمْ أَبْوابُ السَّماءِ وَلا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِياطِ وَكَذلِكَ والمضلون مقدار عذاب كل واحد منكم ، ولا الفرق بين الضعف في المتبوع ، وبين الضعف في التابع. [40] وحينما يسمع القادة جواب الله سبحانه للتابعين ، يتوجهون إليهم بالشماتة ، قائلين : لسنا أولى منكم بالعذاب ليكون لنا ضعف ، فكلنا سواء في الكفر ( وَقالَتْ أُولاهُمْ ) القادة ( لِأُخْراهُمْ ) التابعين : ( فَما كانَ لَكُمْ ) أيها التابعون ( عَلَيْنا مِنْ فَضْلٍ ) وتفاوت في الكفر ، بأن يكون كفركم أخف من كفرنا ، حتى تستحقون عذابا أقل ( فَذُوقُوا ) أيها التابعون ( الْعَذابَ ) بسبب ما ( كُنْتُمْ تَكْسِبُونَ ) من الكفر والمعاصي.` },
            { text: "قَالَ ٱدْخُلُوا۟ فِىٓ أُمَمٍ قَدْ خَلَتْ مِن قَبْلِكُم مِّنَ ٱلْجِنِّ وَٱلْإِنسِ فِى ٱلنَّارِ كُلَّمَا دَخَلَتْ أُمَّةٌ لَّعَنَتْ أُخْتَهَا حَتَّىٰٓ إِذَا ٱدَّارَكُوا۟ فِيهَا جَمِيعًا قَالَتْ أُخْرَىٰهُمْ لِأُولَىٰهُمْ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمْ عَذَابًا ضِعْفًا مِّنَ ٱلنَّارِ قَالَ لِكُلٍّ ضِعْفٌ وَلَٰكِن لَّا تَعْلَمُونَ", tafsir: `` },
            { text: "وَقَالَتْ أُولَىٰهُمْ لِأُخْرَىٰهُمْ فَمَا كَانَ لَكُمْ عَلَيْنَا مِن فَضْلٍ فَذُوقُوا۟ ٱلْعَذَابَ بِمَا كُنتُمْ تَكْسِبُونَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَٱسْتَكْبَرُوا۟ عَنْهَا لَا تُفَتَّحُ لَهُمْ أَبْوَٰبُ ٱلسَّمَآءِ وَلَا يَدْخُلُونَ ٱلْجَنَّةَ حَتَّىٰ يَلِجَ ٱلْجَمَلُ فِى سَمِّ ٱلْخِيَاطِ وَكَذَٰلِكَ نَجْزِى ٱلْمُجْرِمِينَ", tafsir: `فلم يقبلوها ( وَاسْتَكْبَرُوا عَنْها ) أي تكبروا عن الخضوع لها ( لا تُفَتَّحُ لَهُمْ أَبْوابُ السَّماءِ ) روي عن الإمام الباقر عليه‌السلام أنه قال : « أما المؤمنون فترفع أعمالهم وأرواحهم إلى السماء فتفتح لهم أبوابها ، وأما الكافر فيصعد بعمله وروحه حتى إذا بلغ السماء نادى مناد اهبطوا به إلى سجين » ( وَلا يَدْخُلُونَ الْجَنَّةَ حَتَّى يَلِجَ الْجَمَلُ ) أي يدخل البعير ( فِي سَمِّ الْخِياطِ ) أي ثقب الإبرة ، فكما يستحيل دخول الجمل في ثقبها ، كذلك يستحيل دخول الكافر في الجنة ، وهذا تمثيل بديع للاستحالة ، وقيل المراد ب « الجمل » الحبل الغليظ ( وَكَذلِكَ ) نَجْزِي الْمُجْرِمِينَ (40) لَهُمْ مِنْ جَهَنَّمَ مِهادٌ وَمِنْ فَوْقِهِمْ غَواشٍ وَكَذلِكَ نَجْزِي الظَّالِمِينَ (41) وَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحاتِ لا نُكَلِّفُ نَفْساً إِلاَّ وُسْعَها أُولئِكَ أَصْحابُ الْجَنَّةِ هُمْ فِيها خالِدُونَ (42) وَنَزَعْنا ما فِي صُدُورِهِمْ مِنْ غِلٍّ أي كما جزينا هؤلاء المكذبين ( نَجْزِي ) سائر ( الْمُجْرِمِينَ ) وإن كان اختلاف بين أنواع الجزاء ، فكل إجرام له جزاء خاص ، وعقوبة مخصوصة.` },
            { text: "لَهُم مِّن جَهَنَّمَ مِهَادٌ وَمِن فَوْقِهِمْ غَوَاشٍ وَكَذَٰلِكَ نَجْزِى ٱلظَّٰلِمِينَ", tafsir: `أي فراش ومضجع ( وَمِنْ فَوْقِهِمْ غَواشٍ ) جمع « غاشية » ، أي لحف من نار ، فالنار محيطة بهم سفلا وعلوا ( وَكَذلِكَ ) أي كما جزينا المكذبين ( نَجْزِي الظَّالِمِينَ ) الذين ظلموا أنفسهم باتباع أوامر الشيطان ، وترك عبادة الرحمن.` },
            { text: "وَٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفْسًا إِلَّا وُسْعَهَآ أُو۟لَٰٓئِكَ أَصْحَٰبُ ٱلْجَنَّةِ هُمْ فِيهَا خَٰلِدُونَ", tafsir: `بأن صحّت عقيدتهم وعملهم ، ولا يراد بأنهم عملوا كل الصالحات ، بل قدر طاقتهم ووسعهم ، لأنّا ( لا نُكَلِّفُ نَفْساً إِلَّا ) مقدار ( وُسْعَها ) والوسع دون الطاقة ( أُولئِكَ أَصْحابُ الْجَنَّةِ ) الملازمون لها أبد الآبدين ( هُمْ فِيها خالِدُونَ ) . [44] وهناك لا تنازع ولا تخاصم ـ كما كان عند أهل النار ـ ( وَنَزَعْنا ما فِي صُدُورِهِمْ مِنْ غِلٍ ) أي : أخرجنا ما في قلوبهم من حقد وحسد وعداوة حتى لا يحسد بعضهم بعضا ، فإن الإنسان مهما كان تقيا لا يخلو قلبه من شيء من الصفات الذميمة ، وهناك تصفّى قلوبهم ، ليكونوا إخوانا تَجْرِي مِنْ تَحْتِهِمُ الْأَنْهارُ وَقالُوا الْحَمْدُ لِلَّهِ الَّذِي هَدانا لِهذا وَما كُنَّا لِنَهْتَدِيَ لَوْ لا أَنْ هَدانَا اللهُ لَقَدْ جاءَتْ رُسُلُ رَبِّنا بِالْحَقِّ وَنُودُوا أَنْ تِلْكُمُ الْجَنَّةُ أُورِثْتُمُوها بِما كُنْتُمْ تَعْمَلُونَ (43) وَنادى أَصْحابُ الْجَنَّةِ أَصْحابَ النَّارِ قلبا وقالبا ( تَجْرِي مِنْ تَحْتِهِمُ ) أي من تحت قصورهم وبساتينهم ( الْأَنْهارُ ) هذه جملة مستأنفة ، أي أنهم يكونون هكذا في الجنة في قبال الكفار الذين « لهم من جهنم مهاد » ( وَقالُوا الْحَمْدُ لِلَّهِ الَّذِي هَدانا لِهذا ) أي أوصلنا إلى هذا النعيم ، بما هدانا سابقا في الدنيا للعقيدة الصحيحة ، والعمل الصالح ( وَما كُنَّا لِنَهْتَدِيَ ) أي لم نقدر على الهداية بأنفسنا ( لَوْ لا أَنْ هَدانَا اللهُ ) فإن الإنسان لا يهتدي إلا بإرسال الله الرسل ، وتبليغه الأحكام ، وهذا شكر من أهل الجنة ، وتقدير لنعم الله عليهم ، في الدنيا بالهداية ، وفي الآخرة بالجنة ( لَقَدْ جاءَتْ رُسُلُ رَبِّنا بِالْحَقِ ) وأنهم أرسلوا من قبله سبحانه ، وكان ما قالوه حقا ، وها نحن نرى صدق ما قالوا ( وَنُودُوا ) أي أهل الجنة ينادون من قبل الله سبحانه : ( أَنْ تِلْكُمُ الْجَنَّةُ ) التي وعدتموها في الدنيا ، هي هذه التي دخلتموها ، ويحتمل أن يراد كون النداء قبل دخولها ـ فإن الواو لمطلق العطف ( أُورِثْتُمُوها ) أي أعطيتم إياها إرثا ، وصارت إليكم كما يصير الميراث لأهل الميت ( بِما كُنْتُمْ تَعْمَلُونَ ) أي جزاء لأعمالكم الصالحة في الدنيا. [45] وحيث يستقر كلّ فريق من المؤمنين والكافرين ، في مقرّه من الجنّة والنّار ، يقع بينها الحوار على النّحو الآتي ( وَنادى أَصْحابُ الْجَنَّةِ أَصْحابَ النَّارِ ) أَنْ قَدْ وَجَدْنا ما وَعَدَنا رَبُّنا حَقًّا فَهَلْ وَجَدْتُمْ ما وَعَدَ رَبُّكُمْ حَقًّا قالُوا نَعَمْ فَأَذَّنَ مُؤَذِّنٌ بَيْنَهُمْ أَنْ لَعْنَةُ اللهِ عَلَى الظَّالِمِينَ (44) الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِ اللهِ وَيَبْغُونَها عِوَجاً أي أهل الجنّة ، أهل النّار ، والإتيان بلفظ الماضي « نادى » لأنّ المستقبل المتحقّق الوقوع ينزّل منزلة الماضي : ( أَنْ قَدْ وَجَدْنا ما وَعَدَنا رَبُّنا حَقًّا ) فقد أعطينا الثواب والجنة كما كنا نوعد في الدنيا ( فَهَلْ وَجَدْتُمْ ) أنتم يا أهل النار ( ما وَعَدَ رَبُّكُمْ ) من العقاب ( حَقًّا ) والوعد وإن كان بالنسبة إلى كلتا الطائفتين إلا أن انحراف العاصين وإعراضهم ، واهتداء المطيعين إلى الطريق ، أورث توجه الوعد إلى أهل الجنة ، والوعيد إلى أهل النار ( قالُوا ) أي قال أصحاب النار : ( نَعَمْ ) وجدنا وعد ربنا حقا ( فَأَذَّنَ مُؤَذِّنٌ ) أي نادى مناد ( بَيْنَهُمْ ) أي بين أهل الجنة وأهل النار ( أَنْ لَعْنَةُ اللهِ عَلَى الظَّالِمِينَ ) ـ و في الأحاديث أن المؤذن هو الإمام أمير المؤمنين عليه‌السلام (1) ـ ، والمراد ب « لعنة الله » غضبه وانتقامه وطرده وعذابه ، وإنما ينادي المنادي بهذا النداء ليذكرهم بما كانوا يفعلون ، ومن أجله استحقوا العقاب. [46] ومن هم الظالمون ؟ إنهم هم ( الَّذِينَ يَصُدُّونَ عَنْ سَبِيلِ اللهِ ) أي يمنعون الناس عن السير في الطريق الذي جعله الله لعباده ، ليسعدوا بسلوكه في الدنيا والآخرة ( وَيَبْغُونَها عِوَجاً ) أي يطلبون الطريق المعوج ، فلا يسيرون في الطريق المستقيم ، فالضمير في « يبغونها » راجع إلى المضاف وهو « السبيل » لا المضاف والمضاف إليه ، وقيل : ( 1) الكافي : ج 1 ص 426. وَهُمْ بِالْآخِرَةِ كافِرُونَ (45) وَبَيْنَهُما حِجابٌ وَعَلَى الْأَعْرافِ رِجالٌ يَعْرِفُونَ كُلاًّ بِسِيماهُمْ وَنادَوْا أَصْحابَ الْجَنَّةِ أَنْ سَلامٌ عَلَيْكُمْ لَمْ يَدْخُلُوها وَهُمْ يَطْمَعُونَ (46) معناه يطلبون لطريق الله العوج بالشّبه التي يلتبسون بها ويوهمون أنها تقدح فيها ( وَهُمْ ) بالدار الآخرة ( كافِرُونَ ) لا يعتقدون بها.` },
            { text: "وَنَزَعْنَا مَا فِى صُدُورِهِم مِّنْ غِلٍّ تَجْرِى مِن تَحْتِهِمُ ٱلْأَنْهَٰرُ وَقَالُوا۟ ٱلْحَمْدُ لِلَّهِ ٱلَّذِى هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِىَ لَوْلَآ أَنْ هَدَىٰنَا ٱللَّهُ لَقَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ وَنُودُوٓا۟ أَن تِلْكُمُ ٱلْجَنَّةُ أُورِثْتُمُوهَا بِمَا كُنتُمْ تَعْمَلُونَ", tafsir: `` },
            { text: "وَنَادَىٰٓ أَصْحَٰبُ ٱلْجَنَّةِ أَصْحَٰبَ ٱلنَّارِ أَن قَدْ وَجَدْنَا مَا وَعَدَنَا رَبُّنَا حَقًّا فَهَلْ وَجَدتُّم مَّا وَعَدَ رَبُّكُمْ حَقًّا قَالُوا۟ نَعَمْ فَأَذَّنَ مُؤَذِّنٌۢ بَيْنَهُمْ أَن لَّعْنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ", tafsir: `` },
            { text: "ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبْغُونَهَا عِوَجًا وَهُم بِٱلْـَٔاخِرَةِ كَٰفِرُونَ", tafsir: `` },
            { text: "وَبَيْنَهُمَا حِجَابٌ وَعَلَى ٱلْأَعْرَافِ رِجَالٌ يَعْرِفُونَ كُلًّۢا بِسِيمَىٰهُمْ وَنَادَوْا۟ أَصْحَٰبَ ٱلْجَنَّةِ أَن سَلَٰمٌ عَلَيْكُمْ لَمْ يَدْخُلُوهَا وَهُمْ يَطْمَعُونَ", tafsir: `أي بين أهل الجنة وأهل النار ( حِجابٌ ) أي فاصل وستر ( وَعَلَى الْأَعْرافِ رِجالٌ ) الأعراف : هي الأمكنة المرتفعة ، أخذ من « عرف الفرس » ومنه « عرف الديك » وكل موضع مرتفع من الأرض عرف ، لأنه بظهوره أعرف مما انخفض ، وهؤلاء الرجال ( يَعْرِفُونَ كُلًّا ) من أهل الجنة وأهل النار ( بِسِيماهُمْ ) « السيماء » العلامة ، وهو فعل من « سام إبله » إذا أرسلها في المرعى معلّمة ، وإنما يعرفون كلا بسيماهم لأن أهل الجنة معلّمون ببياض الوجه والجلال والحفاوة ، وأهل النار معلّمون بعلامة على أنوفهم ـ كما قال سبحانه : ( سَنَسِمُهُ عَلَى الْخُرْطُومِ ) (1) ـ ، والهيئة المنكرة ، والغبار على الوجوه كما قال سبحانه : ( وَوُجُوهٌ يَوْمَئِذٍ عَلَيْها غَبَرَةٌ ) (2) ، وغيرها. ( وَنادَوْا ) هؤلاء الذين على الأعراف ( أَصْحابَ الْجَنَّةِ ) الذين يرونهم من هناك آخذين في الذهاب إلى الجنة ، أو المستقرين فيها ( أَنْ سَلامٌ عَلَيْكُمْ ) تهنئة لهم بفوزهم بالجنة ( لَمْ يَدْخُلُوها ) أي لم يدخل أصحاب الأعراف الجنة بعد ( وَهُمْ يَطْمَعُونَ ) كما قال ( 1) القلم : 17. ( 2) عبس : 41. وَإِذا صُرِفَتْ أَبْصارُهُمْ تِلْقاءَ أَصْحابِ النَّارِ قالُوا رَبَّنا لا تَجْعَلْنا مَعَ الْقَوْمِ الظَّالِمِينَ (47) وَنادى أَصْحابُ الْأَعْرافِ رِجالاً يَعْرِفُونَهُمْ بِسِيماهُمْ قالُوا ما أَغْنى سبحانه عن لسان إبراهيم عليه‌السلام : ( وَالَّذِي أَطْمَعُ أَنْ يَغْفِرَ لِي خَطِيئَتِي ) (1) ، فإنه يستعمل لليقين والرجاء.` },
            { text: "وَإِذَا صُرِفَتْ أَبْصَٰرُهُمْ تِلْقَآءَ أَصْحَٰبِ ٱلنَّارِ قَالُوا۟ رَبَّنَا لَا تَجْعَلْنَا مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ", tafsir: `توجهت أنظار أصحاب الأعراف ( تِلْقاءَ أَصْحابِ النَّارِ ) الذين أخذوا في الذهاب إلى جهنم ، أو المستقرين فيها ( قالُوا رَبَّنا لا تَجْعَلْنا مَعَ الْقَوْمِ الظَّالِمِينَ ) فلا تدخلنا النار ، ولا تجعلنا من أهلها. وقد وردت أحاديث متعددة أن المراد بأصحاب الأعراف الأنبياء والأئمة عليهم‌السلام وظاهر الآية لا يأباه (2) .` },
            { text: "وَنَادَىٰٓ أَصْحَٰبُ ٱلْأَعْرَافِ رِجَالًا يَعْرِفُونَهُم بِسِيمَىٰهُمْ قَالُوا۟ مَآ أَغْنَىٰ عَنكُمْ جَمْعُكُمْ وَمَا كُنتُمْ تَسْتَكْبِرُونَ", tafsir: `الذين عليها ( رِجالاً ) من أصحاب النار ( يَعْرِفُونَهُمْ بِسِيماهُمْ ) بعلاماتهم ، وأنهم من رؤساء المشركين ، والمراد بالعلامات ، إما العلامات التي كانوا معلّمين بها في الدنيا ، أي صورهم التي كانوا يعرفونهم بها ، وإنما عبر بلفظ « سيماهم » لأنهم تغيروا هناك فلا يعرفون إلا السحنة وسائر العلامات ، وإما العلامات التي وسموا بها في الآخرة ، من الزرقة ، وغبار الوجه وتشوية الخلقة. ( قالُوا ) أي قال أصحاب الأعراف لأولئك المجرمين : ( ما أَغْنى ( 1) الشعراء : 83. (2) ورد كلمة الأنبياء عن العلامة المجلسي في بحار الأنوار : ج 8 ص 331 ، وكما ورد كلمة الأئمة في رواية عن أبي عبد الله عليه‌السلام قال : نحن أصحاب الأعراف : راجع بصائر الدرجات ص 499. عَنْكُمْ جَمْعُكُمْ وَما كُنْتُمْ تَسْتَكْبِرُونَ (48) أَ هؤُلاءِ الَّذِينَ أَقْسَمْتُمْ لا يَنالُهُمُ اللهُ بِرَحْمَةٍ ادْخُلُوا الْجَنَّةَ لا خَوْفٌ عَلَيْكُمْ وَلا أَنْتُمْ تَحْزَنُونَ (49) وَنادى أَصْحابُ النَّارِ أَصْحابَ الْجَنَّةِ أَنْ أَفِيضُوا عَلَيْنا مِنَ الْماءِ أَوْ مِمَّا رَزَقَكُمُ اللهُ عَنْكُمْ جَمْعُكُمْ ) أي اجتماعكم وكثرتكم ، أو جمعكم الأموال والأولاد والخدم والأصدقاء ( وَما كُنْتُمْ تَسْتَكْبِرُونَ ) أي استكباركم على الله والرسول ، ما أغنى عنكم كل ذلك ، فلم يدفع العذاب عنكم. [50] ثم يقول أصحاب الأعراف لأهل النار : ( أَ هؤُلاءِ ) المراد ب « هؤلاء » أهل الجنة ( الَّذِينَ أَقْسَمْتُمْ لا يَنالُهُمُ اللهُ بِرَحْمَةٍ ) فقد كان الكفار يحلفون ـ في الدنيا ـ أن الله لا ينال المؤمنين برحمة منه ، وهناك يريهم أصحاب الأعراف أن المؤمنين دخلوا الجنة ، وأنالهم الله رحمته. ثم يتوجه أصحاب الأعراف إلى المؤمنين قائلين لهم : ( ادْخُلُوا الْجَنَّةَ لا خَوْفٌ عَلَيْكُمْ وَلا أَنْتُمْ تَحْزَنُونَ ) وبهذا النحو يقرع أهل النار ، في قبال ما كانوا يقرعون المؤمنين في الدنيا. [51] وحينما يستقر الفريقان في مقامهما من الجنة والنار يقع حوار بين الجانبين بهذه الكيفية : ( وَنادى أَصْحابُ النَّارِ أَصْحابَ الْجَنَّةِ ) أي « ينادون » ، وإنما أتى بلفظ الماضي ، لأن المستقبل المتحقق وقوعه ينزّل بمنزلته ـ كما سبق ـ : ( أَنْ أَفِيضُوا ) أي صبّوا ( عَلَيْنا مِنَ الْماءِ ) لنسكن به حر النار ، أو نروي به العطش والظمأ ( أَوْ مِمَّا رَزَقَكُمُ اللهُ ) من الطعام واللباس وغيرهما ، لننتفع به في محلنا الحار الفاقد لكل قالُوا إِنَّ اللهَ حَرَّمَهُما عَلَى الْكافِرِينَ (50) الَّذِينَ اتَّخَذُوا دِينَهُمْ لَهْواً وَلَعِباً وَغَرَّتْهُمُ الْحَياةُ الدُّنْيا فَالْيَوْمَ نَنْساهُمْ كَما نَسُوا لِقاءَ يَوْمِهِمْ هذا وَما كانُوا بِآياتِنا يَجْحَدُونَ (51) شيء من وسائل الراحة ( قالُوا ) أي قال أهل الجنة في جواب أهل النار : ( إِنَّ اللهَ حَرَّمَهُما ) أي حرّم الماء والرزق ( عَلَى الْكافِرِينَ ) فلا يباح لنا إعطاؤكم منهما شيئا. [52] ثم وصف الكافرين بأنهم ( الَّذِينَ اتَّخَذُوا دِينَهُمْ لَهْواً وَلَعِباً ) فدينهم الذي اختاره الله لهم ـ وهو الإسلام ـ اتخذوه أداة تلهّي ولعب ، فكانوا به يستهزءون ، أو المراد أن دينهم كان لهوا ولعبا ، فيكون التبكيت لاتخاذهم أصل الدين ـ الكفري ـ لا اتخاذه لهوا. وظاهر الكلام المعنى الأول ، كما تقرر في علم البلاغة أن القيد إذا كان في الكلام توجه النفي والإثبات إليه. ( وَغَرَّتْهُمُ ) أي خدعتهم ( الْحَياةُ الدُّنْيا ) فظنوا أنهم يبقون فيها إلى الأبد ، وأن نعيمها يكفيهم عن نعيم الجنة ( فَالْيَوْمَ ) في الآخرة ( نَنْساهُمْ ) أي نتركهم في العذاب ، كفعل الناسي الذي لا يعتني بالمنسي ، وإن أصابه ما أصابه ( كَما نَسُوا لِقاءَ يَوْمِهِمْ هذا ) أي كما نسوا في الدنيا التأهّب ليوم القيامة ( وَما كانُوا بِآياتِنا يَجْحَدُونَ ) « ما » مصدرية ، أي لسبب نسيانهم ، وبسبب جحودهم ، وإنكارهم لآيات الله وأحكامه. ومن هذه الجملة يعلم أن قوله : « الذين اتخذوا » من كلام الله استئنافا ، لا من تتمة كلام أهل الجنة. وَلَقَدْ جِئْناهُمْ بِكِتابٍ فَصَّلْناهُ عَلى عِلْمٍ هُدىً وَرَحْمَةً لِقَوْمٍ يُؤْمِنُونَ (52) هَلْ يَنْظُرُونَ إِلاَّ تَأْوِيلَهُ يَوْمَ يَأْتِي تَأْوِيلُهُ يَقُولُ الَّذِينَ نَسُوهُ مِنْ قَبْلُ قَدْ جاءَتْ رُسُلُ رَبِّنا بِالْحَقِّ فَهَلْ لَنا مِنْ شُفَعاءَ فَيَشْفَعُوا لَنا أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ الَّذِي كُنَّا نَعْمَلُ [53] إن أهل النار وقعوا فيها بعد البيان وإتمام الحجة ، فلم يكن هذا العذاب ظلم بالنسبة إليهم ( وَلَقَدْ جِئْناهُمْ بِكِتابٍ ) وهو القرآن ( فَصَّلْناهُ ) تفصيلا فلم يكن مجملا لا يستفاد منه المطلب ( عَلى عِلْمٍ ) أي كنا عالمين بما أنزلنا ، فلم يكن الكتاب كتاب جاهل لا يدري المصالح والمفاسد ، ويحكم اعتباطا ( هُدىً ) أي جئنا به لأجل الهداية ( وَرَحْمَةً ) ولأجل الرحمة ( لِقَوْمٍ يُؤْمِنُونَ ) وإنما اختص بهم لأن الفائدة تعود إليهم وحدهم ، وإن كان الكتاب للكل.` },
            { text: "أَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقْسَمْتُمْ لَا يَنَالُهُمُ ٱللَّهُ بِرَحْمَةٍ ٱدْخُلُوا۟ ٱلْجَنَّةَ لَا خَوْفٌ عَلَيْكُمْ وَلَآ أَنتُمْ تَحْزَنُونَ", tafsir: `` },
            { text: "وَنَادَىٰٓ أَصْحَٰبُ ٱلنَّارِ أَصْحَٰبَ ٱلْجَنَّةِ أَنْ أَفِيضُوا۟ عَلَيْنَا مِنَ ٱلْمَآءِ أَوْ مِمَّا رَزَقَكُمُ ٱللَّهُ قَالُوٓا۟ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلْكَٰفِرِينَ", tafsir: `` },
            { text: "ٱلَّذِينَ ٱتَّخَذُوا۟ دِينَهُمْ لَهْوًا وَلَعِبًا وَغَرَّتْهُمُ ٱلْحَيَوٰةُ ٱلدُّنْيَا فَٱلْيَوْمَ نَنسَىٰهُمْ كَمَا نَسُوا۟ لِقَآءَ يَوْمِهِمْ هَٰذَا وَمَا كَانُوا۟ بِـَٔايَٰتِنَا يَجْحَدُونَ", tafsir: `` },
            { text: "وَلَقَدْ جِئْنَٰهُم بِكِتَٰبٍ فَصَّلْنَٰهُ عَلَىٰ عِلْمٍ هُدًى وَرَحْمَةً لِّقَوْمٍ يُؤْمِنُونَ", tafsir: `` },
            { text: "هَلْ يَنظُرُونَ إِلَّا تَأْوِيلَهُۥ يَوْمَ يَأْتِى تَأْوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبْلُ قَدْ جَآءَتْ رُسُلُ رَبِّنَا بِٱلْحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشْفَعُوا۟ لَنَآ أَوْ نُرَدُّ فَنَعْمَلَ غَيْرَ ٱلَّذِى كُنَّا نَعْمَلُ قَدْ خَسِرُوٓا۟ أَنفُسَهُمْ وَضَلَّ عَنْهُم مَّا كَانُوا۟ يَفْتَرُونَ", tafsir: `أي هل ينتظر هؤلاء الكفار الذين لم يؤمنوا بالكتاب ( إِلَّا تَأْوِيلَهُ ) أي مآل الكتاب ، بمعنى : المآل الذي أخبر به الكتاب ، من العذاب والعقاب النازل بالكفار. وهذا تهديد كما يقال للعاصي أمر المولى : « هل تنتظر عقابه ؟ » ( يَوْمَ يَأْتِي تَأْوِيلُهُ ) وما حذّر منه ( يَقُولُ الَّذِينَ نَسُوهُ ) أي تركوه ، وفعلوا به فعل الناسي ( مِنْ قَبْلُ ) في الدنيا : ( قَدْ جاءَتْ رُسُلُ رَبِّنا بِالْحَقِ ) وهناك يعترفون بما أنكروه في الدنيا ، حيث لا فائدة في الاعتراف ( فَهَلْ لَنا مِنْ شُفَعاءَ فَيَشْفَعُوا لَنا ) حتى نتخلص من العقاب ( أَوْ نُرَدُّ ) إلى الدنيا ( فَنَعْمَلَ ) عملا صالحا ( غَيْرَ الَّذِي كُنَّا نَعْمَلُ ) سابقا من المعاصي والآثام ؟ لكن ليس لهم شفيع قَدْ خَسِرُوا أَنْفُسَهُمْ وَضَلَّ عَنْهُمْ ما كانُوا يَفْتَرُونَ (53) إِنَّ رَبَّكُمُ اللهُ الَّذِي خَلَقَ السَّماواتِ وَالْأَرْضَ فِي سِتَّةِ أَيَّامٍ ولا يردون ، ف ( قَدْ خَسِرُوا أَنْفُسَهُمْ ) أهلكوها بالعذاب والعقاب ، وأعطوها بمقابل النار ، حيثما أعطى أهل الإيمان نفوسهم في مقابل الجنان ، وربحوا أكبر ربح ( وَضَلَّ عَنْهُمْ ) أي ذهب وغاب ( ما كانُوا يَفْتَرُونَ ) أي افتراؤهم على الله بالشرك ، فإن الأصنام التي جعلوها شريكة لله ، وكانوا يقولون : ( ما نَعْبُدُهُمْ إِلَّا لِيُقَرِّبُونا إِلَى اللهِ زُلْفى ) (1) ، ضلت عنهم فلم يجدوها ، ولا شفعت لهم هناك. [55] ثم بيّن سبحانه أن الله واحد لا شريك له ، وأنه الذي خلق وكوّن ، لا شريك له في شيء من الأمور الكونية ( إِنَّ رَبَّكُمُ ) أيها الناس ( اللهُ الَّذِي خَلَقَ السَّماواتِ ) أنشأها وكوّنها ( وَالْأَرْضَ ) أوجدها. ولعل ذكر « السماوات » غالبا بلفظ الجمع ، و « الأرض » بلفظ المفرد ، مع أن كلتيهما متعددة ، كما قال سبحانه : ( وَمِنَ الْأَرْضِ مِثْلَهُنَ ) (2) ، أن تعدد السماوات كان مألوفا لديهم ، لما يخبر به المنجمون ، من أفلاك الكواكب السيارة ، بخلاف تعدد الأرض ، ومن البلاغة أن يكلم الإنسان المخاطبين قدر عقولهم ( فِي سِتَّةِ أَيَّامٍ ) أي في مقدار ستة أيام من أيام الدنيا ، وإن لم تكن أيام ذلك الوقت ، حيث لا شمس ولا قمر ولا حركة ، أما مصلحة خلقها في ستة أيام مع قدرته سبحانه في ( 1) الزمر : 4. ( 2) الطلاق : 13. ثُمَّ اسْتَوى عَلَى الْعَرْشِ يُغْشِي اللَّيْلَ النَّهارَ يَطْلُبُهُ حَثِيثاً وَالشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ مُسَخَّراتٍ بِأَمْرِهِ أَلا لَهُ الْخَلْقُ وَالْأَمْرُ تَبارَكَ اللهُ رَبُّ الْعالَمِينَ (54) إنشائهما دفعة ، فهي كمصلحة خلق الجنين والنبات تدريجا ، مع قدرته على الإيجاد دفعة. ( ثُمَ ) بعد خلق السماوات والأرض ( اسْتَوى ) أي استولى ( عَلَى الْعَرْشِ ) والمراد : جعل تدبير الأمر من هناك ، كما يقال : « استوى الملك على العرش » يراد استيلائه على الملك ، و « العرش » محل تشريفي خلقه سبحانه وأضافه إلى نفسه ، كما خلق الكعبة في الدنيا ، وجعلها بيته ، وكان ذلك لألفة الأجسام بمصدر للأحكام والتوجه ( يُغْشِي اللَّيْلَ النَّهارَ ) أي يلبس النهار ، ويمد رواق الليل المظلم على النهار المستنير ، كما يغشي الإنسان العباءة على المصباح ( يَطْلُبُهُ ) أي يطلب الليل النهار طلبا ( حَثِيثاً ) سريعا بكل جد ، كأن النهار يرفض الليل ، لكن الليل يطارده مطاردة الطالب للمطلوب الهارب ( وَ ) خلق ( الشَّمْسَ وَالْقَمَرَ وَالنُّجُومَ ) في حال كونها ( مُسَخَّراتٍ بِأَمْرِهِ ) فهي تسري وتدور وتشرق وتغيب حسب أمره سبحانه ( أَلا ) أي تنبهوا أيها البشر أن ( لَهُ ) سبحانه ( الْخَلْقُ ) للأشياء كلها ( وَالْأَمْرُ ) النافذ فيها ، فما يكون من تغيير وتبديل إلا بأمره وإرادته ، وهكذا لا أمر صحيح في التشريعات إلا له ، أما أمر سائر الآمرين ، فليست لهم قيمة واعتبار واقعي ، إلا إذا كانوا تبعا لأمره تعالى ( تَبارَكَ اللهُ ) أي تعالى عن الشريك وسائر النقائص ( رَبُّ الْعالَمِينَ ) لا رب سواه ، ولا إله إلا هو. ادْعُوا رَبَّكُمْ تَضَرُّعاً وَخُفْيَةً إِنَّهُ لا يُحِبُّ الْمُعْتَدِينَ (55) وَلا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلاحِها` },
            { text: "إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِى خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضَ فِى سِتَّةِ أَيَّامٍ ثُمَّ ٱسْتَوَىٰ عَلَى ٱلْعَرْشِ يُغْشِى ٱلَّيْلَ ٱلنَّهَارَ يَطْلُبُهُۥ حَثِيثًا وَٱلشَّمْسَ وَٱلْقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتٍۭ بِأَمْرِهِۦٓ أَلَا لَهُ ٱلْخَلْقُ وَٱلْأَمْرُ تَبَارَكَ ٱللَّهُ رَبُّ ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "ٱدْعُوا۟ رَبَّكُمْ تَضَرُّعًا وَخُفْيَةً إِنَّهُۥ لَا يُحِبُّ ٱلْمُعْتَدِينَ", tafsir: `أيها البشر ( تَضَرُّعاً ) أي تخشّعا ، فإن التضرع هو التذلل والتخشّع ، وهو في موضع الحال ، أي في حال كونكم متضرعين ( وَخُفْيَةً ) أي في حال الاختفاء ، فإن الضراعة المخفية أقرب إلى تركيز التوحيد في النفس. و لا يخفي أن هذا في مورد ، وفي مورد آخر يستحب الإجهار. فقد نزل جبرئيل على الرسول صلى‌الله‌عليه‌وآله‌وسلم في حال الحج قائلا : « إن ربك يأمرك بالعج والثج » (1) و « العج » من العجيج. كما أن في الروايات استحباب الإجهار بالصلوات على محمد وآله الطاهرين فإنه موجب لذهاب النفاق ، وكأن الجهر والإخفات في الدعاء ، كالإعلان والإسرار بالصدقة ، الذي لكل واحد منهما مورد. و قد روى علي بن إبراهيم أن المراد بالتضرع : العلانية ، أي : « ادعوه علانية وسرا » (2) . ( إِنَّهُ ) سبحانه ( لا يُحِبُّ الْمُعْتَدِينَ ) الذين يتجاوزون الحد ، إنه سبحانه يحب الخشوع والانكسار ، لا التجاوز والاعتداء. [57] وبمناسبة كراهيته سبحانه للاعتداء يقول تعالى : ( وَلا تُفْسِدُوا فِي الْأَرْضِ بَعْدَ إِصْلاحِها ) فإن الأنبياء والأئمة أصلحوا الأرض بمنهاج السماء ، وجعل كل شيء في موضعه ، فالتجاوز عن ذلك إفساد في الأرض وشقاء للبشر. قال الباقر عليه‌السلام : « إن الأرض كانت فاسدة فأصلحها الله بنبيه » (3) . ( 1) راجع معاني الأخبار : ص 224. ( 2) نقلا عن مجمع البيان : ج 4 ص 271. ( 3) الكافي : ج 8 ص 58. وَادْعُوهُ خَوْفاً وَطَمَعاً إِنَّ رَحْمَتَ اللهِ قَرِيبٌ مِنَ الْمُحْسِنِينَ (56) وَهُوَ الَّذِي يُرْسِلُ الرِّياحَ بُشْراً بَيْنَ يَدَيْ رَحْمَتِهِ حَتَّى إِذا أَقَلَّتْ سَحاباً ثِقالاً سُقْناهُ لِبَلَدٍ مَيِّتٍ فَأَنْزَلْنا بِهِ الْماءَ فَأَخْرَجْنا بِهِ مِنْ كُلِّ الثَّمَراتِ ( وَادْعُوهُ خَوْفاً وَطَمَعاً ) أي في حال كونكم خائفين وطامعين ، خوفا من عقابه وطمعا في ثوابه ( إِنَّ رَحْمَتَ اللهِ قَرِيبٌ مِنَ الْمُحْسِنِينَ ) فإنكم إذا لم تفسدوا ودعوتموه خوفا وطمعا جعلكم الله من المحسنين ، فتكون رحمته قريبة منكم ، وذلك يوجب استجابة دعائكم ، ولطف الله بكم.` },
            { text: "وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا وَٱدْعُوهُ خَوْفًا وَطَمَعًا إِنَّ رَحْمَتَ ٱللَّهِ قَرِيبٌ مِّنَ ٱلْمُحْسِنِينَ", tafsir: `` },
            { text: "وَهُوَ ٱلَّذِى يُرْسِلُ ٱلرِّيَٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦ حَتَّىٰٓ إِذَآ أَقَلَّتْ سَحَابًا ثِقَالًا سُقْنَٰهُ لِبَلَدٍ مَّيِّتٍ فَأَنزَلْنَا بِهِ ٱلْمَآءَ فَأَخْرَجْنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِ كَذَٰلِكَ نُخْرِجُ ٱلْمَوْتَىٰ لَعَلَّكُمْ تَذَكَّرُونَ", tafsir: `الله وحده ( الَّذِي يُرْسِلُ الرِّياحَ بُشْراً ) أي يطلقها ويجريها لأجل البشارة بالمطر ( بَيْنَ يَدَيْ رَحْمَتِهِ ) أي أمام رحمته ـ التي هي المطر ـ فإن الرياح إذا هبت في أيام السحاب ، دلت على نزول المطر ( حَتَّى إِذا أَقَلَّتْ ) أي حملت تلك الرياح ( سَحاباً ثِقالاً ) بالماء ( سُقْناهُ ) أي دفعنا السحاب ( لِبَلَدٍ مَيِّتٍ ) وموت البلد : تعفّي مزارعه ودروس مشاربه ، لا نبات فيه ، ولا عيون وأنهار ( فَأَنْزَلْنا بِهِ ) أي بالبلد ، أو بالسحاب ، و « الباء » على الأول بمعنى « في » ، وعلى الثاني بمعنى « السبب » ( الْماءَ ) وهناك خلاف في تكوّن المطر ، لكن ذلك لا يهم التفسير ، وكيف كان فإنه بقدرة الحكيم القدير ( فَأَخْرَجْنا بِهِ ) أي بسبب الماء ( مِنْ كُلِّ الثَّمَراتِ ) المتداولة هناك ، لا أن المراد جميع أنواع الثمرات ، إلا إذا أخذ الماء والسحاب بصورة عامة لا بالنسبة إلى بلد معيّن. كَذلِكَ نُخْرِجُ الْمَوْتى لَعَلَّكُمْ تَذَكَّرُونَ (57) وَالْبَلَدُ الطَّيِّبُ يَخْرُجُ نَباتُهُ بِإِذْنِ رَبِّهِ وَالَّذِي خَبُثَ لا يَخْرُجُ إِلاَّ نَكِداً كَذلِكَ نُصَرِّفُ الْآياتِ لِقَوْمٍ يَشْكُرُونَ (58) ( كَذلِكَ ) أي كما أخرجنا بالماء الثمرات ( نُخْرِجُ الْمَوْتى ) من الأرض ، فنحييهم. و في بعض الأحاديث : « تمطر السماء ماء ، فيسبب ذلك الماء إحياء الأموات ، بقدرة الله سبحانه » (1) ( لَعَلَّكُمْ تَذَكَّرُونَ ) المعاد والآخرة ، وكأن « لعل » تفريع على إنبات الثمر من ماء السماء في الأرض الميتة ، بأن يكون ذلك سببا لتذكيركم بالآخرة.` },
            { text: "وَٱلْبَلَدُ ٱلطَّيِّبُ يَخْرُجُ نَبَاتُهُۥ بِإِذْنِ رَبِّهِۦ وَٱلَّذِى خَبُثَ لَا يَخْرُجُ إِلَّا نَكِدًا كَذَٰلِكَ نُصَرِّفُ ٱلْـَٔايَٰتِ لِقَوْمٍ يَشْكُرُونَ", tafsir: `ترابه الصالح للزرع ( يَخْرُجُ نَباتُهُ ) « نبات » فاعل « يخرج » ، أي يخرج زرعه حسنا ناميا ( بِإِذْنِ رَبِّهِ ) وأمره سبحانه ، بلا نكد ولا عناء ولا تعب ( وَ ) البلد ( الَّذِي خَبُثَ ) ترابه بأن كان سبخا أو ما أشبه ( لا يَخْرُجُ ) النبات ( إِلَّا نَكِداً ) قليلا عسرا لا ينتفع به ، وهكذا القلب الطيب ينمو فيه الخير والفضيلة نموا سريعا ممرعا ، والقلب الخبيث لا ينمو فيه الخير إلا قليلا عسرا ( كَذلِكَ ) أي كما بيّنا هذه الآية الدالة على كمال قدرة الله سبحانه ( نُصَرِّفُ الْآياتِ ) أي نقلبها ونبيّنها ( لِقَوْمٍ يَشْكُرُونَ ) أي للشاكرين الذين يشكرون نعم الله سبحانه ، فإنهم المنتفعون بتصريف الآيات ، فغاية التصريف لهم دون غيرهم. [60] وإذ تمّ الدليل على وجوده سبحانه بما له من الصفات ، وأنه لا شريك له ، يأتي الكلام حول الأنبياء السالفين الذين بلغوا ( 1) راجع بحار الأنوار ج 7 ص 13. لَقَدْ أَرْسَلْنا نُوحاً إِلى قَوْمِهِ فَقالَ يا قَوْمِ اعْبُدُوا اللهَ ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ إِنِّي أَخافُ عَلَيْكُمْ عَذابَ يَوْمٍ عَظِيمٍ (59) قالَ الْمَلَأُ مِنْ قَوْمِهِ إِنَّا لَنَراكَ فِي ضَلالٍ مُبِينٍ (60) قالَ يا قَوْمِ لَيْسَ بِي ضَلالَةٌ وَلكِنِّي رَسُولٌ مِنْ رَبِّ الْعالَمِينَ (61) أُبَلِّغُكُمْ رِسالاتِ رَبِّي وَأَنْصَحُ لَكُمْ رسالات ربهم ، ولم يقبل قومهم منهم ، فأخذوا بالعذاب ، كما سبق في أول السورة ( وَكَمْ مِنْ قَرْيَةٍ أَهْلَكْناها )( لَقَدْ أَرْسَلْنا نُوحاً إِلى قَوْمِهِ فَقالَ يا قَوْمِ اعْبُدُوا اللهَ ) حيث كان القوم يعبدون الأصنام والأوثان ( ما لَكُمْ ) أي ليس لكم ( مِنْ إِلهٍ غَيْرُهُ ) فهو خالقكم الذي لا شريك له ( إِنِّي أَخافُ عَلَيْكُمْ ) أيها القوم ، إن لم تؤمنوا ( عَذابَ يَوْمٍ عَظِيمٍ ) إما المراد يوم القيامة ، أو عذابهم في الدنيا بالطوفان.` },
            { text: "لَقَدْ أَرْسَلْنَا نُوحًا إِلَىٰ قَوْمِهِۦ فَقَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ إِنِّىٓ أَخَافُ عَلَيْكُمْ عَذَابَ يَوْمٍ عَظِيمٍ", tafsir: `` },
            { text: "قَالَ ٱلْمَلَأُ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى ضَلَٰلٍ مُّبِينٍ", tafsir: `أي الأشراف ، وسمّوا به لأنهم يملأون العيون والصدور هيبة وجمالا : ( إِنَّا لَنَراكَ ) يا نوح ( فِي ضَلالٍ مُبِينٍ ) أي انحراف واضح حيث تذر الأصنام وتعبد الإله الذي لم تره.` },
            { text: "قَالَ يَٰقَوْمِ لَيْسَ بِى ضَلَٰلَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ", tafsir: `نوح لهم : ( يا قَوْمِ لَيْسَ بِي ضَلالَةٌ ) فلم أضلّ طريق الحق ( وَلكِنِّي رَسُولٌ مِنْ رَبِّ الْعالَمِينَ ) الذي يملك كل شيء فهو رب كل شيء ، وما لشيء سواه ملك ، فلا شريك له.` },
            { text: "أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنصَحُ لَكُمْ وَأَعْلَمُ مِنَ ٱللَّهِ مَا لَا تَعْلَمُونَ", tafsir: `أي أؤدّي إليكم ما أمرني ربي بتبليغه ، وإنما جمعت الرسالات ، باعتبار كل وحي وحي ( وَأَنْصَحُ لَكُمْ ) أي أنصح وَأَعْلَمُ مِنَ اللهِ ما لا تَعْلَمُونَ (62) أَ وَعَجِبْتُمْ أَنْ جاءَكُمْ ذِكْرٌ مِنْ رَبِّكُمْ عَلى رَجُلٍ مِنْكُمْ لِيُنْذِرَكُمْ وَلِتَتَّقُوا وَلَعَلَّكُمْ تُرْحَمُونَ (63) فَكَذَّبُوهُ فَأَنْجَيْناهُ وَالَّذِينَ مَعَهُ فِي الْفُلْكِ وَأَغْرَقْنَا الَّذِينَ كَذَّبُوا بِآياتِنا لفائدتكم ( وَأَعْلَمُ مِنَ اللهِ ) من أمره ونهيه ، ومن صفاته وآثاره ، ومن ثوابه وعقابه ( ما لا تَعْلَمُونَ ) فاتبعوني حتى أهديكم إلى الحق. [64] وقد كان القوم يبدون التعجب من أقوال نوح عليه‌السلام ، كيف يدّعي هذا المنصب الخطير ؟ وكيف يخبر عن أشياء لم يعلموها ؟ فكان يقول لهم : ( أَ وَعَجِبْتُمْ ) الهمزة للاستفهام ، أي هل تتعجبون ( أَنْ جاءَكُمْ ذِكْرٌ مِنْ رَبِّكُمْ عَلى رَجُلٍ مِنْكُمْ ) أي بشر من جنسكم ( لِيُنْذِرَكُمْ ) ويخوّفكم من عذاب الله إن تمردتم وكفرتم ( وَلِتَتَّقُوا ) أي جاءكم الذكر لتتقوا وتجتنبوا عقاب الله والكفر والمعاصي ( وَلَعَلَّكُمْ تُرْحَمُونَ ) أي لكي يرحمكم ربكم ؟` },
            { text: "أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَلِتَتَّقُوا۟ وَلَعَلَّكُمْ تُرْحَمُونَ", tafsir: `` },
            { text: "فَكَذَّبُوهُ فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِى ٱلْفُلْكِ وَأَغْرَقْنَا ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَآ إِنَّهُمْ كَانُوا۟ قَوْمًا عَمِينَ", tafsir: `أي كذب القوم نوحا عليه‌السلام فيما دعاهم إليه ، حتى أنهم كانوا يوسعونه ضربا ، وكان الرجل يأتي بابنه إلى نوح ، ويقول له : يا بني لا تؤمن بهذا ( فَأَنْجَيْناهُ وَالَّذِينَ ) آمنوا ( مَعَهُ ) ـ وفي بعض الروايات : أنهم كانوا ثمانية ـ ( فِي الْفُلْكِ ) أي السفينة ، حيث أمره الله سبحانه فعمل سفينة وركب هو والمؤمنون فيها ، ثم أمطرت السماء ، وتفجرت العيون ، حتى أخذ الماء وجه الأرض ، وهلك الكفار بأجمعهم ، ثم يبست الأرض وخرج نوح والمؤمنون ، يعمرون الأرض بتقوى الله من جديد ( وَأَغْرَقْنَا الَّذِينَ كَذَّبُوا بِآياتِنا ) أي بدلائلنا الدالة إِنَّهُمْ كانُوا قَوْماً عَمِينَ (64) وَإِلى عادٍ أَخاهُمْ هُوداً قالَ يا قَوْمِ اعْبُدُوا اللهَ ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ أَ فَلا تَتَّقُونَ (65) قالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ إِنَّا لَنَراكَ فِي سَفاهَةٍ على التوحيد والنبوة والمعاد ( إِنَّهُمْ ) أي المكذبون ( كانُوا قَوْماً عَمِينَ ) يقال : « رجل عم » إذا كان أعمى القلب ، ورجل أعمى إذا كان أعمى البصر ، وستأتي جوانب أخرى من قصة نوح عليه‌السلام في بعض السور الآتية ، كسورة هود وغيرها ، وحيث كان المقصود في الكتاب تفسير الآيات ـ حسب ظواهرها ـ نطوي القصة طيا.` },
            { text: "وَإِلَىٰ عَادٍ أَخَاهُمْ هُودًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥٓ أَفَلَا تَتَّقُونَ", tafsir: `أرسلنا ( إِلى عادٍ ) أي قبيلة عاد ، من أحفاد نوح عليه‌السلام ( أَخاهُمْ ) في النسب ( هُوداً ) وهو من أحفاد نوح عليه‌السلام ، وقد كان هود النبي من نفس القبيلة ليكون أقرب إلى القبول ، فإن غالب النفوس تأبى عن إطاعة غير بني قومهم ( قالَ ) هود لهم : ( يا قَوْمِ اعْبُدُوا اللهَ ) وحده لا شريك له ( ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ ) فإن الأصنام ليست بآلهة ( أَ فَلا تَتَّقُونَ ) استفهام إنكاري ، أي لماذا لا تتقون الشرك والمعاصي ؟` },
            { text: "قَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦٓ إِنَّا لَنَرَىٰكَ فِى سَفَاهَةٍ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلْكَٰذِبِينَ", tafsir: `الأشراف ( الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ ) والتعبير ب « كفروا » إما لتجريد الفعل عن معنى الحدوث ، وإما باعتبار الفطرة الإيمانية ، كما قال الرسول صلى‌الله‌عليه‌وآله‌وسلم : « كل مولود يولد على الفطرة » (1) ، وإما باعتبار المجموع فإن قومه ـ إذا اعتبروا من زمان نوح عليه‌السلام ـ كان فيهم بعض المؤمنين ( إِنَّا لَنَراكَ ) أي نعلمك ، يا هود ( فِي سَفاهَةٍ ) فأنت سفيه ، و « السفيه » هو ( 1) بحار الأنوار : ج 2 ص 12. وَإِنَّا لَنَظُنُّكَ مِنَ الْكاذِبِينَ (66) قالَ يا قَوْمِ لَيْسَ بِي سَفاهَةٌ وَلكِنِّي رَسُولٌ مِنْ رَبِّ الْعالَمِينَ (67) أُبَلِّغُكُمْ رِسالاتِ رَبِّي وَأَنَا لَكُمْ ناصِحٌ أَمِينٌ (68) أَ وَعَجِبْتُمْ أَنْ جاءَكُمْ ذِكْرٌ مِنْ رَبِّكُمْ عَلى رَجُلٍ مِنْكُمْ لِيُنْذِرَكُمْ وَاذْكُرُوا إِذْ جَعَلَكُمْ خُلَفاءَ مِنْ بَعْدِ قَوْمِ نُوحٍ الذي ليس له ملكة إصلاح لنفسه أو ماله ( وَإِنَّا لَنَظُنُّكَ مِنَ الْكاذِبِينَ ) فتكذب في دعوى النبوة ، وأنه ليس للعالم إلّا إله واحد.` },
            { text: "قَالَ يَٰقَوْمِ لَيْسَ بِى سَفَاهَةٌ وَلَٰكِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ", tafsir: `هود عليه‌السلام في جوابهم : ( يا قَوْمِ لَيْسَ بِي سَفاهَةٌ ) فإني لست سفيها وهل السفيه من ينطق بالحق الذي دلّ عليه العقل والفطرة ؟! ( وَلكِنِّي رَسُولٌ مِنْ رَبِّ الْعالَمِينَ ) وكلام السفيه غير كلام الرسول العاقل.` },
            { text: "أُبَلِّغُكُمْ رِسَٰلَٰتِ رَبِّى وَأَنَا۠ لَكُمْ نَاصِحٌ أَمِينٌ", tafsir: `أؤدّي إليكم ما أوحى إليّ من الرسالات ، والجمع باعتبار كل رسالة رسالة في مختلف الأصول والفروع ( وَأَنَا لَكُمْ ناصِحٌ ) أنصحكم لئلّا تقعوا في العقاب والعذاب ( أَمِينٌ ) في تأدية الرسالة فلا أكذّب ولا أغيّر. [70] وحيث كان القوم يظهرون عجبهم من رسالة هود عليه‌السلام قال لهم : ( أَ وَعَجِبْتُمْ ) أي هل تتعجبون ( أَنْ جاءَكُمْ ذِكْرٌ ) ووحي ( مِنْ ) قبل ( رَبِّكُمْ عَلى ) لسان ( رَجُلٍ مِنْكُمْ ) من قبيلتكم ( لِيُنْذِرَكُمْ ) ويخوّفكم من بأس الله سبحانه ( وَاذْكُرُوا ) أيها القوم نعمة الله عليكم ( إِذْ جَعَلَكُمْ خُلَفاءَ ) في الأرض ، أي تخلفون من سبقكم في أموالهم ومساكنهم ( مِنْ بَعْدِ قَوْمِ نُوحٍ ) فقد أهلكهم وأتى بكم مكانهم ، أ فلا وَزادَكُمْ فِي الْخَلْقِ بَصْطَةً فَاذْكُرُوا آلاءَ اللهِ لَعَلَّكُمْ تُفْلِحُونَ (69) قالُوا أَ جِئْتَنا لِنَعْبُدَ اللهَ وَحْدَهُ وَنَذَرَ ما كانَ يَعْبُدُ آباؤُنا فَأْتِنا بِما تَعِدُنا إِنْ كُنْتَ مِنَ الصَّادِقِينَ (70) قالَ قَدْ وَقَعَ عَلَيْكُمْ مِنْ رَبِّكُمْ رِجْسٌ وَغَضَبٌ تخافون أن يصيبكم ما أصابهم ، أم لا تشكرون ما وهب الله لكم من البلاد والأموال ( وَزادَكُمْ ) الله سبحانه ( فِي الْخَلْقِ بَصْطَةً ) هيكلا وقوّة. فقد كانوا أقوياء ذوي هياكل كبيرة عظيمة ( فَاذْكُرُوا آلاءَ اللهِ ) آلاء جمع « إلى » بمعنى « النّعم » ( لَعَلَّكُمْ تُفْلِحُونَ ) أي تفوزون بنعيم الدنيا وسعادة الآخرة.` },
            { text: "أَوَعَجِبْتُمْ أَن جَآءَكُمْ ذِكْرٌ مِّن رَّبِّكُمْ عَلَىٰ رَجُلٍ مِّنكُمْ لِيُنذِرَكُمْ وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ قَوْمِ نُوحٍ وَزَادَكُمْ فِى ٱلْخَلْقِ بَصْۜطَةً فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ لَعَلَّكُمْ تُفْلِحُونَ", tafsir: `` },
            { text: "قَالُوٓا۟ أَجِئْتَنَا لِنَعْبُدَ ٱللَّهَ وَحْدَهُۥ وَنَذَرَ مَا كَانَ يَعْبُدُ ءَابَآؤُنَا فَأْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ", tafsir: `أي قال قوم هود : ( أَ جِئْتَنا لِنَعْبُدَ اللهَ وَحْدَهُ ) بلا شريك ( وَنَذَرَ ) أي ندع عبادة ( ما كانَ يَعْبُدُ آباؤُنا ) من الأصنام ، وكيف يكون هذا ؟ فإنّا لن نترك الأصنام ( فَأْتِنا ) أي ادع ربك ليأتينا ( بِما تَعِدُنا ) من العذاب ( إِنْ كُنْتَ مِنَ الصَّادِقِينَ ) في أنه إن لم نؤمن نزل علينا العذاب.` },
            { text: "قَالَ قَدْ وَقَعَ عَلَيْكُم مِّن رَّبِّكُمْ رِجْسٌ وَغَضَبٌ أَتُجَٰدِلُونَنِى فِىٓ أَسْمَآءٍ سَمَّيْتُمُوهَآ أَنتُمْ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلْطَٰنٍ فَٱنتَظِرُوٓا۟ إِنِّى مَعَكُم مِّنَ ٱلْمُنتَظِرِينَ", tafsir: `هود عليه‌السلام لقومه : ( قَدْ وَقَعَ عَلَيْكُمْ ) أي وجب أن يقع ـ فإن المستقبل المتحقق الوقوع ينزّل منزلة الماضي ـ ( مِنْ رَبِّكُمْ رِجْسٌ ) أي عذاب ( وَغَضَبٌ ) حيث لم تؤمنوا بعد إتيان الحجة ، ووضوح الأدلة ، وحيث أن الله سبحانه منزّه عن الأحوال الزائدة ، كان المراد ب « غضب » عاقبة الغضب ، وهو العذاب ، كما قيل : « خذ الغايات واترك المبادئ » . وعليه فالفرق بين الرجس والغضب أن الثاني أعم من الأول. أَ تُجادِلُونَنِي فِي أَسْماءٍ سَمَّيْتُمُوها أَنْتُمْ وَآباؤُكُمْ ما نَزَّلَ اللهُ بِها مِنْ سُلْطانٍ فَانْتَظِرُوا إِنِّي مَعَكُمْ مِنَ الْمُنْتَظِرِينَ (71) فَأَنْجَيْناهُ وَالَّذِينَ مَعَهُ بِرَحْمَةٍ مِنَّا وَقَطَعْنا دابِرَ الَّذِينَ كَذَّبُوا بِآياتِنا وَما كانُوا مُؤْمِنِينَ (72) وَإِلى ثَمُودَ ثم ذكر هود عليه‌السلام بطلان أصنامهم قائلا : ( أَ تُجادِلُونَنِي ) أي هل أنتم تناظرون معي وتخاصمونني ( فِي أَسْماءٍ سَمَّيْتُمُوها أَنْتُمْ وَآباؤُكُمْ ) أي في أصنام سميتموها أنتم ربّا ، وإلا فهي أحجار منحوتة ، وإنما قال « في أسماء » إشارة إلى أن ربوبيتها مجرد اسم لا أكثر ( ما نَزَّلَ اللهُ بِها ) أي بتلك الأصنام والأسماء ( مِنْ سُلْطانٍ ) أي من دليل دال على كونها تصنع شيئا ، أو كونها آلهة وأربابا. وقد كان الاحتجاج منه عليه‌السلام قويا جدا ، إذ مدعي الآلهة الزائدة يحتاج إلى دليل وبرهان ( فَانْتَظِرُوا ) عذاب الله ونكاله ( إِنِّي مَعَكُمْ مِنَ الْمُنْتَظِرِينَ ) لنزول العذاب بكم ، وسترون صدق مقالتي. [73] فجاء العذاب الموعود إليهم ، وذلك أنه سبحانه ساق إليهم سحابة أمطرتهم بالعذاب حتى هلكوا جميعا وأنجيناه أي هودا عليه‌السلام ( وَالَّذِينَ مَعَهُ بِرَحْمَةٍ مِنَّا ) فلقد كان عليه‌السلام والمؤمنون في حظيرة لا يمرّ بهم العذاب ( وَقَطَعْنا دابِرَ الَّذِينَ كَذَّبُوا بِآياتِنا ) « الدابر » الأصل ، أي قطعنا أصلهم ، كما يقطع أصل الشجرة ، وذلك كناية عن إهلاكهم بأجمعهم ( وَما كانُوا مُؤْمِنِينَ ) أي لم يكونوا ليؤمنوا من بعد ، فقد عرفنا حالهم ، وعلمنا نواياهم وضمائرهم ومستقبلهم.` },
            { text: "فَأَنجَيْنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحْمَةٍ مِّنَّا وَقَطَعْنَا دَابِرَ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَمَا كَانُوا۟ مُؤْمِنِينَ", tafsir: `` },
            { text: "وَإِلَىٰ ثَمُودَ أَخَاهُمْ صَٰلِحًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمْ ءَايَةً فَذَرُوهَا تَأْكُلْ فِىٓ أَرْضِ ٱللَّهِ وَلَا تَمَسُّوهَا بِسُوٓءٍ فَيَأْخُذَكُمْ عَذَابٌ أَلِيمٌ", tafsir: `أرسلنا ( إِلى ثَمُودَ ) وهي قبيلة من آل رجل يسمى « ثمود » من أَخاهُمْ صالِحاً قالَ يا قَوْمِ اعْبُدُوا اللهَ ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ قَدْ جاءَتْكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ هذِهِ ناقَةُ اللهِ لَكُمْ آيَةً أحفاد نوح عليه‌السلام ( أَخاهُمْ ) في النسب ( صالِحاً ) حيث كان صالح من نفس القبيلة ( قالَ ) صالح عليه‌السلام لهم : ( يا قَوْمِ اعْبُدُوا اللهَ ) وحده ولا تشركوا به شيئا ( ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ ) فتعبدوه معه ( قَدْ جاءَتْكُمْ بَيِّنَةٌ ) أي دلالة ومعجزة ( مِنْ رَبِّكُمْ ) شاهدة على صدق ادعائي للنبوة ( هذِهِ ناقَةُ اللهِ ) الإضافة إلى الله تشريفية ، كإضافة مكة إلى الله يقال : « بيت الله » ، وإضافة دم الحسين عليه‌السلام إلى الله ، يقال : « ثار الله » ( لَكُمْ آيَةً ) دالة على صدق كلامي. وقد كان من قصة صالح ما ورد : أنه بعث إلى قومه وهو ابن ست عشرة سنة فلبث فيهم حتى بلغ عشرين ومائة سنة لا يجيبونه إلى خير ، وكان لهم سبعون صنما ، يعبدونها من دون الله ، فقال لهم : إن شئتم فاسألوني حتى أسأل إلهي فيجيبكم فيما سألتموني الساعة ، وإن شئتم سألت آلهتكم ، فإن أجابتني بالذي أسألها خرجت عنكم ، فقد سئمتكم وسئمتموني ، فقالوا : قد أنصفت ، فدعاها كلها بأسمائها فلم يجبه منها شيء فنحّوا بسطهم وفرشهم وثيابهم وتمرغوا على التراب وطرحوا التراب على رؤوسهم ، وقالوا لأصنامهم : لئن لم تجيبوا صالحا اليوم لنفتضحنّ ، ثم دعوه فقالوا : يا صالح ادعها ، فدعاها فلم تجبه. قال صالح : فاسألوني حتى أدعو إلهي يجبكم الساعة ، فقالوا : ادع لنا ربك يخرج لنا من هذا الجبل الساعة ناقة حمراء شقراء وبراء عشراء بين جبينها ميل ، فقال لهم : سألتموني شيئا يعظم عليّ ويهون على ربي فَذَرُوها تَأْكُلْ فِي أَرْضِ اللهِ وَلا تَمَسُّوها بِسُوءٍ فَيَأْخُذَكُمْ عَذابٌ أَلِيمٌ (73) وَاذْكُرُوا إِذْ جَعَلَكُمْ خُلَفاءَ مِنْ بَعْدِ عادٍ وَبَوَّأَكُمْ فِي الْأَرْضِ تعالوا ، فسأل الله ذلك ، فانصدع الجبل صدعا كادت تطير منه عقولهم لما سمعوا ذلك ، ثم اضطرب ذلك الجبل اضطرابا شديدا كالمرأة إذا أخذها المخاض ، ثم لم يفاجئهم إلا رأسها قد طلع عليهم من ذلك الصدع فما استتمّت رقبتها حتى اجترّت ، ثم خرج سائر جسدها ، ثم استوت قائمة على الأرض ، فلما رأوا ذلك قالوا : يا صالح ما أسرع ما أجابك ربك ، ادع لنا يخرج لنا فصيلها ، فسأل الله ذلك فرمت به فدبّ حولها ، فقال لهم : يا قوم أبقي شيء ؟ قالوا : لا ، انطلق بنا إلى قومنا نخبرهم بما رأينا ويؤمنون بك. قال الراوي : فرجعوا فلم يبلغ السبعون إليهم حتى ارتد منهم أربعة وستون رجلا ، وقالوا : سحر وكذب. قال : فانتبهوا إلى الجميع فقال الستة : حق ، وقال الجميع : كذب وسحر ، فانصرفوا على ذلك ثم ارتاب واحد فكان فيمن عقرها (1) . ( فَذَرُوها ) أي دعوها واتركوها وشأنها ( تَأْكُلْ فِي أَرْضِ اللهِ ) من نبات الأرض ( وَلا تَمَسُّوها بِسُوءٍ ) وأذية ( فَيَأْخُذَكُمْ ) أي ينالكم ويصيبكم ( عَذابٌ أَلِيمٌ ) مؤلم موجع.` },
            { text: "وَٱذْكُرُوٓا۟ إِذْ جَعَلَكُمْ خُلَفَآءَ مِنۢ بَعْدِ عَادٍ وَبَوَّأَكُمْ فِى ٱلْأَرْضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورًا وَتَنْحِتُونَ ٱلْجِبَالَ بُيُوتًا فَٱذْكُرُوٓا۟ ءَالَآءَ ٱللَّهِ وَلَا تَعْثَوْا۟ فِى ٱلْأَرْضِ مُفْسِدِينَ", tafsir: `نعمة الله عليكم ( إِذْ جَعَلَكُمْ خُلَفاءَ ) في الأرض بأن أورثكم إياها ومكّنكم فيها ( مِنْ بَعْدِ عادٍ ) الذين أهلكوا حيث عصوا ربهم ( وَبَوَّأَكُمْ ) أي جعل لكم بيوتا ومساكن ( فِي الْأَرْضِ ) بحيث ( 1) راجع بحار الأنوار : ج 11 ص 377. تَتَّخِذُونَ مِنْ سُهُولِها قُصُوراً وَتَنْحِتُونَ الْجِبالَ بُيُوتاً فَاذْكُرُوا آلاءَ اللهِ وَلا تَعْثَوْا فِي الْأَرْضِ مُفْسِدِينَ (74) قالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِنْ قَوْمِهِ لِلَّذِينَ اسْتُضْعِفُوا لِمَنْ آمَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صالِحاً مُرْسَلٌ مِنْ رَبِّهِ قالُوا إِنَّا بِما أُرْسِلَ بِهِ مُؤْمِنُونَ (75) ( تَتَّخِذُونَ مِنْ سُهُولِها ) أي سهول الأرض ( قُصُوراً وَتَنْحِتُونَ الْجِبالَ بُيُوتاً ) وهذه نعمة كبري إذ جعل لكم الأرض ذلولا سهولها وجبالها ( فَاذْكُرُوا آلاءَ اللهِ ) أي نعم الله عليكم ، وقد تقدم أن « آلاء » جمع « إلى » بمعنى النعمة ( وَلا تَعْثَوْا ) أي : لا تطغوا وتسعوا ، من « العثا » بمعنى شدة الفساد ( فِي الْأَرْضِ مُفْسِدِينَ ) فلا تثيروا الفساد في الأرض.` },
            { text: "قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لِلَّذِينَ ٱسْتُضْعِفُوا۟ لِمَنْ ءَامَنَ مِنْهُمْ أَتَعْلَمُونَ أَنَّ صَٰلِحًا مُّرْسَلٌ مِّن رَّبِّهِۦ قَالُوٓا۟ إِنَّا بِمَآ أُرْسِلَ بِهِۦ مُؤْمِنُونَ", tafsir: `أي جماعة الأشراف ( الَّذِينَ اسْتَكْبَرُوا ) عن قبول الحق ، ورفعوا أنفسهم عن ذلك ( مِنْ قَوْمِهِ ) أي من قوم صالح ( لِلَّذِينَ اسْتُضْعِفُوا ) أي للمؤمنين الذين نظر إليهم المستكبرون بنظر الضعف والضعة ( لِمَنْ آمَنَ مِنْهُمْ ) ـ بدل من قوله : ( « لِلَّذِينَ اسْتُضْعِفُوا ) وإنما جيء به لئلّا يظن أن المراد « المستضعف في الدين » ـ : ( أَ تَعْلَمُونَ أَنَّ صالِحاً مُرْسَلٌ مِنْ رَبِّهِ ) وأنه رسول من الله. وكان هذا السؤال منهم مقدمة لكلامهم أنهم غير مؤمنين به ( قالُوا ) أي : المؤمنون : ( إِنَّا بِما أُرْسِلَ ) صالح ( بِهِ مُؤْمِنُونَ ) فنعتقد بإله واحد وبرسالته وبما جاء به. ( قالَ الَّذِينَ اسْتَكْبَرُوا إِنَّا بِالَّذِي آمَنْتُمْ بِهِ كافِرُونَ (76) فَعَقَرُوا النَّاقَةَ وَعَتَوْا عَنْ أَمْرِ رَبِّهِمْ وَقالُوا` },
            { text: "قَالَ ٱلَّذِينَ ٱسْتَكْبَرُوٓا۟ إِنَّا بِٱلَّذِىٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ", tafsir: `السائلون ـ بعد سماعهم لكلام المؤمنين ـ : ( إِنَّا بِالَّذِي آمَنْتُمْ بِهِ ) من التوحيد والرسالة ( كافِرُونَ ) جاحدون منكرون.` },
            { text: "فَعَقَرُوا۟ ٱلنَّاقَةَ وَعَتَوْا۟ عَنْ أَمْرِ رَبِّهِمْ وَقَالُوا۟ يَٰصَٰلِحُ ٱئْتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلْمُرْسَلِينَ", tafsir: `أي : قتلوها ، و « العقر » الجرح الذي يأتي على أصل النفس. ورد أن الله أوحى إلى صالح عليه‌السلام : قل لهم : إن الله قد جعل لهذه الناقة من الماء شرب يوم ، ولكم شرب يوم ، فكانت الناقة إذا كان يوم شربها شربت ذلك اليوم ، فيحلبونها فلا يبقى صغير ولا كبير إلا شرب من لبنها يومهم ذلك ، فإذا كان الليل وأصبحوا غدوا إلى مائهم فشربوا منه ذلك اليوم ولم تشرب الناقة ذلك اليوم ، فمكثوا بذلك إلى ما شاء الله ثم أنهم عتوا على الله ومشى بعضهم إلى بعض وقالوا : اعقروا هذه الناقة واستريحوا منها لا نرضى أن يكون لها شرب يوم ولنا شرب يوم ، فجعلوا حبلا لرجل أحمر أشقر أزرق من ولد الزنا لا يعرف له أب يقال له : « قدار » شقي من الأشقياء مشؤوم عليهم فقتلها وهرب فصيلها ، واقتسموا لحمها فيما بينهم ، فأوحى الله إلى صالح : قل لهم : إني مرسل إليكم عذابي إلى ثلاثة أيام ، فإن تابوا ورجعوا قبلت توبتهم عنهم ، وإن لم يتوبوا بعثت عليهم عذابي في اليوم الثالث (1) . ( وَعَتَوْا عَنْ أَمْرِ رَبِّهِمْ ) أي تجاوزوا الحد في الفساد ( وَقالُوا ( 1) الكافي : ج 8 ص 187. يا صالِحُ ائْتِنا بِما تَعِدُنا إِنْ كُنْتَ مِنَ الْمُرْسَلِينَ (77) فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِي دارِهِمْ جاثِمِينَ (78) فَتَوَلَّى عَنْهُمْ وَقالَ يا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسالَةَ رَبِّي وَنَصَحْتُ لَكُمْ يا صالِحُ ائْتِنا بِما تَعِدُنا ) من العذاب على قتل الناقة والبقاء في الكفر ( إِنْ كُنْتَ مِنَ الْمُرْسَلِينَ ) ثم أخبر سبحانه بما حلّ بهم من العذاب.` },
            { text: "فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ", tafsir: `« الرجف » الاضطراب ( فَأَصْبَحُوا فِي دارِهِمْ ) أي في محلهم ، يقول الحاضر : « أنا في داري » أي بلدي ومحلتي ( جاثِمِينَ ) أي صرعى ميّتين ساقطين لا حركة لهم. ورد أن صالح لما وعدهم بالعذاب وأمهلهم ثلاثة أيام ، قال صالح عليه‌السلام : إنكم تصبحون وجوهكم مصفرّة ، واليوم الثاني محمرة ، والثالث مسودة. فجاءهم ما قاله لهم فلم يتوبوا ولم يرجعوا ، فلما كان منتصف الليل أتاهم جبريل فصرخ بهم صرخة خرقت أسماعهم وفلقت قلوبهم وصدعت أكبادهم. وفي بعض التفاسير : إن النار كانت تصحب الصيحة حيث أخذتهم. ولعل تسمية ذلك بالرجفة لأجل الاضطراب الحاصل للإنسان حينما يسمع صيحة مهولة (1) .` },
            { text: "فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَالَةَ رَبِّى وَنَصَحْتُ لَكُمْ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ", tafsir: `أي أعرض صالح عليه‌السلام ( عَنْهُمْ ) حين رأى إصرارهم على الكفر ( وَقالَ يا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسالَةَ رَبِّي وَنَصَحْتُ لَكُمْ ) أدّيت النصح الذي يسعدكم في دنياكم وأخراكم ( 1) مجمع البيان : ج 4 ص 296. وَلكِنْ لا تُحِبُّونَ النَّاصِحِينَ (79) وَلُوطاً إِذْ قالَ لِقَوْمِهِ أَ تَأْتُونَ الْفاحِشَةَ ما سَبَقَكُمْ بِها مِنْ أَحَدٍ مِنَ الْعالَمِينَ (80) إِنَّكُمْ لَتَأْتُونَ الرِّجالَ شَهْوَةً مِنْ دُونِ النِّساءِ ( وَلكِنْ لا تُحِبُّونَ النَّاصِحِينَ ) فلا تقبلون نصحي. ولعل سر تأخير هذه الجملة ، عن جملة « فأخذتهم الرجفة » مع تقديمها في ظرف الوقوع عليها ، إيهام السياق سرعة الخاتمة ، حتى لا يكون فصل بين الإعراض وبين العذاب في اللفظ ، وهذا من فنون البلاغة ، لكن حيث أن مصير صالح عليه‌السلام لم يعلم مما قبل ، استأنف السياق ذكر مصيره وأنه نفض يديه منهم ، وتركهم ليلاقوا ما جلبوه على أنفسهم ، دونه.` },
            { text: "وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنْ أَحَدٍ مِّنَ ٱلْعَٰلَمِينَ", tafsir: `اذكر ( لُوطاً ) ولعلّ اختلاف السياق هنا عمّا سبقه ، حيث كان يقول : « وإلى » ، تنبيه عدم التعرض لمن توسطهما من الأنبياء ، كإبراهيم عليه‌السلام الذي كان معاصرا للوط ، وإنما لم يذكر إبراهيم عليه‌السلام لعله لعدم نزول عقاب على قومه كما نزل على قوم لوط ، وقوم الأنبياء السابقي الذكر ( إِذْ قالَ لِقَوْمِهِ أَ تَأْتُونَ الْفاحِشَةَ ) ؟ على نحو الاستفهام الإنكاري ، والمراد ب « الفاحشة » المعصية المتجاوزة للحدود ، وهي اللواط بالرجال ( ما سَبَقَكُمْ بِها ) أي بهذه الفاحشة ( مِنْ أَحَدٍ مِنَ الْعالَمِينَ ) فإن قوم لوط أول من تعاطى هذا العمل الشنيع.` },
            { text: "إِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ بَلْ أَنتُمْ قَوْمٌ مُّسْرِفُونَ", tafsir: `أي إتيانا شهويا ، فإن لفظ « أتى » بدون هذا القيد « الشهوة » يكون بمعنى « جاء » ( مِنْ دُونِ النِّساءِ ) فلا تأتون المباح ، وتأتون المحرّم ، ولعلّ عدم الإتيان لهن كان أيضا محرما ، كما بَلْ أَنْتُمْ قَوْمٌ مُسْرِفُونَ (81) وَما كانَ جَوابَ قَوْمِهِ إِلاَّ أَنْ قالُوا أَخْرِجُوهُمْ مِنْ قَرْيَتِكُمْ إِنَّهُمْ أُناسٌ يَتَطَهَّرُونَ (82) فَأَنْجَيْناهُ وَأَهْلَهُ إِلاَّ امْرَأَتَهُ كانَتْ مِنَ الْغابِرِينَ (83) وَأَمْطَرْنا عَلَيْهِمْ مَطَراً أنه كذلك عندنا ، بعد أربعة أشهر ( بَلْ أَنْتُمْ قَوْمٌ مُسْرِفُونَ ) متجاوزون في الظلم والفساد ، فإن الإسراف بمعنى التجاوز.` },
            { text: "وَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوهُم مِّن قَرْيَتِكُمْ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ", tafsir: `أي جواب القوم للوط عليه‌السلام الذي كان ينهاهم عن اللواط ( إِلَّا أَنْ قالُوا ) أي قال بعضهم لبعض ( أَخْرِجُوهُمْ ) أي أخرجوا لوطا وأهله ( مِنْ قَرْيَتِكُمْ ) أي مدينتكم ، وهي « سدوم » ( إِنَّهُمْ أُناسٌ يَتَطَهَّرُونَ ) أي يتحرّجون عن هذا العمل ، من أجل الطهارة والنزاهة.` },
            { text: "فَأَنجَيْنَٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ كَانَتْ مِنَ ٱلْغَٰبِرِينَ", tafsir: `أي خلصنا لوطا ( وَأَهْلَهُ إِلَّا امْرَأَتَهُ ) من العذاب النازل بقومه ، حيث أمرناهم بالسير والفرار من المدينة ، ففروا جميعا إلا زوجته ( كانَتْ مِنَ الْغابِرِينَ ) أي الباقين في قومه المتخلفين عن لوط ، وإنما بقيت وهلكت لأنها كانت على طريقتهم ، كما قال سبحانه في آية أخرى : ( ضَرَبَ اللهُ مَثَلاً لِلَّذِينَ كَفَرُوا امْرَأَتَ نُوحٍ وَامْرَأَتَ لُوطٍ كانَتا تَحْتَ عَبْدَيْنِ مِنْ عِبادِنا صالِحَيْنِ فَخانَتاهُما ) (1) ، إذ لم تؤمنا بما آمن به زوجيهما.` },
            { text: "وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُجْرِمِينَ", tafsir: `أي أرسلنا عليهم الحجارة كالمطر ، كما قال ( 1) التحريم : 11. فَانْظُرْ كَيْفَ كانَ عاقِبَةُ الْمُجْرِمِينَ (84) وَإِلى مَدْيَنَ أَخاهُمْ شُعَيْباً قالَ يا قَوْمِ اعْبُدُوا اللهَ ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ قَدْ جاءَتْكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ فَأَوْفُوا الْكَيْلَ وَالْمِيزانَ وَلا تَبْخَسُوا النَّاسَ أَشْياءَهُمْ وَلا تُفْسِدُوا فِي الْأَرْضِ تعالى في آية أخرى : ( وَأَمْطَرْنا عَلَيْهِمْ حِجارَةً مِنْ سِجِّيلٍ ) (1) ، ثم قلبت مدينتهم حتى جعل عاليها سافلها ( فَانْظُرْ ) أي فاعلم يا رسول الله ، أو أيها الناظر ( كَيْفَ كانَ عاقِبَةُ الْمُجْرِمِينَ ) المرتكبين للسيئات.` },
            { text: "وَإِلَىٰ مَدْيَنَ أَخَاهُمْ شُعَيْبًا قَالَ يَٰقَوْمِ ٱعْبُدُوا۟ ٱللَّهَ مَا لَكُم مِّنْ إِلَٰهٍ غَيْرُهُۥ قَدْ جَآءَتْكُم بَيِّنَةٌ مِّن رَّبِّكُمْ فَأَوْفُوا۟ ٱلْكَيْلَ وَٱلْمِيزَانَ وَلَا تَبْخَسُوا۟ ٱلنَّاسَ أَشْيَآءَهُمْ وَلَا تُفْسِدُوا۟ فِى ٱلْأَرْضِ بَعْدَ إِصْلَٰحِهَا ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ", tafsir: `أرسلنا ( إِلى مَدْيَنَ ) هم قبيلة سميت باسم جدّهم « مدين » حفيد إبراهيم عليه‌السلام ( أَخاهُمْ شُعَيْباً ) وهو من أحفاد إبراهيم عليه‌السلام ، فهو أخ القبيلة ( قالَ يا قَوْمِ اعْبُدُوا اللهَ ) وحده لا شريك له ( ما لَكُمْ مِنْ إِلهٍ غَيْرُهُ ) من الأصنام التي تبعدونها ( قَدْ جاءَتْكُمْ بَيِّنَةٌ مِنْ رَبِّكُمْ ) دلالة واضحة تدل على صدقي. والظاهر أن المراد « المعجزة » ، فإن الأنبياء كانوا مزوّدين بالإعجاز ( فَأَوْفُوا الْكَيْلَ وَالْمِيزانَ ) أخذا وعطاء ، فلا تأخذوا زائدا ولا تعطوا ناقصا ( وَلا تَبْخَسُوا النَّاسَ ) من « بخس » بمعنى « نقص » ( أَشْياءَهُمْ ) أي لا تعطوهم ناقصا حيث إن الشيء المباع هو ملك المشتري ، فيكون الشيء للناس ، ولذا أضيف إليهم ( وَلا تُفْسِدُوا فِي الْأَرْضِ ) بأن ( 1) الحجر : 75. بَعْدَ إِصْلاحِها ذلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ مُؤْمِنِينَ (85) وَلا تَقْعُدُوا بِكُلِّ صِراطٍ تُوعِدُونَ وَتَصُدُّونَ عَنْ سَبِيلِ اللهِ مَنْ آمَنَ بِهِ وَتَبْغُونَها عِوَجاً تعملوا بالمعاصي ( بَعْدَ إِصْلاحِها ) لا يراد بذلك الإصلاح التام ، بل المعنى أن لا تأتوا بالفاسد مكان الصالح ، فإن الفساد إنما يتدرج إلى المجتمع ، أو المراد : لا تفسدوا بعد ما أصلح الأنبياء الأرض. ( ذلِكُمْ ) الذي أمرتكم به من إتيان الواجبات وترك المحرمات ( خَيْرٌ لَكُمْ ) أي أنفع مما أنتم فيه ، وكأن الإتيان بصفة التفضيل في أمثال المقام ، للفضل المتوهم في الطرف الآخر ، مثلا : كان هؤلاء يزعمون أن ما يعملونه في الفضل ، فقيل لهم : إن ما تدعون إليه خير ( إِنْ كُنْتُمْ مُؤْمِنِينَ ) وهؤلاء وإن لم يكونوا مؤمنين لكن الشرط في أمثال المقام مرتبط بفعل مقدر ، أي إن كنتم مؤمنين لعلمتم أنه خير لكم ـ كما ذكره أهل الأدب ـ.` },
            { text: "وَلَا تَقْعُدُوا۟ بِكُلِّ صِرَٰطٍ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنْ ءَامَنَ بِهِۦ وَتَبْغُونَهَا عِوَجًا وَٱذْكُرُوٓا۟ إِذْ كُنتُمْ قَلِيلًا فَكَثَّرَكُمْ وَٱنظُرُوا۟ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ", tafsir: `فإنهم كانوا قطاع طرق ، يقعدون في الطرق ، يوعدون الناس بالقتل والإيذاء إن لم يرضخوا للنهب والسلب ( وَتَصُدُّونَ عَنْ سَبِيلِ اللهِ ) أي تمنعون عن إيمان الناس ، فقد كانوا يمنعون الناس عن الإيمان بشعيب ( مَنْ آمَنَ بِهِ ) أي من أراد الإيمان ، أو المراد صد المؤمنين عن القيام بوظائف الإيمان ( وَتَبْغُونَها ) أي تطلبون السبيل ( عِوَجاً ) أي تريدون الطريق المعوجّ ، ولا تريدون الطريق المستقيم ، أو المراد تتصيدون الاعوجاج لسبيل الله تعالى ، فإن أهل الباطل دائما يفكرون في نقد الحق ، حتى يروه للناس أعوج. وَاذْكُرُوا إِذْ كُنْتُمْ قَلِيلاً فَكَثَّرَكُمْ وَانْظُرُوا كَيْفَ كانَ عاقِبَةُ الْمُفْسِدِينَ (86) وَإِنْ كانَ طائِفَةٌ مِنْكُمْ آمَنُوا بِالَّذِي أُرْسِلْتُ بِهِ وَطائِفَةٌ لَمْ يُؤْمِنُوا فَاصْبِرُوا حَتَّى يَحْكُمَ اللهُ بَيْنَنا ( وَاذْكُرُوا ) أيها القوم ( إِذْ كُنْتُمْ قَلِيلاً ) في العدد ( فَكَثَّرَكُمْ ) الله فإن جدّهم « مدين » كان واحدا ، ثم كثروا ، كما هو شأن كل قبيلة ، فاشكروا أيها القوم هذه النعمة ( وَانْظُرُوا ) تفكروا وتدبروا ( كَيْفَ كانَ عاقِبَةُ الْمُفْسِدِينَ ) من الأمم التي تقدمتكم ، حيث أهلكت بعذاب الله سبحانه لما فسدوا وأفسدوا وخالفوا أوامر الله سبحانه ، فخافوا أيها القوم نكال الله وعقابه. [88] ولا يغرّنكم أيها القوم تفرق الناس عني بين مؤمن وكافر ، فإن المصلحين يتفرّق الناس عنهم فرقتين دائما ، وقبل شروعهم في الإصلاح ، ويكون الناس حولهم فرقة واحدة موالية ، ولا يخفى أن هذا لا يكون سببا لأن يزعم كل من تفرّق الناس عنه فرقتين أنه مصلح وعلى حق ، فإن العاقبة للحق والضمائر تشهد بالصدق والكذب ، وهاتان علامتان مميزتان بين المحق والمبطل ، ولذا تمسك شعيب عليه‌السلام بقوله : « فاصبروا » . ( وَإِنْ كانَ طائِفَةٌ مِنْكُمْ آمَنُوا بِالَّذِي أُرْسِلْتُ بِهِ ) بأن صدقوني وقبلوا رسالتي ( وَطائِفَةٌ ) أخرى ( لَمْ يُؤْمِنُوا ) بل جحدوا وبقوا على كفرهم ( فَاصْبِرُوا ) أيها القوم ، المؤمن منكم والكافر ( حَتَّى يَحْكُمَ اللهُ بَيْنَنا ) في الدنيا بإعلاء كلمة الدين وإبطال كلمة الكافرين ، أما في وَهُوَ خَيْرُ الْحاكِمِينَ (87) الآخرة فهو شيء واضح ( وَهُوَ خَيْرُ الْحاكِمِينَ ) لأنه لا يجور في الحكم ، عن عمد أو غير عمد ، بل يعطي كل ذي حق حقه ، ( وَإِنْ كانَ مِثْقالَ حَبَّةٍ مِنْ خَرْدَلٍ أَتَيْنا بِها وَكَفى بِنا حاسِبِينَ ) (1) . ( 1) الأنبياء : 48. تقريب القران الى الأذهان من آية 89 من سورة الأعراف إلى آية 41 من سورة الأنفال بسم الله الرّحمن الرّحيم الحمد لله رب العالمين ، والصلاة والسلام على أشرف الأنبياء والمرسلين محمد المصطفى وعترته الطاهرين قالَ الْمَلَأُ الَّذِينَ اسْتَكْبَرُوا مِنْ قَوْمِهِ لَنُخْرِجَنَّكَ يا شُعَيْبُ وَالَّذِينَ آمَنُوا مَعَكَ مِنْ قَرْيَتِنا أَوْ لَتَعُودُنَّ فِي مِلَّتِنا قالَ أَ وَلَوْ كُنَّا كارِهِينَ (88) قَدِ افْتَرَيْنا عَلَى اللهِ كَذِباً إِنْ عُدْنا فِي مِلَّتِكُمْ بَعْدَ إِذْ نَجَّانَا اللهُ مِنْها` },
            { text: "وَإِن كَانَ طَآئِفَةٌ مِّنكُمْ ءَامَنُوا۟ بِٱلَّذِىٓ أُرْسِلْتُ بِهِۦ وَطَآئِفَةٌ لَّمْ يُؤْمِنُوا۟ فَٱصْبِرُوا۟ حَتَّىٰ يَحْكُمَ ٱللَّهُ بَيْنَنَا وَهُوَ خَيْرُ ٱلْحَٰكِمِينَ", tafsir: `` },
            { text: "قَالَ ٱلْمَلَأُ ٱلَّذِينَ ٱسْتَكْبَرُوا۟ مِن قَوْمِهِۦ لَنُخْرِجَنَّكَ يَٰشُعَيْبُ وَٱلَّذِينَ ءَامَنُوا۟ مَعَكَ مِن قَرْيَتِنَآ أَوْ لَتَعُودُنَّ فِى مِلَّتِنَا قَالَ أَوَلَوْ كُنَّا كَٰرِهِينَ", tafsir: `جماعة الأشراف ( الَّذِينَ اسْتَكْبَرُوا ) رفعوا أنفسهم فوق مقدارها وعتوا وطغوا ( مِنْ قَوْمِهِ ) أي من قوم شعيب ( لَنُخْرِجَنَّكَ ) بكل تأكيد ( يا شُعَيْبُ وَ ) لنخرجنّ ( الَّذِينَ آمَنُوا مَعَكَ مِنْ قَرْيَتِنا ) أي بلدنا ( أَوْ لَتَعُودُنَّ فِي مِلَّتِنا ) « الملّة » هي الطريقة ، أي ارجعوا كفارا كما كنتم ، والعود في الملة إما باعتبار الغالب ، فأدخل فيه شعيبا عليه‌السلام تغليبا ، فإن المؤمنين به كانوا كفارا ثم آمنوا ، أو لزعمهم أن شعيبا عليه‌السلام كان منهم حيث كان أحدهم قبل ادّعاء النبوة ، وإما بمعنى الصيرورة ، فإن « عاد » يستعمل بمعنى « صار » ، كما قال الشاعر : تلك المكارم لا ثعبان من لبن شيبا بماء فعادا بعد أبوالا ( قالَ ) شعيب عليه‌السلام لهم : أ تعيدوننا في ملتكم وتدخلوننا إليها ( أَ وَلَوْ كُنَّا كارِهِينَ ) للدخول فيها ؟ أي : أ تجبروننا على ذلك ؟ ولعل القصد : إنكم لا تقدرون على ذلك في حين كراهيتنا لذلك ، فإن العقائد لا تزول بالإكراه والإجبار. [90] ثم قال شعيب : إنه من المستحيل أن نتخذ طريقتكم ، إذ ( قَدِ افْتَرَيْنا عَلَى اللهِ كَذِباً إِنْ عُدْنا فِي مِلَّتِكُمْ ) بأن نجعل لله شريكا ، ونحلّل حرامه ، ونحرّم حلاله وننسب كل ذلك إليه ( بَعْدَ إِذْ نَجَّانَا اللهُ مِنْها ) وَما يَكُونُ لَنا أَنْ نَعُودَ فِيها إِلاَّ أَنْ يَشاءَ اللهُ رَبُّنا وَسِعَ رَبُّنا كُلَّ شَيْءٍ عِلْماً عَلَى اللهِ تَوَكَّلْنا رَبَّنَا افْتَحْ بَيْنَنا وَبَيْنَ قَوْمِنا بِالْحَقِّ وَأَنْتَ بأن أوضح الحق وأقام الحجة عليه ( وَما يَكُونُ لَنا ) أي لا يجوز لنا ( أَنْ نَعُودَ فِيها إِلَّا أَنْ يَشاءَ اللهُ رَبُّنا ) وهذا من التعليق على المحال ، لأن الله لا يشاء الكفر والعصيان ، كما قال : ( إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) (1) ، وقال : ( حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِياطِ ) (2) ، أو المراد مشيئة الله بسلب التوفيق منهم ، وهذا ممكن بالنسبة إلى بعض المؤمنين الذين لا رسوخ لإيمانهم ، كما ارتد بعضهم بعد رسول الله صلى‌الله‌عليه‌وآله‌وسلم ، وحيث أن العود بالنسبة إلى كل واحد واحد صح ذلك ( وَسِعَ رَبُّنا كُلَّ شَيْءٍ عِلْماً ) أي وسع علمه سبحانه كل شيء ، فهو أعلم بالصلاح وأعلم بالواقع والحقيقة ، فما كان من عبادتنا لتوحيده ، بأمره ونهيه ، هو الصحيح دون ما أنتم عليه من الشرك والعناد ( عَلَى اللهِ تَوَكَّلْنا ) في أمورنا ، فلا نخاف من تهديدكم بإخراجنا. ثم دعا شعيب عليه‌السلام قائلا : ( رَبَّنَا افْتَحْ بَيْنَنا وَبَيْنَ قَوْمِنا بِالْحَقِ ) ومعنى « الفتح » النجاة ووضوح الحق ، إذ الواقع في المشكلة كأن الطريق مسدود أمامه ، كما أن من يريد الهداية يرى الضلال حاجزا ، فيطلب الفتح لهذا الحاجز وإزالته ليرى الحق ، وقيد « بالحق » توضيحي ، لإفادة أن فتحه سبحانه بالحق ، أو احترازي لأن الفتح يطلق على الفتح بالباطل ـ كما يفتح الكافر مدينة ما ـ والفتح بالحق ( وَأَنْتَ ) يا إلهنا ( 1) الزخرف : 82. ( 2) الأعراف : 41. خَيْرُ الْفاتِحِينَ (89) وَقالَ الْمَلَأُ الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ لَئِنِ اتَّبَعْتُمْ شُعَيْباً إِنَّكُمْ إِذاً لَخاسِرُونَ (90) فَأَخَذَتْهُمُ الرَّجْفَةُ فَأَصْبَحُوا فِي دارِهِمْ جاثِمِينَ (91) ( خَيْرُ الْفاتِحِينَ ) فإن سائر الفاتحين قد يظلم عمدا أو خطأ أو جهلا ، أما الله سبحانه فلا يحيد فتحه عن الحق ، قيد شعرة. [91] ثم بيّن سبحانه ما قالت جماعة شعيب بعضهم لبعض ( وَقالَ الْمَلَأُ ) أي جماعة الأشراف ( الَّذِينَ كَفَرُوا مِنْ قَوْمِهِ ) أي من قوم شعيب ، بعضهم لبعض : ( لَئِنِ اتَّبَعْتُمْ شُعَيْباً ) في دينه وطريقته ( إِنَّكُمْ إِذاً لَخاسِرُونَ ) خسرتم منافعكم وطريقة آبائكم.` },
            { text: "قَدِ ٱفْتَرَيْنَا عَلَى ٱللَّهِ كَذِبًا إِنْ عُدْنَا فِى مِلَّتِكُم بَعْدَ إِذْ نَجَّىٰنَا ٱللَّهُ مِنْهَا وَمَا يَكُونُ لَنَآ أَن نَّعُودَ فِيهَآ إِلَّآ أَن يَشَآءَ ٱللَّهُ رَبُّنَا وَسِعَ رَبُّنَا كُلَّ شَىْءٍ عِلْمًا عَلَى ٱللَّهِ تَوَكَّلْنَا رَبَّنَا ٱفْتَحْ بَيْنَنَا وَبَيْنَ قَوْمِنَا بِٱلْحَقِّ وَأَنتَ خَيْرُ ٱلْفَٰتِحِينَ", tafsir: `` },
            { text: "وَقَالَ ٱلْمَلَأُ ٱلَّذِينَ كَفَرُوا۟ مِن قَوْمِهِۦ لَئِنِ ٱتَّبَعْتُمْ شُعَيْبًا إِنَّكُمْ إِذًا لَّخَٰسِرُونَ", tafsir: `` },
            { text: "فَأَخَذَتْهُمُ ٱلرَّجْفَةُ فَأَصْبَحُوا۟ فِى دَارِهِمْ جَٰثِمِينَ", tafsir: `أي الزلزلة ، أو الصيحة ، الموجبة للرجف والاضطراب ( فَأَصْبَحُوا فِي دارِهِمْ ) أي محلهم وبلدهم ( جاثِمِينَ ) أي ميتين ملقين لا حراك فيهم. في المجمع : قيل : أرسل الله عليهم رمدة « أي هلاكا جعلهم كالرماد » وحرا شديدا فأخذ بأنفاسهم ، فدخلوا أجواف البيوت ، فدخل عليهم البيوت ، فلم ينفعهم ظل ولا ماء وأنضجهم الحرّ ، فبعث الله تعالى سحابة فيها ريح طيبة فوجدوا برد الريح وطيبها وظل السحابة فتنادوا : « عليكم بها » فخرجوا إلى البرية فلما اجتمعوا تحتها ألهبها الله عليهم نارا ورجفت بهم الأرض فاحترقوا كما يحترق الجراد المقلي وصاروا رمادا وهو عذاب يوم الظلّة (1) . ( 1) مجمع البيان : ج 4 ص 309. الَّذِينَ كَذَّبُوا شُعَيْباً كَأَنْ لَمْ يَغْنَوْا فِيهَا الَّذِينَ كَذَّبُوا شُعَيْباً كانُوا هُمُ الْخاسِرِينَ (92) فَتَوَلَّى عَنْهُمْ وَقالَ يا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسالاتِ رَبِّي وَنَصَحْتُ لَكُمْ فَكَيْفَ آسى عَلى قَوْمٍ كافِرِينَ (93) ثم روي عن أبي عبد الله عليه‌السلام : « أنه بعث الله عليهم صيحة واحدة فماتوا » (1) .` },
            { text: "ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَأَن لَّمْ يَغْنَوْا۟ فِيهَا ٱلَّذِينَ كَذَّبُوا۟ شُعَيْبًا كَانُوا۟ هُمُ ٱلْخَٰسِرِينَ", tafsir: `ولم يؤمنوا به وبرسالته ( كَأَنْ لَمْ يَغْنَوْا فِيهَا ) « غنى بالمكان » يعني : « أقام فيه » أي : كأن المكذبين لم يقيموا في دارهم أصلا ، حيث ذهبت أخبارهم وآثارهم ( الَّذِينَ كَذَّبُوا شُعَيْباً ) عاد اللفظ تأكيدا ( كانُوا هُمُ الْخاسِرِينَ ) فقد خسروا دينهم ودنياهم وآخرتهم ، وهذا في قبال قولهم : ( لَئِنِ اتَّبَعْتُمْ شُعَيْباً إِنَّكُمْ إِذاً لَخاسِرُونَ ) .` },
            { text: "فَتَوَلَّىٰ عَنْهُمْ وَقَالَ يَٰقَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسَٰلَٰتِ رَبِّى وَنَصَحْتُ لَكُمْ فَكَيْفَ ءَاسَىٰ عَلَىٰ قَوْمٍ كَٰفِرِينَ", tafsir: `شعيب ، أي أعرض عنهم ، إما قبل الهلاك ـ وتأخير هذه الجملة لما تقدم في قصة قوم صالح ـ وإما حين الهلاك إذ أخذهم العذاب ( وَقالَ يا قَوْمِ لَقَدْ أَبْلَغْتُكُمْ رِسالاتِ رَبِّي ) وجمع « رسالات » باعتبار كل رسالة من مختلف الشؤون ( وَنَصَحْتُ لَكُمْ ) بأن تتبعوني حتى تكونوا في أمن وسلامة ( فَكَيْفَ آسى ) أي أحزن ( عَلى قَوْمٍ كافِرِينَ ) بعد أن قمت بواجب النصح والإرشاد. والمراد بالاستفهام « كيف » النفي ، أي : لا أحزن ، فإنهم استحقوا العقاب بإعراضهم واستكبارهم وتمرّدهم. ( 1) بحار الأنوار : ج 12 ص 383. وَما أَرْسَلْنا فِي قَرْيَةٍ مِنْ نَبِيٍّ إِلاَّ أَخَذْنا أَهْلَها بِالْبَأْساءِ وَالضَّرَّاءِ لَعَلَّهُمْ يَضَّرَّعُونَ (94) ثُمَّ بَدَّلْنا مَكانَ السَّيِّئَةِ الْحَسَنَةَ حَتَّى عَفَوْا وَقالُوا قَدْ مَسَّ آباءَنَا الضَّرَّاءُ [95] ثم ذكر سبحانه أنه هكذا جرت عادة الناس بالنسبة إلى الأنبياء ، وهكذا جرت سنة الله بالنسبة إلى المكذبين ، تسلية للنبي صلى‌الله‌عليه‌وآله‌وسلم ، وإيقاظا لمن أراد القيام بالأمر والنهي في سبيل الله تعالى ( وَما أَرْسَلْنا فِي قَرْيَةٍ ) المراد بها المدينة ( مِنْ نَبِيٍ ) لإرشادهم ، فلم يؤمنوا به ( إِلَّا أَخَذْنا أَهْلَها ) أي أهل تلك القرية ( بِالْبَأْساءِ وَالضَّرَّاءِ ) البأساء : الشدة ، والضراء : سائر أنواع الضرر ( لَعَلَّهُمْ يَضَّرَّعُونَ ) أي يتضرعون ، بأن يتنبهوا ويتوبوا عن شركهم وكفرهم ومعاصيهم.` },
            { text: "وَمَآ أَرْسَلْنَا فِى قَرْيَةٍ مِّن نَّبِىٍّ إِلَّآ أَخَذْنَآ أَهْلَهَا بِٱلْبَأْسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمْ يَضَّرَّعُونَ", tafsir: `` },
            { text: "ثُمَّ بَدَّلْنَا مَكَانَ ٱلسَّيِّئَةِ ٱلْحَسَنَةَ حَتَّىٰ عَفَوا۟ وَّقَالُوا۟ قَدْ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذْنَٰهُم بَغْتَةً وَهُمْ لَا يَشْعُرُونَ", tafsir: `بعد أخذهم بالبأساء والضراء ( بَدَّلْنا مَكانَ السَّيِّئَةِ الْحَسَنَةَ ) بأن رفعنا عنهم الشدة وجعلنا الرفاه والرخاء مكانها لعلهم يشكرون ، كما قال سبحانه : ( فَتَحْنا عَلَيْهِمْ أَبْوابَ كُلِّ شَيْءٍ ) (1) ، فإن الله سبحانه يوقظ العصاة أولا بالشدة ، فإن لم تنفع يوقظهم بالرفاه ، فإن لم ينفع عذّبهم ، حيث لم يفدهم لا الخوف ولا الإحسان ( حَتَّى عَفَوْا ) « العفو » هو : الإغضاء عن الذنب ، أي فعلوا الذنوب غاضّين عنها ، تاركين أنفسهم وشهواتها. ( وَ ) إذا قيل لهم : إن الشدة والرخاء للابتلاء والإيقاظ ، لم يصدقوا ، بل ( قالُوا ) : هذه عادة الدنيا دائما ف ( قَدْ مَسَّ آباءَنَا الضَّرَّاءُ ( 1) الأنعام : 45. وَالسَّرَّاءُ فَأَخَذْناهُمْ بَغْتَةً وَهُمْ لا يَشْعُرُونَ (95) وَلَوْ أَنَّ أَهْلَ الْقُرى آمَنُوا وَاتَّقَوْا لَفَتَحْنا عَلَيْهِمْ بَرَكاتٍ مِنَ السَّماءِ وَالْأَرْضِ وَالسَّرَّاءُ ) ما يضر من الشدائد ، وما يسر من الرفاه ، وليسا للابتلاء والإيقاظ فانسدت جميع أبواب الهداية في وجوههم ، ولم ينفعهم إرشاد الأنبياء ، ولا الضراء ولا السراء ( فَأَخَذْناهُمْ بَغْتَةً ) أي فجأة بدون إمهال ( وَهُمْ لا يَشْعُرُونَ ) بالعذاب إلّا حين يرونه ، وربما كان هناك احتمال إقلاع ، وهنا يأتي العذاب تدريجيا ، كما حصل لقوم يونس عليه‌السلام ، أو إبلاغا للحجة إلى أقصاها ، كما صنع بقوم صالح عليه‌السلام . ثم إن المؤمن والكافر كلاهما يبتليان بالضراء والسراء ، لكن هناك فرق ؛ فضراء المؤمن مع صبر وارتياح ، وضراء الكافر مع جزع وكمد ، وسراء المؤمن مع بركة وأمن واطمئنان ، وسراء الكافر مع محق وقلق واضطراب.` },
            { text: "وَلَوْ أَنَّ أَهْلَ ٱلْقُرَىٰٓ ءَامَنُوا۟ وَٱتَّقَوْا۟ لَفَتَحْنَا عَلَيْهِم بَرَكَٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ وَلَٰكِن كَذَّبُوا۟ فَأَخَذْنَٰهُم بِمَا كَانُوا۟ يَكْسِبُونَ", tafsir: `بالله تعالى وبأنبيائه ( وَاتَّقَوْا ) معاصيه وعملوا الصالحات ( لَفَتَحْنا عَلَيْهِمْ بَرَكاتٍ مِنَ السَّماءِ وَالْأَرْضِ ) « البركات » الخيرات النامية ، وفتح الخير من السماء بكثرة الأمطار ، وطيب الهواء ، وفتحه من الأرض بإخراج النبات والثمار ، وتفجّر العيون ، إلى غيرهما من الخيرات المادية والمعنوية كاستجابة الدعاء ونحوها ، وهذا إلى جنب كونه معنويا بلطفه سبحانه ، كذلك يكون بالأسباب الظاهرة ، فإن الإيمان والتقوى يوجبان سيادة مناهج الله تعالى وهي توجب الأخوة والتعاون مما يسببان ازدهار الحياة وتعميم وَلكِنْ كَذَّبُوا فَأَخَذْناهُمْ بِما كانُوا يَكْسِبُونَ (96) أَ فَأَمِنَ أَهْلُ الْقُرى أَنْ يَأْتِيَهُمْ بَأْسُنا بَياتاً وَهُمْ نائِمُونَ (97) أَ وَأَمِنَ أَهْلُ الْقُرى أَنْ يَأْتِيَهُمْ بَأْسُنا ضُحًى وَهُمْ يَلْعَبُونَ (98) أَ فَأَمِنُوا مَكْرَ اللهِ فَلا يَأْمَنُ مَكْرَ اللهِ إِلاَّ الْقَوْمُ الْخاسِرُونَ (99) الرفاه والأمن ، كما أن الكفر والعصيان سببان لعكس ذلك ( وَلكِنْ كَذَّبُوا ) الرسل ولم يؤمنوا ( فَأَخَذْناهُمْ بِما كانُوا يَكْسِبُونَ ) أي بسبب كسبهم المعاصي والآثام. [98] ثم ذكر سبحانه أن أهل المعاصي لا بد لهم أن يترقبوا العقاب والنكال ( أَ فَأَمِنَ ) أي هل يأمن ( أَهْلُ الْقُرى ) المكذبون للرسل العاصون لله سبحانه ( أَنْ يَأْتِيَهُمْ بَأْسُنا ) أي عذابنا ( بَياتاً ) أي ليلا ( وَهُمْ نائِمُونَ ) في أمن وراحة واطمئنان ؟ والمعنى : أنهم يجب أن لا يأمنوا ذلك.` },
            { text: "أَفَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا بَيَٰتًا وَهُمْ نَآئِمُونَ", tafsir: `` },
            { text: "أَوَأَمِنَ أَهْلُ ٱلْقُرَىٰٓ أَن يَأْتِيَهُم بَأْسُنَا ضُحًى وَهُمْ يَلْعَبُونَ", tafsir: `الهمزة للاستفهام ، والواو للعطف ، أي وهل يأمن أهل البلاد ( أَنْ يَأْتِيَهُمْ بَأْسُنا ) نكالنا وعقابنا ( ضُحًى ) نهارا عند ارتفاع الشمس ( وَهُمْ يَلْعَبُونَ ) في أمن واطمئنان ، أنهم إن عصوا فلن يكونوا آمنين في أحسن أوقات أمنهم ليلا ولا نهارا.` },
            { text: "أَفَأَمِنُوا۟ مَكْرَ ٱللَّهِ فَلَا يَأْمَنُ مَكْرَ ٱللَّهِ إِلَّا ٱلْقَوْمُ ٱلْخَٰسِرُونَ", tafsir: `المكر : العلاج الخفي ، وإن غلب استعماله عرفا في معالجة الأشياء بالباطل ، أي يجب أن لا يأمن أحد من مكر الله ، وتسبيبه الأسباب للنكال به ( فَلا يَأْمَنُ مَكْرَ اللهِ إِلَّا الْقَوْمُ الْخاسِرُونَ ) الذين خسروا أنفسهم ، ولا ينكرون من أمرهم ، وإلا فالمؤمنين يخافون أَ وَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ الْأَرْضَ مِنْ بَعْدِ أَهْلِها أَنْ لَوْ نَشاءُ أَصَبْناهُمْ بِذُنُوبِهِمْ وَنَطْبَعُ عَلى قُلُوبِهِمْ فَهُمْ لا يَسْمَعُونَ (100) تِلْكَ الْقُرى نَقُصُّ عَلَيْكَ مِنْ أَنْبائِها وَلَقَدْ جاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّناتِ سوء العاقبة الموجب للنكال والعقاب ، والمعصومون خارجون عن العموم لأن مصب الكلام حول العصاة ـ فإنه عبارة أخرى عن وجوب حذر العصاة ـ أو داخلون باعتبار احتمال صدور ترك الأولى منهم ، الموجب لعدم بلوغ بعض الدرجات الرفيعة ، كما قال سبحانه : ( وَلَقَدْ عَهِدْنا إِلى آدَمَ مِنْ قَبْلُ فَنَسِيَ وَلَمْ نَجِدْ لَهُ عَزْماً ) (1) .` },
            { text: "أَوَلَمْ يَهْدِ لِلَّذِينَ يَرِثُونَ ٱلْأَرْضَ مِنۢ بَعْدِ أَهْلِهَآ أَن لَّوْ نَشَآءُ أَصَبْنَٰهُم بِذُنُوبِهِمْ وَنَطْبَعُ عَلَىٰ قُلُوبِهِمْ فَهُمْ لَا يَسْمَعُونَ", tafsir: `أي : ألم ينبّه ويرشد ( لِلَّذِينَ يَرِثُونَ الْأَرْضَ مِنْ بَعْدِ أَهْلِها ) أي الذين صاروا خلفاء لآبائهم وأجدادهم ، من بعد ما أفنينا أولئك ، وأبحنا الأرض لهؤلاء ، أي أليس يعرف الناس مما رأوه من عذاب الأمم السابقة ـ حينما عصوا ـ ( أَنْ لَوْ نَشاءُ أَصَبْناهُمْ ) وأخذناهم ( بِذُنُوبِهِمْ ) كما أهلكنا الأمم السابقة ( وَنَطْبَعُ عَلى قُلُوبِهِمْ ) بأن نعلمها بعلامة الكفر ، أو نغفلها حتى لا تعقل شيئا ، وذلك بسبب اقترافهم الجرائم والآثام ـ كما سبق ـ ( فَهُمْ لا يَسْمَعُونَ ) الوعظ ولا يقبلونه.` },
            { text: "تِلْكَ ٱلْقُرَىٰ نَقُصُّ عَلَيْكَ مِنْ أَنۢبَآئِهَا وَلَقَدْ جَآءَتْهُمْ رُسُلُهُم بِٱلْبَيِّنَٰتِ فَمَا كَانُوا۟ لِيُؤْمِنُوا۟ بِمَا كَذَّبُوا۟ مِن قَبْلُ كَذَٰلِكَ يَطْبَعُ ٱللَّهُ عَلَىٰ قُلُوبِ ٱلْكَٰفِرِينَ", tafsir: `التي هلكت واضمحلت ( نَقُصُّ عَلَيْكَ ) يا رسول الله ( مِنْ أَنْبائِها ) أي أخبارها لتنظر فيها بنظر الاعتبار ، وتخبر بها المسلمين وغير المسلمين حتى يعتبروا ( وَلَقَدْ جاءَتْهُمْ رُسُلُهُمْ بِالْبَيِّناتِ ) أي الأدلة ( 1) طه : 116. فَما كانُوا لِيُؤْمِنُوا بِما كَذَّبُوا مِنْ قَبْلُ كَذلِكَ يَطْبَعُ اللهُ عَلى قُلُوبِ الْكافِرِينَ (101) وَما وَجَدْنا لِأَكْثَرِهِمْ مِنْ عَهْدٍ وَإِنْ وَجَدْنا أَكْثَرَهُمْ لَفاسِقِينَ (102) ثُمَّ بَعَثْنا مِنْ بَعْدِهِمْ الواضحة الدالة على المرسل والرسول فأهلكناهم لأنهم تمادوا في غيهم ولم يكن احتمال إقلاعهم عن كفرهم وعصيانهم إذ ما ( كانُوا لِيُؤْمِنُوا بِما كَذَّبُوا مِنْ قَبْلُ ) إنهم كانوا كذلك حسب علمنا بكامن قلوبهم ( كَذلِكَ ) أي كما طبع على قلوب هؤلاء ، بمعنى أنها لم تكن قابلة للهداية بسوء صنيعها ، كمن صارت المعصية ملكة له فلا يقدر عادة على تركها كذلك ( يَطْبَعُ اللهُ عَلى قُلُوبِ الْكافِرِينَ ) وقد مرّ مرارا معنى « الطبع » وأنه بسوء اختيار الشخص ، لا أنه ظلم من الله ـ تعالى عن ذلك ـ بالنسبة إلى الكافر.` },
            { text: "وَمَا وَجَدْنَا لِأَكْثَرِهِم مِّنْ عَهْدٍ وَإِن وَجَدْنَآ أَكْثَرَهُمْ لَفَٰسِقِينَ", tafsir: `أي أكثر الذين أهلكوا ( مِنْ عَهْدٍ ) أي كانوا ينقضون العهود والمواثيق ، يقال : « لا عهد لفلان » ، أي لا يفي بعهده ، والمراد ب « العهد » ، إما ما أودع في فطرة كل أحد من الإيمان ، وإما ما كان مأخوذا من الناس على لسان الأنبياء ، وتصح نسبة عدم العهد إلى الأبناء ، بملاحظة التعهد مع الآباء ، ولذا من عاهد قبيلة أن لا يحاربها خمسين سنة ، كان الأبناء ملزمين بما التزم به آباؤهم ( وَإِنْ وَجَدْنا ) أي قد وجدنا ( أَكْثَرَهُمْ لَفاسِقِينَ ) خارجين من الوفاء بالعهد ، فإن الفسق بمعنى الخروج عن الطاعة.` },
            { text: "ثُمَّ بَعَثْنَا مِنۢ بَعْدِهِم مُّوسَىٰ بِـَٔايَٰتِنَآ إِلَىٰ فِرْعَوْنَ وَمَلَإِي۟هِۦ فَظَلَمُوا۟ بِهَا فَٱنظُرْ كَيْفَ كَانَ عَٰقِبَةُ ٱلْمُفْسِدِينَ", tafsir: `أي بعد الرسل الذين تقدمت أسماؤهم ، أو مُوسى بِآياتِنا إِلى فِرْعَوْنَ وَمَلائِهِ فَظَلَمُوا بِها فَانْظُرْ كَيْفَ كانَ عاقِبَةُ الْمُفْسِدِينَ (103) وَقالَ مُوسى يا فِرْعَوْنُ إِنِّي رَسُولٌ مِنْ رَبِّ الْعالَمِينَ (104) حَقِيقٌ عَلى أَنْ لا أَقُولَ عَلَى اللهِ إِلاَّ الْحَقَّ قَدْ جِئْتُكُمْ بِبَيِّنَةٍ بعد هلاك الأمم السالفة ( مُوسى ) عليه‌السلام ( بِآياتِنا ) أي مع دلائلنا وحججنا ( إِلى فِرْعَوْنَ وَمَلَائِهِ ) أي قومه ، أو الأشراف منهم ، وإنما خصّوا لأنه عليه‌السلام قصدهم أولا وبالذات ( فَظَلَمُوا ) أي ظلم فرعون وملأه أنفسهم ( بِها ) أي بسبب تلك الآيات ، فإن نزولها صار سببا لظلم أنفسهم ، ولو لا أنها نزلت لم يظلموا ، لأنه لم تكن حينئذ شريعة أصلا ، وهذا مجاز في النسبة كقوله سبحانه : ( وَلا يَزِيدُ الظَّالِمِينَ إِلَّا خَساراً ) (1) ، ( فَانْظُرْ كَيْفَ كانَ عاقِبَةُ الْمُفْسِدِينَ ) أي انظر يا رسول الله ، أو كل من يأتي منه النظر ، والمراد ب « النظر » التدبر والتفكر ، فيما آل إليه أمر المفسدين ، من الهلاك والغرق.` },
            { text: "وَقَالَ مُوسَىٰ يَٰفِرْعَوْنُ إِنِّى رَسُولٌ مِّن رَّبِّ ٱلْعَٰلَمِينَ", tafsir: `أي إني رسول إليك ، من الله تعالى ، وقد كان فرعون يقول أنه الإله ، كما قال سبحانه : ( فَحَشَرَ فَنادى * فَقالَ أَنَا رَبُّكُمُ الْأَعْلى ) (2) .` },
            { text: "حَقِيقٌ عَلَىٰٓ أَن لَّآ أَقُولَ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ قَدْ جِئْتُكُم بِبَيِّنَةٍ مِّن رَّبِّكُمْ فَأَرْسِلْ مَعِىَ بَنِىٓ إِسْرَٰٓءِيلَ", tafsir: `أي واجب عليّ أن أقول الحق ، ولا أنسب إلى الله إلّا الصدق ، فإن الجدير بالنبي أن يقول ما قاله سبحانه ، لا أن ينسب إليه تعالى الباطل والكذب ( قَدْ جِئْتُكُمْ بِبَيِّنَةٍ ( 1) الإسراء : 83. ( 2) النازعات : 24 و 25. مِنْ رَبِّكُمْ فَأَرْسِلْ مَعِيَ بَنِي إِسْرائِيلَ (105) قالَ إِنْ كُنْتَ جِئْتَ بِآيَةٍ فَأْتِ بِها إِنْ كُنْتَ مِنَ الصَّادِقِينَ (106) فَأَلْقى عَصاهُ فَإِذا هِيَ ثُعْبانٌ مُبِينٌ (107) وَنَزَعَ يَدَهُ فَإِذا هِيَ بَيْضاءُ لِلنَّاظِرِينَ (108) مِنْ رَبِّكُمْ ) أي بحجة دالة على صدق كلامي ، والمراد بها الجنس لا حجة واحدة ( فَأَرْسِلْ ) يا فرعون ( مَعِيَ بَنِي إِسْرائِيلَ ) فإن فرعون كان قد سخّر بني إسرائيل للأعمال كالبناء ونحوه. والمراد بإرسالهم : التخلية بين بني إسرائيل وبين موسى عليه‌السلام ليوجّههم حسب الشريعة. وفي بعض التفاسير أنه عليه‌السلام أرادهم ليذهب بهم إلى الأرض المقدسة موطن آبائهم وأجدادهم.` },
            { text: "قَالَ إِن كُنتَ جِئْتَ بِـَٔايَةٍ فَأْتِ بِهَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ", tafsir: `فرعون : ( إِنْ كُنْتَ ) يا موسى ( جِئْتَ بِآيَةٍ ) أي حجة تدل على صدق نبوتك ( فَأْتِ بِها إِنْ كُنْتَ مِنَ الصَّادِقِينَ ) في أنك رسول رب العالمين.` },
            { text: "فَأَلْقَىٰ عَصَاهُ فَإِذَا هِىَ ثُعْبَانٌ مُّبِينٌ", tafsir: `موسى عليه‌السلام ( عَصاهُ ) التي كانت بيده ، وكانت من الجنة ( فَإِذا هِيَ ) تنقلب إلى ( ثُعْبانٌ مُبِينٌ ) أي حية كبيرة عظيمة فتحت فاها لتلتقم قصر فرعون الذي كان طوله ثمانين ذراعا. وهنا خاف فرعون والحاشية ، وهربوا ، وأحدث فرعون من الخوف ، والتمس موسى أن يردّها ، فردّها وإذا بها ترجع عصا كالسابق.` },
            { text: "وَنَزَعَ يَدَهُۥ فَإِذَا هِىَ بَيْضَآءُ لِلنَّٰظِرِينَ", tafsir: `موسى عليه‌السلام ( يَدَهُ ) أي جعلها تحت إبطه ، ثم أخرجها ( فَإِذا هِيَ بَيْضاءُ لِلنَّاظِرِينَ ) أي صارت اليد أكثر ضياء من الشمس ، ثم أعادها إلى إبطه وأخرجها فإذا بها كحالتها السابقة. قالَ الْمَلَأُ مِنْ قَوْمِ فِرْعَوْنَ إِنَّ هذا لَساحِرٌ عَلِيمٌ (109) يُرِيدُ أَنْ يُخْرِجَكُمْ مِنْ أَرْضِكُمْ فَما ذا تَأْمُرُونَ (110) قالُوا أَرْجِهْ وَأَخاهُ وَأَرْسِلْ فِي الْمَدائِنِ حاشِرِينَ (111) يَأْتُوكَ بِكُلِّ ساحِرٍ عَلِيمٍ (112) وَجاءَ السَّحَرَةُ فِرْعَوْنَ قالُوا إِنَّ لَنا لَأَجْراً [110] ولما رأوا هاتين المعجزتين العظيمتين تحيروا ، وهنا تدخلت الحاشية في الأمر ليخفّفوا من روع فرعون ( قالَ الْمَلَأُ ) أي جماعة الأشراف ( مِنْ قَوْمِ فِرْعَوْنَ إِنَّ هذا ) أي موسى عليه‌السلام ( لَساحِرٌ عَلِيمٌ ) بالسحر ، وأنه صنع ما صنع سحرا لا معجزة.` },
            { text: "قَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٌ", tafsir: `` },
            { text: "يُرِيدُ أَن يُخْرِجَكُم مِّنْ أَرْضِكُمْ فَمَاذَا تَأْمُرُونَ", tafsir: `أي موسى عليه‌السلام ( أَنْ يُخْرِجَكُمْ مِنْ أَرْضِكُمْ ) باستمالة قلوب بني إسرائيل وسائر الناس إلى نفسه حتى يغلب عليكم. ومن الواضح أن شخصا إذا غلب يهرب أعضاء الحكومة السابقة خوفا منه ( فَما ذا تَأْمُرُونَ ) أن نصنع لاتقاء خطر موسى عليه‌السلام ؟` },
            { text: "قَالُوٓا۟ أَرْجِهْ وَأَخَاهُ وَأَرْسِلْ فِى ٱلْمَدَآئِنِ حَٰشِرِينَ", tafsir: `أي قال الملأ في جواب فرعون الذي سأل « ماذا تأمرون » : ( أَرْجِهْ ) أمر من « أرجأ » بمعنى « أخّر » ، أي أخّره واضرب معه موعدا ، ولا تعجل في الحكم له أو عليه ( وَأَخاهُ ) أي وأخّر أخاه هارون معه ( وَأَرْسِلْ فِي الْمَدائِنِ ) التي حولك ، جمع « مدينة » أي ابعث إلى البلدان الأخرى ( حاشِرِينَ ) أي أناسا جامعين للسحرة ليأتوا ويقابلوه بمثل سحره.` },
            { text: "يَأْتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٍ", tafsir: `أولئك المبعوثون ( بِكُلِّ ساحِرٍ عَلِيمٍ ) فاستحسن فرعون رأيهم وأرسل في طلب السحرة.` },
            { text: "وَجَآءَ ٱلسَّحَرَةُ فِرْعَوْنَ قَالُوٓا۟ إِنَّ لَنَا لَأَجْرًا إِن كُنَّا نَحْنُ ٱلْغَٰلِبِينَ", tafsir: `وفي عددهم خلاف : من سبعين ، إلى ثمانين ألف ( فِرْعَوْنَ ) أي جاءوا إليه ( قالُوا إِنَّ لَنا لَأَجْراً ) أي عوضا على عملنا إِنْ كُنَّا نَحْنُ الْغالِبِينَ (113) قالَ نَعَمْ وَإِنَّكُمْ لَمِنَ الْمُقَرَّبِينَ (114) قالُوا يا مُوسى إِمَّا أَنْ تُلْقِيَ وَإِمَّا أَنْ نَكُونَ نَحْنُ الْمُلْقِينَ (115) قالَ أَلْقُوا فَلَمَّا أَلْقَوْا سَحَرُوا أَعْيُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجاؤُ بِسِحْرٍ عَظِيمٍ (116) وَأَوْحَيْنا إِلى مُوسى أَنْ أَلْقِ عَصاكَ ( إِنْ كُنَّا نَحْنُ الْغالِبِينَ ) على موسى.` },
            { text: "قَالَ نَعَمْ وَإِنَّكُمْ لَمِنَ ٱلْمُقَرَّبِينَ", tafsir: `فرعون : ( نَعَمْ ) لكم الأجر إن غلبتموه ( وَإِنَّكُمْ لَمِنَ الْمُقَرَّبِينَ ) إليّ ، فأكرمكم وأجعلكم في عداد المقربين إلي.` },
            { text: "قَالُوا۟ يَٰمُوسَىٰٓ إِمَّآ أَن تُلْقِىَ وَإِمَّآ أَن نَّكُونَ نَحْنُ ٱلْمُلْقِينَ", tafsir: `أي قال السحرة : ( يا مُوسى إِمَّا أَنْ تُلْقِيَ ) عصاك أنت أولا ( وَإِمَّا أَنْ نَكُونَ نَحْنُ الْمُلْقِينَ ) لما معنا من السحر ؟` },
            { text: "قَالَ أَلْقُوا۟ فَلَمَّآ أَلْقَوْا۟ سَحَرُوٓا۟ أَعْيُنَ ٱلنَّاسِ وَٱسْتَرْهَبُوهُمْ وَجَآءُو بِسِحْرٍ عَظِيمٍ", tafsir: `لهم موسى عليه‌السلام : ( أَلْقُوا ) ما معكم أولا ( فَلَمَّا أَلْقَوْا ) حبالهم وعصيّهم التي كانت آلة سحرهم ( سَحَرُوا أَعْيُنَ النَّاسِ ) فقد احتالوا في تحريك العصي والحبال بما جعلوا فيها من الزئبق حتى تتحرك بحرارة الشمس ، وغير ذلك من أنواع التمويه ، وخيّل إلى الناس أنها تتحرك ، وقد ظن الناس أنها حيات تتحرك ، وما شعروا أنها حبال تحرّكها حرارة الشمس بما فيها من الزئبق ( وَاسْتَرْهَبُوهُمْ ) أي أرهبوهم ، فإن الناس خافوا من حيّاتهم ( وَجاؤُ بِسِحْرٍ عَظِيمٍ ) فإن الحبال الكثيرة المختلفة الألوان والكيفية إذا صارت كلها حيات ـ في أعين الناس ـ تركب بعضها على بعض يكون عظيما لدى الناظر.` },
            { text: "وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ أَنْ أَلْقِ عَصَاكَ فَإِذَا هِىَ تَلْقَفُ مَا يَأْفِكُونَ", tafsir: `عليه‌السلام حين ذاك ( أَنْ أَلْقِ عَصاكَ ) التي هي فَإِذا هِيَ تَلْقَفُ ما يَأْفِكُونَ (117) فَوَقَعَ الْحَقُّ وَبَطَلَ ما كانُوا يَعْمَلُونَ (118) فَغُلِبُوا هُنالِكَ وَانْقَلَبُوا صاغِرِينَ (119) وَأُلْقِيَ السَّحَرَةُ ساجِدِينَ (120) قالُوا آمَنَّا بِرَبِّ الْعالَمِينَ (121) معك ، فألقاها فصارت ثعبانا مدهشا ( فَإِذا هِيَ تَلْقَفُ ) أي تلقم وتأكل ( ما يَأْفِكُونَ ) أي إفكهم ، والمراد به حيّاتهم وعصيّهم ، فإن العصا أخذت تأكل الحبال ثم توجهت إلى الناس ، فأخذوا في الهرب ، وقتل تحت الأيدي والأرجل جمع كثير ، ثم أخذها موسى عليه‌السلام فإذا بها عصا ، وهناك قال السحرة : لو كان هذا سحرا لم تأكل حبالنا ، فلا بد وأن يكون إعجازا من رب السماء.` },
            { text: "فَوَقَعَ ٱلْحَقُّ وَبَطَلَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `أي ظهر ( الْحَقُ ) وهو أمر موسى عليه‌السلام ونبوته ( وَبَطَلَ ما كانُوا يَعْمَلُونَ ) من التمويهات ، أي ظهر بطلانها.` },
            { text: "فَغُلِبُوا۟ هُنَالِكَ وَٱنقَلَبُوا۟ صَٰغِرِينَ", tafsir: `أي غلب موسى عليه‌السلام فرعون وملأه ، وبهت أولئك ( هُنالِكَ ) أي من ذلك المكان ( وَانْقَلَبُوا ) أي انصرف فرعون وملأه ( صاغِرِينَ ) أذلّاء مقهورين.` },
            { text: "وَأُلْقِىَ ٱلسَّحَرَةُ سَٰجِدِينَ", tafsir: `فإن السحرة لما شاهدوا تلك الآيات ، وعلموا أن موسى عليه‌السلام نبي من عند الله تعالى ، لم يتمالكوا أنفسهم إلّا وسجدوا إذعانا لله سبحانه ، والتعبير ب « ألقي » مبني للمجهول ، لأجل إفادة معنى عدم تمالك النفس ، وأن ما رأوا من الآيات هي التي سببت أن يسجدوا.` },
            { text: "قَالُوٓا۟ ءَامَنَّا بِرَبِّ ٱلْعَٰلَمِينَ", tafsir: `أي قال السحرة : ( آمَنَّا بِرَبِّ الْعالَمِينَ ) صدّقناه واعترفنا بوجوده ، وكفرنا بألوهية فرعون. رَبِّ مُوسى وَهارُونَ (122) قالَ فِرْعَوْنُ آمَنْتُمْ بِهِ قَبْلَ أَنْ آذَنَ لَكُمْ إِنَّ هذا لَمَكْرٌ مَكَرْتُمُوهُ فِي الْمَدِينَةِ لِتُخْرِجُوا مِنْها أَهْلَها فَسَوْفَ تَعْلَمُونَ (123) لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُمْ مِنْ خِلافٍ ثُمَّ لَأُصَلِّبَنَّكُمْ` },
            { text: "رَبِّ مُوسَىٰ وَهَٰرُونَ", tafsir: `وإنما خصّوهما بالذكر ، بعد قولهم « رب العالمين » لأنهما دعيا إلى الإيمان بالله.` },
            { text: "قَالَ فِرْعَوْنُ ءَامَنتُم بِهِۦ قَبْلَ أَنْ ءَاذَنَ لَكُمْ إِنَّ هَٰذَا لَمَكْرٌ مَّكَرْتُمُوهُ فِى ٱلْمَدِينَةِ لِتُخْرِجُوا۟ مِنْهَآ أَهْلَهَا فَسَوْفَ تَعْلَمُونَ", tafsir: `حين رأى إيمان السحرة : ( آمَنْتُمْ بِهِ ) أي بموسى عليه‌السلام والاستفهام للتوبيخ والإنكار ( قَبْلَ أَنْ آذَنَ لَكُمْ ) أي قبل أن تحصلوا على إذني ، فإنه كان يرى نفسه المستحق لأن يأذن بالإيمان ، وأن الإيمان بدون إذنه موجب للعقوبة ( إِنَّ هذا ) أي هذا الإيمان بهذه الكيفية ( لَمَكْرٌ مَكَرْتُمُوهُ فِي الْمَدِينَةِ ) فإنه أراد أن يلبس على الناس أن إيمان السحرة ليس على علم واعتقاد ، وإنما عن تواطؤ من موسى والسحرة ( لِتُخْرِجُوا مِنْها أَهْلَها ) أي صنعتم هذا المكر لأن تسودوا أنتم في البلاد ، وتخرجوا من المدينة أهلها ، والمراد بهم فرعون وملأه ، فإنه إذا جاءت سلطة جديدة ، تجبر أهل السلطة القديمة بالفرار وقاية لأنفسهم من السجن والقتل ( فَسَوْفَ تَعْلَمُونَ ) أيها السحرة عاقبة أمركم وجزاء عملكم.` },
            { text: "لَأُقَطِّعَنَّ أَيْدِيَكُمْ وَأَرْجُلَكُم مِّنْ خِلَٰفٍ ثُمَّ لَأُصَلِّبَنَّكُمْ أَجْمَعِينَ", tafsir: `بكل تأكيد ( أَيْدِيَكُمْ وَأَرْجُلَكُمْ ) أيها السحرة ( مِنْ خِلافٍ ) أي من كل شق طرفا ، كاليد اليمنى والرجل اليسرى ، أو بالعكس. وكانوا يعملون ذلك لبقاء التوازن في الجملة للجسد ، إذ لو كان القطع من طرف واحد ، لم يكن لذلك الطرف رجل يمشي بها ، ولا يد يتكئ بها على العصا ( ثُمَ ) بعد القطع ( لَأُصَلِّبَنَّكُمْ ) أَجْمَعِينَ (124) قالُوا إِنَّا إِلى رَبِّنا مُنْقَلِبُونَ (125) وَما تَنْقِمُ مِنَّا إِلاَّ أَنْ آمَنَّا بِآياتِ رَبِّنا لَمَّا جاءَتْنا رَبَّنا أَفْرِغْ عَلَيْنا صَبْراً وَتَوَفَّنا مُسْلِمِينَ (126) وَقالَ الْمَلَأُ مِنْ قَوْمِ فِرْعَوْنَ أَ تَذَرُ مُوسى وَقَوْمَهُ لِيُفْسِدُوا فِي الْأَرْضِ وَيَذَرَكَ و « الصلب » هو الشد على الخشبة حتى يموت ، وقد كان يطول بقاء المصلوب يوما وأكثر ( أَجْمَعِينَ ) فلا أدع منكم أحدا.` },
            { text: "قَالُوٓا۟ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ", tafsir: `أي قال السحرة : ( إِنَّا إِلى رَبِّنا مُنْقَلِبُونَ ) « الانقلاب » هو الرجوع ، والمعنى : إنك إن صلبتنا فإنا إلى جزاء الله وثوابه نرجع ، فلا يضرنا شيء. وغرضهم بيان صبرهم على ما ينزل بهم من الشدة ، وأنهم مصممون على استمرارهم في الإيمان.` },
            { text: "وَمَا تَنقِمُ مِنَّآ إِلَّآ أَنْ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتْنَا رَبَّنَآ أَفْرِغْ عَلَيْنَا صَبْرًا وَتَوَفَّنَا مُسْلِمِينَ", tafsir: `« النقمة » الإنكار ، أي : ما تكره ( مِنَّا ) وما تطعن فينا ( إِلَّا أَنْ آمَنَّا بِآياتِ رَبِّنا ) أي دلائله وحججه ( لَمَّا جاءَتْنا ) فليس لنا ذنب سوى ذلك ( رَبَّنا أَفْرِغْ عَلَيْنا صَبْراً ) أي اصبب علينا الصبر عند ما يفعل بنا من القطع والصلب ( وَتَوَفَّنا مُسْلِمِينَ ) أي وفّقنا للثبات على الإسلام إلى وقت الوفاة حتى نموت على الإيمان والإسلام. وفي أن فرعون صلب هؤلاء أم لا ، خلاف بين المفسرين.` },
            { text: "وَقَالَ ٱلْمَلَأُ مِن قَوْمِ فِرْعَوْنَ أَتَذَرُ مُوسَىٰ وَقَوْمَهُۥ لِيُفْسِدُوا۟ فِى ٱلْأَرْضِ وَيَذَرَكَ وَءَالِهَتَكَ قَالَ سَنُقَتِّلُ أَبْنَآءَهُمْ وَنَسْتَحْىِۦ نِسَآءَهُمْ وَإِنَّا فَوْقَهُمْ قَٰهِرُونَ", tafsir: `أي جماعة الأشراف ( مِنْ قَوْمِ فِرْعَوْنَ ) بعد أن رأوا غلبة موسى عليه‌السلام وإيمان جمع به ( أَ تَذَرُ ) أي هل تبقي يا فرعون ( مُوسى وَقَوْمَهُ ) وهم بنو إسرائيل ( لِيُفْسِدُوا فِي الْأَرْضِ ) بإظهار التوحيد ، وأنك لست بإله ( وَيَذَرَكَ ) أي يتركك موسى ، فلا يعتني وَآلِهَتَكَ قالَ سَنُقَتِّلُ أَبْناءَهُمْ وَنَسْتَحْيِي نِساءَهُمْ وَإِنَّا فَوْقَهُمْ قاهِرُونَ (127) قالَ مُوسى لِقَوْمِهِ اسْتَعِينُوا بِاللهِ وَاصْبِرُوا إِنَّ الْأَرْضَ لِلَّهِ يُورِثُها مَنْ يَشاءُ مِنْ عِبادِهِ وَالْعاقِبَةُ لِلْمُتَّقِينَ (128) بك ( وَ ) يذر ( آلِهَتَكَ ) جمع « إله » ، فقد كان يدّعي الربوبية ، وجعل لهم آلهة أيضا ، فكانوا يعبدون البقر والأصنام. وقد كان الاستفهام منهم تحريضا لفرعون ، حتى يقضي على موسى عليه‌السلام ( قالَ ) فرعون في جوابهم : ( سَنُقَتِّلُ أَبْناءَهُمْ ) أي سوف نكثر في أبناء قوم موسى القتل حتى لا يبقى منهم أحد يصلح للقتال والإفساد ( وَنَسْتَحْيِي نِساءَهُمْ ) أي نستبقيهن أحياء للخدمة والاستمتاع إذلالا لهم ، وإماتة لكلماتهم ( وَإِنَّا فَوْقَهُمْ قاهِرُونَ ) بيدنا القوة والجند والسلاح والملك فلا يتمكنون من مقاومتنا. [129] قد كان فرعون يفعل ذلك ببني إسرائيل ، لما علم أن زوال ملكه بيد أحدهم ، ولما ظهر موسى عليه‌السلام كفّ عن ذلك خوفا ، وبعد ما حثه قومه على الانتقام ، عزم على العودة إلى ما كان يفعله سابقا ، ولما علم بذلك بنو إسرائيل شكوا إلى موسى عليه‌السلام ف ( قالَ مُوسى ) عليه‌السلام ( لِقَوْمِهِ اسْتَعِينُوا بِاللهِ ) في دفع بلاء فرعون عن أنفسكم ( وَاصْبِرُوا ) على أذى فرعون أياما قليلة ، فلا ترجعوا عن دينكم ، ولا تظهروا الجزع ( إِنَّ الْأَرْضَ لِلَّهِ ) تعالى ( يُورِثُها مَنْ يَشاءُ مِنْ عِبادِهِ ) أي ينقلها بإماتة السابقين أو إقصائهم ، ويجعلها في أيدي الآخرين ، كما أن الإرث كذلك في الجملة ( وَالْعاقِبَةُ ) الحسنة ( لِلْمُتَّقِينَ ) الذين يتقون الله تعالى ، فإنهم يجلبون بذلك خير الدنيا وسعادة الآخرة ، مع رضا الله سبحانه عنهم. قالُوا أُوذِينا مِنْ قَبْلِ أَنْ تَأْتِيَنا وَمِنْ بَعْدِ ما جِئْتَنا قالَ عَسى رَبُّكُمْ أَنْ يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِي الْأَرْضِ فَيَنْظُرَ كَيْفَ تَعْمَلُونَ (129) وَلَقَدْ أَخَذْنا آلَ فِرْعَوْنَ بِالسِّنِينَ وَنَقْصٍ مِنَ الثَّمَراتِ لَعَلَّهُمْ يَذَّكَّرُونَ (130) فَإِذا جاءَتْهُمُ الْحَسَنَةُ` },
            { text: "قَالَ مُوسَىٰ لِقَوْمِهِ ٱسْتَعِينُوا۟ بِٱللَّهِ وَٱصْبِرُوٓا۟ إِنَّ ٱلْأَرْضَ لِلَّهِ يُورِثُهَا مَن يَشَآءُ مِنْ عِبَادِهِۦ وَٱلْعَٰقِبَةُ لِلْمُتَّقِينَ", tafsir: `` },
            { text: "قَالُوٓا۟ أُوذِينَا مِن قَبْلِ أَن تَأْتِيَنَا وَمِنۢ بَعْدِ مَا جِئْتَنَا قَالَ عَسَىٰ رَبُّكُمْ أَن يُهْلِكَ عَدُوَّكُمْ وَيَسْتَخْلِفَكُمْ فِى ٱلْأَرْضِ فَيَنظُرَ كَيْفَ تَعْمَلُونَ", tafsir: `أي قال بنو إسرائيل ، لما سمعوا جواب موسى بالصبر ، وأنه لا يريد دفع فرعون عاجلا : ( أُوذِينا ) أي عذّبنا من قبل فرعون ( مِنْ قَبْلِ أَنْ تَأْتِيَنا ) وتبعث فينا بالرسالة ( وَمِنْ بَعْدِ ما جِئْتَنا ) وبعثت إلينا رسولا ، فلم ننتفع بك في دفع الأذى ( قالَ ) موسى عليه‌السلام واعدا إياهم بالنجاة : ( عَسى رَبُّكُمْ ) أي لعل الله سبحانه ( أَنْ يُهْلِكَ عَدُوَّكُمْ ) فرعون وينقذكم منه ( وَيَسْتَخْلِفَكُمْ فِي الْأَرْضِ ) أي يجعلكم خلفاءه والقائمين مقامه في البلاد ( فَيَنْظُرَ كَيْفَ تَعْمَلُونَ ) بعد ما ملكتم الأرض ، هل تفسدون كما أفسد فرعون أم تصلحون ، فإن الله سبحانه يجازي البشر بعملهم لا بعلمه فيهم. [131] ثم بيّن سبحانه ما فعله بآل فرعون من النكال والعقاب جزاء بما كانوا يقترفونه من المعاصي والآثام ( وَلَقَدْ أَخَذْنا آلَ فِرْعَوْنَ بِالسِّنِينَ ) « السنين » الأعوام المقحطة ، يقال : « أخذتهم السنة » إذا كانت سنة مقحطة مجدبة ، أي عاقبناها بالجدب والقحط ( وَنَقْصٍ مِنَ الثَّمَراتِ ) فإن أشجارها كانت تحمل أثمارا قليلة ، وهذا غير جدب أراضيهم ( لَعَلَّهُمْ يَذَّكَّرُونَ ) أي لكي يذكروا عذاب الله فيرجعوا إلى الإيمان.` },
            { text: "وَلَقَدْ أَخَذْنَآ ءَالَ فِرْعَوْنَ بِٱلسِّنِينَ وَنَقْصٍ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمْ يَذَّكَّرُونَ", tafsir: `` },
            { text: "فَإِذَا جَآءَتْهُمُ ٱلْحَسَنَةُ قَالُوا۟ لَنَا هَٰذِهِۦ وَإِن تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا۟ بِمُوسَىٰ وَمَن مَّعَهُۥٓ أَلَآ إِنَّمَا طَٰٓئِرُهُمْ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَهُمْ لَا يَعْلَمُونَ", tafsir: `أي أصابهم الخير كالخصب والسعة والصحة قالُوا لَنا هذِهِ وَإِنْ تُصِبْهُمْ سَيِّئَةٌ يَطَّيَّرُوا بِمُوسى وَمَنْ مَعَهُ أَلا إِنَّما طائِرُهُمْ عِنْدَ اللهِ وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ (131) وَقالُوا مَهْما تَأْتِنا بِهِ مِنْ آيَةٍ لِتَسْحَرَنا بِها فَما نَحْنُ لَكَ بِمُؤْمِنِينَ (132) وما أشبه ( قالُوا لَنا هذِهِ ) أي إنا نستحق ذلك ، وهذا من حسن حظنا ، وعلوّ طالعنا ، فلم يكونوا يشكرون الله سبحانه على ما أنعم عليهم ( وَإِنْ تُصِبْهُمْ سَيِّئَةٌ ) كالجوع والقحط والمرض ونحوها ( يَطَّيَّرُوا ) أصله « يتطير » فأدغمت التاء في الطاء ( بِمُوسى وَمَنْ مَعَهُ ) من المؤمنين ، فكانوا يقولون : هذا من شؤم موسى وسوء طالعه ، والأصل في التطير ما كان العرب تزعمه من أن الطير إذا جاء من طرف شمال الإنسان كان شرا وإذا جاء من طرف يمينه كان خيرا ، ثم غلب التطيّر في القسم الأول ، فإذا قيل : « تطيّر » أريد أنه « تشاءم » . فكان آل فرعون يرون البلايا من موسى عليه‌السلام ولم يكونوا يعلمون أنها من سوء أعمالهم ( أَلا ) أي تنبيه أيها المخاطب ( إِنَّما طائِرُهُمْ ) والشؤم الذي كان يلحق بهم لم يكن من عند موسى ولأجله بل من ( عِنْدَ اللهِ ) فإنه كان يضربهم بالبلاء عقوبة لأعمالهم ( وَلكِنَّ أَكْثَرَهُمْ لا يَعْلَمُونَ ) ذلك بل كانوا يزعمون الشؤم من موسى عليه‌السلام .` },
            { text: "وَقَالُوا۟ مَهْمَا تَأْتِنَا بِهِۦ مِنْ ءَايَةٍ لِّتَسْحَرَنَا بِهَا فَمَا نَحْنُ لَكَ بِمُؤْمِنِينَ", tafsir: `أي قال فرعون وملأه لموسى عليه‌السلام : ( مَهْما تَأْتِنا بِهِ مِنْ آيَةٍ لِتَسْحَرَنا ) أي : أي شيء من المعجزات لتموّه علينا ( بِها ) بسببها ، تريد بذلك أن نؤمن بما تدعو إليه ( فَما نَحْنُ لَكَ بِمُؤْمِنِينَ ) ولا نصدّقك فيما جئت به من الألوهية والرسالة والوعد والوعيد. فَأَرْسَلْنا عَلَيْهِمُ الطُّوفانَ وَالْجَرادَ وَالْقُمَّلَ وَالضَّفادِعَ وَالدَّمَ آياتٍ مُفَصَّلاتٍ فَاسْتَكْبَرُوا وَكانُوا قَوْماً مُجْرِمِينَ (133)` },
            { text: "فَأَرْسَلْنَا عَلَيْهِمُ ٱلطُّوفَانَ وَٱلْجَرَادَ وَٱلْقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٍ مُّفَصَّلَٰتٍ فَٱسْتَكْبَرُوا۟ وَكَانُوا۟ قَوْمًا مُّجْرِمِينَ", tafsir: `هو الماء الغالب على أبنيتهم وأشجارهم حتّى خرّبها ( وَالْجَرادَ ) حتّى أكل أشجارهم وزرعهم ( وَالْقُمَّلَ ) هو السوس الذي يخرج من الحنطة ونحوها ( وَالضَّفادِعَ ) جمع « ضفدع » حتى كان يثب في أوانيهم وقدورهم ويكثر في بيوتهم ومحلاتهم حتّى عجزوا عنها ( وَالدَّمَ ) فقد انقلب ماء النيل دما فكانوا لا يتمكنون من شرب ولا يهنؤون بأكل وطعام ( آياتٍ مُفَصَّلاتٍ ) أي معجزات فصّلت بعضها عن بعض ، ظاهرات واضحات ( فَاسْتَكْبَرُوا ) أي تكبروا عن قبول الحق بعد كل ذلك ( وَكانُوا قَوْماً مُجْرِمِينَ ) عاصين ذوي كفر وإجرام. روي أن السحرة لما سجدوا وآمن بموسى جمع من آل فرعون قال هامان لفرعون ـ وكان وزيره ـ : إن الناس قد آمنوا بموسى فانظر من دخل في دينه فاحبسه ، فحبس كل من آمن به من بني إسرائيل ، فجاء إليه موسى ، فقال له : خلّ عن بني إسرائيل ، فلم يفعل ، فأنزل الله عليهم في تلك السنة الطوفان ، فخرّب دورهم ومساكنهم حتى خرجوا إلى البرية وضربوا الخيام ، فقال فرعون لموسى : ادع ربك حتى يكف عنا الطوفان فأخلّي عن بني إسرائيل وأصحابك ، فدعا موسى ربه فكفّ عنهم الطوفان وهمّ فرعون أن يخلي عن بني إسرائيل ، فقال له هامان : إن خليت عن بني إسرائيل غلبك موسى وأزال ملكك ، فقبل منه ولم يخلّ عن بني إسرائيل ، فأنزل عليهم في السنة الثانية الجراد فجردت كل شيء كان لهم من النبت والشجر حتى وَلَمَّا وَقَعَ عَلَيْهِمُ الرِّجْزُ قالُوا يا مُوسَى ادْعُ لَنا رَبَّكَ بِما عَهِدَ عِنْدَكَ لَئِنْ كَشَفْتَ عَنَّا الرِّجْزَ لَنُؤْمِنَنَّ لَكَ كانت تجرد شعورهم ولحاهم ، فجزع فرعون من ذلك جزعا شديدا ، وقال : يا موسى ادع ربك أن يكف عنا الجراد حتى أخلي عن بني إسرائيل وأصحابك ، فدعا موسى ربه فكفّ عنهم الجراد. فلم يدعه هامان أن يخلي عن بني إسرائيل فأنزل الله عليهم القمّل فذهب زرعهم وأصابتهم المجاعة فقال فرعون لموسى : إن دفعت عنا القمل كففت عن بني إسرائيل ، فدعا موسى ربه حتى ذهب القمل ، فلم يخلي عن بني إسرائيل ، فأرسل الله عليهم بعد ذلك الضفادع فكانت تكون في طعامهم وشرابهم ، فجزعوا من ذلك جزعا شديدا ، فجاءوا إلى موسى فقالوا : ادع الله يذهب عنا الضفادع فإنا نؤمن بك ونرسل معك بني إسرائيل ، فدعا موسى ربه فرفع الله عنهم ذلك ، فلما أبوا أن يخلوا عن بني إسرائيل حوّل الله ماء النيل دما فكان القبطي يراه دما والإسرائيلي يراه ماء فإذا شربه الإسرائيلي كان ماء وإذا شربه القبطي كان دما ، فجزعوا من ذلك جزعا شديدا فقالوا لموسى : لئن رفع عنا الدم لنرسلن معك بني إسرائيل ، فلما رفع الله عنهم الدم غدروا ولم يخلوا عن بني إسرائيل.` },
            { text: "وَلَمَّا وَقَعَ عَلَيْهِمُ ٱلرِّجْزُ قَالُوا۟ يَٰمُوسَى ٱدْعُ لَنَا رَبَّكَ بِمَا عَهِدَ عِندَكَ لَئِن كَشَفْتَ عَنَّا ٱلرِّجْزَ لَنُؤْمِنَنَّ لَكَ وَلَنُرْسِلَنَّ مَعَكَ بَنِىٓ إِسْرَٰٓءِيلَ", tafsir: `« الرجز » العذاب ، فقد أصابهم ثلج أحمر ولم يروه قبل ذلك فماتوا فيه وجزعوا وأصابهم ما لم يعهدوا من قبل ( قالُوا ) أي فرعون وملأه : ( يا مُوسَى ادْعُ لَنا رَبَّكَ بِما عَهِدَ عِنْدَكَ ) أي بما تقدم إليك أن تدعوه به ، فإنه يجيبك كما أجابك سابقا ( لَئِنْ كَشَفْتَ عَنَّا ) هذا ( الرِّجْزَ لَنُؤْمِنَنَّ لَكَ ) بما جئت به من التوحيد والنبوة وَلَنُرْسِلَنَّ مَعَكَ بَنِي إِسْرائِيلَ (134) فَلَمَّا كَشَفْنا عَنْهُمُ الرِّجْزَ إِلى أَجَلٍ هُمْ بالِغُوهُ إِذا هُمْ يَنْكُثُونَ (135) فَانْتَقَمْنا مِنْهُمْ فَأَغْرَقْناهُمْ فِي الْيَمِّ بِأَنَّهُمْ كَذَّبُوا بِآياتِنا وَكانُوا عَنْها غافِلِينَ (136) ( وَلَنُرْسِلَنَّ مَعَكَ بَنِي إِسْرائِيلَ ) فنطلق سراحهم من السجون ومن تسخيرهم بالأعمال الشاقة.` },
            { text: "فَلَمَّا كَشَفْنَا عَنْهُمُ ٱلرِّجْزَ إِلَىٰٓ أَجَلٍ هُم بَٰلِغُوهُ إِذَا هُمْ يَنكُثُونَ", tafsir: `بدعاء موسى عليه‌السلام ، ومعنى « كشف الرجز » رفع العذاب ( إِلى أَجَلٍ هُمْ بالِغُوهُ ) أي : إن رفعنا العذاب كان لأجل أن يبلغوا المدّة المحدودة المقدرة لهم ، إذ لم يقدّر موتهم في ذلك الوقت الذي نزل بهم الرجز فيه ( إِذا هُمْ يَنْكُثُونَ ) أي يخالفون وينقضون عهدهم فلا يؤمنون ولا يطلقون بني إسرائيل.` },
            { text: "فَٱنتَقَمْنَا مِنْهُمْ فَأَغْرَقْنَٰهُمْ فِى ٱلْيَمِّ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ", tafsir: `أي عذّبناهم جزاء بما فعلوا من الكفر والمعاصي ( فَأَغْرَقْناهُمْ فِي الْيَمِ ) أي في البحر ( بِأَنَّهُمْ ) أي بسبب أنهم ( كَذَّبُوا بِآياتِنا وَكانُوا عَنْها ) أي عن الآيات ( غافِلِينَ ) بمعنى أنهم كانوا يعملون عمل الغافل عن الآيات ، إذ الملتفت العاقل لا يخالف ولا يكذب ، أو المراد غافلين عن عواقب الآيات ، كما يقال : « فلان غافل عن أمر السلطة » أي عن عواقبه السيئة فيما إذا خالف. وفي بعض الروايات : أنه بعد نزول الثلج خلّي عن بني إسرائيل فاجتمعوا إلى موسى في مصر واجتمع إليه من كان هرب من مصر وبلغ فرعون ذلك ، فقال هامان : قد نهيتك أن تخلّي عن بني إسرائيل فقد استجمعوا إليه ، فجزع فرعون ، وفرّ موسى إلى الخارج واتبعهم وَأَوْرَثْنَا الْقَوْمَ الَّذِينَ كانُوا يُسْتَضْعَفُونَ مَشارِقَ الْأَرْضِ وَمَغارِبَهَا الَّتِي بارَكْنا فِيها وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنى عَلى بَنِي إِسْرائِيلَ بِما صَبَرُوا فرعون ، حتى وصلوا إلى البحر ، فدخل موسى ومن معه البحر بعد ما انشق لهم طرقا ، ولما بلغوا منتصف البحر ـ وهو البحر الأحمر ـ دخل فرعون وجنوده البحر ولما بلغ موسى آخر البحر وخرجوا ، كان فرعوا قد بلغ منتصفه ـ وعرضه أربع فراسخ تقريبا ـ وهناك أطبق الماء على أصحاب فرعون ، وأغرقوا أجمعين.` },
            { text: "وَأَوْرَثْنَا ٱلْقَوْمَ ٱلَّذِينَ كَانُوا۟ يُسْتَضْعَفُونَ مَشَٰرِقَ ٱلْأَرْضِ وَمَغَٰرِبَهَا ٱلَّتِى بَٰرَكْنَا فِيهَا وَتَمَّتْ كَلِمَتُ رَبِّكَ ٱلْحُسْنَىٰ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ بِمَا صَبَرُوا۟ وَدَمَّرْنَا مَا كَانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُۥ وَمَا كَانُوا۟ يَعْرِشُونَ", tafsir: `يعني : أعطينا بني إسرائيل الذين كانوا مستضعفين ، فإن القبط كانوا يستضعفونهم ، فأورثهم الله ( مَشارِقَ الْأَرْضِ وَمَغارِبَهَا ) أي مشارق الأرض التي كانوا فيها ، ومغاربها يعني أرض الشام ، فإن بني إسرائيل ملكوها بعد الفراعنة والعمالقة ( الَّتِي بارَكْنا فِيها ) بإخراج الزرع والثمار وسائر صنوف النبات والأشجار ( وَتَمَّتْ ) وثبتت ( كَلِمَتُ رَبِّكَ الْحُسْنى ) صفة « كلمة » أي الكلمة الحسنة التي وعدها الله ( عَلى بَنِي إِسْرائِيلَ ) فإنه أنجز وعده بإهلاك أعدائهم واستخلافهم في الأرض وكان تمام الكلمة الحسنى بسبب ما ( صَبَرُوا ) على أذى فرعون متمسكين بدينهم ، وقيل المراد ب « الكلمة الحسنى » ما بيّنه سبحانه في محل آخر بقوله : ( وَنُرِيدُ أَنْ نَمُنَّ عَلَى الَّذِينَ اسْتُضْعِفُوا فِي الْأَرْضِ وَنَجْعَلَهُمْ أَئِمَّةً وَنَجْعَلَهُمُ الْوارِثِينَ ) ـ إلى قوله ـ ( يَحْذَرُونَ ) (1) . ( 1) القصص : 6 و 7. وَدَمَّرْنا ما كانَ يَصْنَعُ فِرْعَوْنُ وَقَوْمُهُ وَما كانُوا يَعْرِشُونَ (137) وَجاوَزْنا بِبَنِي إِسْرائِيلَ الْبَحْرَ فَأَتَوْا عَلى قَوْمٍ يَعْكُفُونَ عَلى أَصْنامٍ لَهُمْ قالُوا يا مُوسَى اجْعَلْ لَنا إِلهاً كَما لَهُمْ آلِهَةٌ قالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ (138) إِنَّ هؤُلاءِ مُتَبَّرٌ ما هُمْ فِيهِ وَباطِلٌ ما كانُوا يَعْمَلُونَ (139) ( وَدَمَّرْنا ) أي نسفنا وأهلكنا ( ما كانَ يَصْنَعُ فِرْعَوْنُ ) من الأبنية والقصور ( وَ ) ما كان يصنعه ( قَوْمُهُ ) من المنازل والمزارع ( وَما كانُوا يَعْرِشُونَ ) من الأشجار والأعناب والثمار ، أي يجعلون له عريشا وسقفا.` },
            { text: "وَجَٰوَزْنَا بِبَنِىٓ إِسْرَٰٓءِيلَ ٱلْبَحْرَ فَأَتَوْا۟ عَلَىٰ قَوْمٍ يَعْكُفُونَ عَلَىٰٓ أَصْنَامٍ لَّهُمْ قَالُوا۟ يَٰمُوسَى ٱجْعَل لَّنَآ إِلَٰهًا كَمَا لَهُمْ ءَالِهَةٌ قَالَ إِنَّكُمْ قَوْمٌ تَجْهَلُونَ", tafsir: `أي قطعنا لهم بحر مصر الأحمر بأن جعلنا لهم فيه طرقا يابسة ليعبروا فلما عبروا ( فَأَتَوْا عَلى قَوْمٍ ) أي مرّوا على جماعة ( يَعْكُفُونَ عَلى أَصْنامٍ لَهُمْ ) أي يقبلون عليها ملازمين لها مقيمين عندها ( قالُوا يا مُوسَى اجْعَلْ لَنا إِلهاً ) مجسما حتى نعبده ( كَما لَهُمْ آلِهَةٌ ) يعبدونها ( قالَ ) موسى عليه‌السلام : ( إِنَّكُمْ قَوْمٌ تَجْهَلُونَ ) ربكم ولا تعظّمونه فإنه لا يجوز أن تعبد الأصنام ، لأنه شرك بالله سبحانه.` },
            { text: "إِنَّ هَٰٓؤُلَآءِ مُتَبَّرٌ مَّا هُمْ فِيهِ وَبَٰطِلٌ مَّا كَانُوا۟ يَعْمَلُونَ", tafsir: `القوم الذين يعبدون الأصنام ( مُتَبَّرٌ ) أي مدمّر مهلك ، من « التبار » بمعنى الهلاك ( ما هُمْ فِيهِ ) من عبادة الأصنام ، أي أن هذه العبادة توجب الهلاك والدمار ( وَباطِلٌ ما كانُوا يَعْمَلُونَ ) أي أن عملهم باطل لا نصيب له من الحق والحقيقة. قالَ أَ غَيْرَ اللهِ أَبْغِيكُمْ إِلهاً وَهُوَ فَضَّلَكُمْ عَلَى الْعالَمِينَ (140) وَإِذْ أَنْجَيْناكُمْ مِنْ آلِ فِرْعَوْنَ يَسُومُونَكُمْ سُوءَ الْعَذابِ يُقَتِّلُونَ أَبْناءَكُمْ وَيَسْتَحْيُونَ نِساءَكُمْ [141] ثم ( قالَ ) موسى عليه‌السلام لقومه على نحو الاستنكار والتوبيخ : ( أَ غَيْرَ اللهِ أَبْغِيكُمْ إِلهاً ) أي ألتمس وأطلب لكم إلها غير الله ، إن هذا لا يكون أبدا ( وَ ) الحال أنه إلهكم الوحيد و ( هُوَ ) الذي ( فَضَّلَكُمْ عَلَى الْعالَمِينَ ) أي عالمي زمانهم ، فإنه هو المعطي المفضل ، فكيف أتخذ إلها غيره ؟! [142] ثم خاطب الله سبحانه بني إسرائيل الموجودين في زمان الرسول صلى‌الله‌عليه‌وآله‌وسلم ليعدّد نعمه عليهم ، استدراجا لهم إلى الإيمان ، وتذكيرا بما سبق لهم منه سبحانه من الإحسان ( وَ ) اذكروا يا بني إسرائيل ( إِذْ أَنْجَيْناكُمْ مِنْ آلِ فِرْعَوْنَ ) خلّصناكم منهم ، والمراد ب « آل فرعون » قومه وذووا السلطة في ملكه ، حين كانوا ( يَسُومُونَكُمْ ) أي يولونكم ويفعلون بكم ـ من « سام فلانا » إذا عذبه وأذّله ـ ( سُوءَ الْعَذابِ ) أي العذاب السيئ. ثم بيّن سبحانه طرفا من ذلك العذاب بقوله : ( يُقَتِّلُونَ أَبْناءَكُمْ ) « التقتيل » تفعيل من القتل ، أي يكثرون القتل في الذكور منكم. فقد كان فرعون يقتل أولاد بني إسرائيل ، لئلّا يولد فيهم مولود ذكر يذهب بملكه ـ حسب ما أخبره المنجّمون ـ ثم بعد ذلك وإن علم بموسى وأرسل إليه ، أخذ يقتل الذكور ثانية ، لئلّا يجتمعون حول موسى وتقوى شوكته فيعارضوه في سلطانه ( وَيَسْتَحْيُونَ نِساءَكُمْ ) أي وَفِي ذلِكُمْ بَلاءٌ مِنْ رَبِّكُمْ عَظِيمٌ (141) وَواعَدْنا مُوسى ثَلاثِينَ لَيْلَةً وَأَتْمَمْناها بِعَشْرٍ فَتَمَّ مِيقاتُ رَبِّهِ أَرْبَعِينَ لَيْلَةً يستبقونهن أحياء للخدمة والاستمتاع والإذلال ( وَفِي ذلِكُمْ ) أي في تخلية فرعون وما يفعل بكم ( بَلاءٌ ) أي ابتلاء ( مِنْ رَبِّكُمْ ) من قبله سبحانه ليجازي الصابرين ( عَظِيمٌ ) أو المعنى : في طرف ما فعل بكم من النجاة « بلاء » أي نعمة ، فإنه يأتي بمعناها « من » طرف ربكم « عظيم » حيث تفضل عليكم بنعمة النجاة من ذلك الشقي. [143] ثم ذكر سبحانه تمام نعمه على بني إسرائيل فقال : ( وَواعَدْنا ) أي وعدنا ( مُوسى ثَلاثِينَ لَيْلَةً ) فقد روي أن موسى عليه‌السلام لما كان بمصر وعد بني إسرائيل أنه إذا أهلك الله عدوهم أتاهم بكتاب من عند الله فيه بيان ما يأتون وما يذرون ، فلما هلك فرعون سأل موسى ربه الكتاب ، فوعد الله موسى أن يأتي إلى الطور ويصوم ثلاثين يوما ثم يعطيه الكتاب الذي فيه الشرائع. ولعل ذكر « ليلة » دون « يوم » لأجل أن الليل أقرب إلى المناجاة ، فإن الظلمة تشع في النفس الانقطاع والخوف والرجاء ، مما يجعل الإنسان أقرب إلى الله سبحانه من النهار ، ولذا كان العبّاد يتخذونها ميقاتا لعبادتهم ( وَأَتْمَمْناها ) أي أكملنا الثلاثين ليلة ( بِعَشْرٍ ) ليال حتى صار المجموع أربعين ( فَتَمَّ مِيقاتُ رَبِّهِ ) أي الوقت المضروب لإعطاء الكتاب ( أَرْبَعِينَ لَيْلَةً ) وقد كان ذلك لأجل تهيئة موسى عليه‌السلام لأهلية إعطاء الكتاب ، ولئن يعرف الناس عظمة الكتاب حتى أن مثل موسى عليه‌السلام لا يعطى له إلا بعد الصيام والقيام. ولا يخفى أن الإتمام عشرا لا ينافي وعده ثلاثين ، فإن المقرّر كان وَقالَ مُوسى لِأَخِيهِ هارُونَ اخْلُفْنِي فِي قَوْمِي وَأَصْلِحْ وَلا تَتَّبِعْ سَبِيلَ الْمُفْسِدِينَ (142) وَلَمَّا جاءَ مُوسى لِمِيقاتِنا وَكَلَّمَهُ رَبُّهُ قالَ رَبِّ أَرِنِي أَنْظُرْ إِلَيْكَ إعطاء الكتاب بعد إتمام الثلاثين ، لا بمجرد إكمال الثلاثين ، وإنما قال : « فتم ميقات ربه » لئلا يوهم أن المعنى : أكملنا الثلاثين بعشر حتى كملت ثلاثين ، نحو : « أكملت العشرة بدرهمين » . ( وَ ) حين أراد موسى عليه‌السلام الخروج إلى ميقات ربه أوحى إلى أخيه هارون عليه‌السلام إذ ( قالَ مُوسى لِأَخِيهِ هارُونَ اخْلُفْنِي ) أي كن خليفتي ( فِي قَوْمِي ) فإن هارون وإن كان نبيا لكنه لم يكن رئيسا ، ففوض إليه موسى عليه‌السلام منصب الرئاسة ( وَأَصْلِحْ ) فيما بينهم وأصلحهم ( وَلا تَتَّبِعْ سَبِيلَ الْمُفْسِدِينَ ) الذين يأمرون بالفساد و يفسدون الناس ، وهارون عليه‌السلام وإن كان منزّها عن ذلك ، إلّا أن ذلك لتنبيه القوم وإرشادهم إلى عمل هارون ، فإن الإنسان قد يوصي لأجل الوصيّ ، وقد يوصي لأجل من يسمع.` },
            { text: "قَالَ أَغَيْرَ ٱللَّهِ أَبْغِيكُمْ إِلَٰهًا وَهُوَ فَضَّلَكُمْ عَلَى ٱلْعَٰلَمِينَ", tafsir: `` },
            { text: "وَإِذْ أَنجَيْنَٰكُم مِّنْ ءَالِ فِرْعَوْنَ يَسُومُونَكُمْ سُوٓءَ ٱلْعَذَابِ يُقَتِّلُونَ أَبْنَآءَكُمْ وَيَسْتَحْيُونَ نِسَآءَكُمْ وَفِى ذَٰلِكُم بَلَآءٌ مِّن رَّبِّكُمْ عَظِيمٌ", tafsir: `` },
            { text: "وَوَٰعَدْنَا مُوسَىٰ ثَلَٰثِينَ لَيْلَةً وَأَتْمَمْنَٰهَا بِعَشْرٍ فَتَمَّ مِيقَٰتُ رَبِّهِۦٓ أَرْبَعِينَ لَيْلَةً وَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخْلُفْنِى فِى قَوْمِى وَأَصْلِحْ وَلَا تَتَّبِعْ سَبِيلَ ٱلْمُفْسِدِينَ", tafsir: `` },
            { text: "وَلَمَّا جَآءَ مُوسَىٰ لِمِيقَٰتِنَا وَكَلَّمَهُۥ رَبُّهُۥ قَالَ رَبِّ أَرِنِىٓ أَنظُرْ إِلَيْكَ قَالَ لَن تَرَىٰنِى وَلَٰكِنِ ٱنظُرْ إِلَى ٱلْجَبَلِ فَإِنِ ٱسْتَقَرَّ مَكَانَهُۥ فَسَوْفَ تَرَىٰنِى فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلْجَبَلِ جَعَلَهُۥ دَكًّا وَخَرَّ مُوسَىٰ صَعِقًا فَلَمَّآ أَفَاقَ قَالَ سُبْحَٰنَكَ تُبْتُ إِلَيْكَ وَأَنَا۠ أَوَّلُ ٱلْمُؤْمِنِينَ", tafsir: `عليه‌السلام ( لِمِيقاتِنا ) « الميقات » هو الزمان أو المكان الذي قدّر ليعمل فيه ، ولذا يقال : « ميقات الحج » للمكان المقدّر فيه الإحرام ، والمعنى : أنه لمّا انتهى موسى إلى المكان الذي وقّتنا له وأمرناه بالمسير إليه لننزل عليه التوراة ، أو المراد الميقات الزماني ، أي لمّا انتهى إلى زمان المواعدة ( وَكَلَّمَهُ رَبُّهُ ) بأن خلق الكلام في الفضاء حتى سمعه موسى عليه‌السلام ، فإن الله سبحانه منزّه عن اللسان واللهاة وسائر الأمور المرتبطة بالكلام الجسدي. ( قالَ ) موسى : يا ( رَبِّ أَرِنِي ) نفسك ( أَنْظُرْ إِلَيْكَ ) نظر قالَ لَنْ تَرانِي وَلكِنِ انْظُرْ إِلَى الْجَبَلِ العيان. وقد كان هذا السؤال من موسى إجابة لطلب قومه ، فقد روي أنه لما كلّمه الله وقرّبه نجيّا رجع إلى قومه فأخبرهم بذلك ، فقالوا : لن نؤمن لك حتى نسمع كلامه كما سمعته ، فاختار منهم سبعين فخرج بهم إلى طور سيناء فأقامهم في سفح الجبل وصعد إلى الطور وسأل الله أن يكلمه ويسمعهم كلامه ، فكلمه الله فسمعوا كلامه من فوق وأسفل ويمين وشمال ووراء وأمام ، لأن الله أحدثه في الشجرة ثم جعله منبعثا منها حتى سمعوه من جميع الوجوه ، فقالوا : لن نؤمن بأن هذا الذي سمعناه من جميع الوجوه كلام الله حتى نرى الله جهرة ، فلما قالوا هذا القول العظيم واستكبروا وعتوا بعث الله عليهم صاعقة فأخذتهم الصاعقة بظلمهم فماتوا. فقال موسى : يا رب ما أقول لبني إسرائيل إذا رجعت إليهم وقالوا إنك ذهبت بهم فقتلتهم لأنك لم تكن صادقا فيما ادعيت من مناجاة الله إياك ؟ فأحياهم وبعثهم معه فقالوا : لو أنك سألت الله أن يريك تنظر إليه لأجابك فتخبرنا كيف هو ونعرفه حق معرفته ، فقال : يا قوم إن الله لا يرى بالأبصار ولا كيفية له وإنما يعرف بآياته ويعلم بعلاماته ، فقالوا : لن نؤمن لك حتى تسأله ، فقال موسى : يا رب إنك قد سمعت مقالة بني إسرائيل وأنت أعلم بصلاحهم ، فأوحى الله إليه : يا موسى سلني ما سألوك فلن أؤاخذك بجهلهم فعند ذلك قال موسى : رب أرني انظر إليك ( قالَ ) الله تعالى في جواب موسى : ( لَنْ تَرانِي ) أبدا ، فإن « لن » لنفي الأبد ، وذلك لاستحالة رؤية الله سبحانه لا في الدنيا ولا في الآخرة ، فإن للرؤية شرائط كلها مفقودة بالنسبة إليه سبحانه ، ومنها أن يكون المرئي جسما أو عرضا ، والله سبحانه ليس بجسم ولا عرض ( وَلكِنِ انْظُرْ إِلَى الْجَبَلِ ) فَإِنِ اسْتَقَرَّ مَكانَهُ فَسَوْفَ تَرانِي فَلَمَّا تَجَلَّى رَبُّهُ لِلْجَبَلِ جَعَلَهُ دَكًّا وَخَرَّ مُوسى صَعِقاً فَلَمَّا أَفاقَ قالَ سُبْحانَكَ تُبْتُ إِلَيْكَ الذي كان هناك ( فَإِنِ اسْتَقَرَّ مَكانَهُ ) حال التجلّي ( فَسَوْفَ تَرانِي ) وقد كان هذا من باب التعليق بالمحال ، فإن استقرار الجبل مكانه مع إرادة الله عدم الاستقرار له كان مستحيلا. فيكون التعليق على ذلك مثل قوله : ( حَتَّى يَلِجَ الْجَمَلُ فِي سَمِّ الْخِياطِ ) (1) ، وقوله : ( إِنْ كانَ لِلرَّحْمنِ وَلَدٌ فَأَنَا أَوَّلُ الْعابِدِينَ ) (2) ، ( لَوْ كانَ فِيهِما آلِهَةٌ إِلَّا اللهُ لَفَسَدَتا ) (3) ، مما جرى العرف بالتعليق على شيء لا يكون ، في بيان أن الشيء الفلاني لا يكون ( فَلَمَّا تَجَلَّى رَبُّهُ ) أي رب موسى عليه‌السلام ( لِلْجَبَلِ جَعَلَهُ دَكًّا ) أي مستويا مع الأرض ، والمراد بالتجلي : خلق نور يشع على الجبل ، أو إظهار قدرة وعظمة له ( وَخَرَّ مُوسى صَعِقاً ) أي وقع مغشيا عليه من الرعب والخوف ( فَلَمَّا أَفاقَ ) من غشيته ورجعت قواه إليه ( قالَ ) موسى عليه‌السلام : ( سُبْحانَكَ ) أي أنزهك تنزيها عما لا يليق بك من رؤية وغيرها من النواقص ( تُبْتُ إِلَيْكَ ) أي رجعت إليك في أموري ، ولم يكن ذلك توبة عن ذنب بل إنه على وجه الانقطاع والتخضّع ، فإن الإنسان إذا رأى الأمور الجليلة يذكر الله بالتسبيح والتقديس والاستغفار ، والسر أن هذه الألفاظ صارت إعلاما للخضوع والخشوع ، لكثرة ما استعملت فيهما. و منه الحديث : « كان النبي صلى‌الله‌عليه‌وآله‌وسلم يستغفر الله من غير ذنب » (4) وإن شئت قلت : إنه إنشاء مفهوم التوبة ( 1) الأعراف : 41. ( 2) الزخرف : 82. ( 3) الأنبياء : 23. ( 4) راجع وسائل الشيعة : ج 7 ص 180. وَأَنَا أَوَّلُ الْمُؤْمِنِينَ (143) قالَ يا مُوسى إِنِّي اصْطَفَيْتُكَ عَلَى النَّاسِ بِرِسالاتِي وَبِكَلامِي فَخُذْ ما آتَيْتُكَ وَكُنْ مِنَ الشَّاكِرِينَ (144) وَكَتَبْنا لَهُ فِي الْأَلْواحِ بداعي التعظيم ، كما أن أدوات الاستفهام في كلامه سبحانه هي لإنشاء مفهوم الاستفهام بداعي آخر ، كالمفاضلة في قوله : ( هَلْ يَسْتَوِي الَّذِينَ يَعْلَمُونَ وَالَّذِينَ لا يَعْلَمُونَ ) (1) ، ( وَأَنَا أَوَّلُ الْمُؤْمِنِينَ ) بك وبما يليق بك من الصفات.` },
            { text: "قَالَ يَٰمُوسَىٰٓ إِنِّى ٱصْطَفَيْتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِى وَبِكَلَٰمِى فَخُذْ مَآ ءَاتَيْتُكَ وَكُن مِّنَ ٱلشَّٰكِرِينَ", tafsir: `الله سبحانه : ( يا مُوسى إِنِّي اصْطَفَيْتُكَ ) أي اخترتك ( عَلَى النَّاسِ ) وفضّلتك عليهم ( بِرِسالاتِي ) حيث ألقيت إليك أنواع الرسالة في الأصول والفروع ( وَبِكَلامِي ) حيث كلّمتك دون سائر خلقي. والعطف إما للبيان ، أو المراد من الرسالة غير ما كلّم فيه ، بل كانت بالإلهام ، ومن الكلام غير ما أرسل به ، بل كان لسائر الأمور ( فَخُذْ ) يا موسى ( ما آتَيْتُكَ ) أي أعطيتك من التوراة وتمسك به ( وَكُنْ مِنَ الشَّاكِرِينَ ) لنعمتي ، والشكر إما بالجنان بأن يعرف الإنسان قدر المنعم وفضله ، وإما باللسان بأن يعترف بجميله ، وإما بالأركان بأن يأتي الإنسان بما يستحق المنعم من التعظيم والإجلال والخضوع ، قال تعالى : ( اعْمَلُوا آلَ داوُدَ شُكْراً ) (2) .` },
            { text: "وَكَتَبْنَا لَهُۥ فِى ٱلْأَلْوَاحِ مِن كُلِّ شَىْءٍ مَّوْعِظَةً وَتَفْصِيلًا لِّكُلِّ شَىْءٍ فَخُذْهَا بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا۟ بِأَحْسَنِهَا سَأُو۟رِيكُمْ دَارَ ٱلْفَٰسِقِينَ", tafsir: `أي لموسى عليه‌السلام ( فِي الْأَلْواحِ ) جمع « لوح » ، وهي القطعة من الخشب أو نحوها ، وقد نزلت على موسى عليه‌السلام ألواح ( 1) الزمر : 10. ( 2) سبأ : 14. مِنْ كُلِّ شَيْءٍ مَوْعِظَةً وَتَفْصِيلاً لِكُلِّ شَيْءٍ فَخُذْها بِقُوَّةٍ وَأْمُرْ قَوْمَكَ يَأْخُذُوا بِأَحْسَنِها سَأُرِيكُمْ دارَ الْفاسِقِينَ (145) سَأَصْرِفُ عَنْ آياتِيَ مكتوب فيها التوراة ( مِنْ كُلِّ شَيْءٍ ) مما يحتاج إليه الناس في أمور دينهم ودنياهم ( مَوْعِظَةً ) هذا تفسير لقوله « كل شيء » ، وهي عبارة عن التحذير عن القبيح ، والتبصير بمواقع الخوف ( وَتَفْصِيلاً لِكُلِّ شَيْءٍ ) أي بيانا وتوضيحا لكل أمر كانوا محتاجين إليه. ومن المعلوم أن المراد بيان الخطوط العامة للحياة الدينية ، لا كل جزئي جزئي ، وهذا هو المراد من قوله : ( لا رَطْبٍ وَلا يابِسٍ إِلَّا فِي كِتابٍ مُبِينٍ ) (1) ، لو أريد بالكتاب القرآن ، وهو المراد من قول الرسول صلى‌الله‌عليه‌وآله‌وسلم : « ما من شيء يقربكم إلى الجنة ، إلّا وقد أمرتكم به ، وما من شيء يباعدكم عن النار إلّا وقد نهيتكم عنه » (2) ، ( فَخُذْها ) أي الألواح ( بِقُوَّةٍ ) أي بجدّ واجتهاد ، والمراد بأخذها : العمل بما فيها ، كما قال سبحانه : ( يا يَحْيى خُذِ الْكِتابَ بِقُوَّةٍ ) (3) ، ( وَأْمُرْ قَوْمَكَ ) أي بني إسرائيل ( يَأْخُذُوا بِأَحْسَنِها ) وهذا تحريض بالأخذ بالفضائل ، فإن الشريعة لها عرض كبير للأمور يبتدئ من الواجبات وينتهي إلى أكمل الفضائل وهذا من باب شدة الجذب بقصد الاعتدال ، كما يشد الحمل من جانب كثيرا ليعتدل ( سَأُرِيكُمْ دارَ الْفاسِقِينَ ) أي جهنم ، فاحذروا أن تخالفوا وتفسقوا حتى تكونوا منهم.` },
            { text: "سَأَصْرِفُ عَنْ ءَايَٰتِىَ ٱلَّذِينَ يَتَكَبَّرُونَ فِى ٱلْأَرْضِ بِغَيْرِ ٱلْحَقِّ وَإِن يَرَوْا۟ كُلَّ ءَايَةٍ لَّا يُؤْمِنُوا۟ بِهَا وَإِن يَرَوْا۟ سَبِيلَ ٱلرُّشْدِ لَا يَتَّخِذُوهُ سَبِيلًا وَإِن يَرَوْا۟ سَبِيلَ ٱلْغَىِّ يَتَّخِذُوهُ سَبِيلًا ذَٰلِكَ بِأَنَّهُمْ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَكَانُوا۟ عَنْهَا غَٰفِلِينَ", tafsir: `أي أصرفهم عن الإيمان بها ، أو أصرفهم عن ( 1) الأنعام : 60. ( 2) راجع مستدرك وسائل الشيعة : ج 13 ص 30. ( 3) مريم : 13. الَّذِينَ يَتَكَبَّرُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ وَإِنْ يَرَوْا كُلَّ آيَةٍ لا يُؤْمِنُوا بِها وَإِنْ يَرَوْا سَبِيلَ الرُّشْدِ لا يَتَّخِذُوهُ سَبِيلاً وَإِنْ يَرَوْا سَبِيلَ الغَيِّ يَتَّخِذُوهُ سَبِيلاً ذلِكَ النيل منها ( الَّذِينَ يَتَكَبَّرُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِ ) فعلى المعنى الأول : أن ذلك لكونهم تكبروا ، فلم يلطف بهم الله سبحانه لطفه الخفي بل صرفهم عن الإيمان وخلّى بينهم وبين إضلال الشيطان ، كما يصرف الإنسان ولده العاصي عن لطفه فلا يعتني بشأنه. وعلى المعنى الثاني : يكون المعنى حفظ الآيات عن الزيادة والنقصان كما قال سبحانه : ( إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحافِظُونَ ) (1) ، والأول أقرب ، وقوله : ( بِغَيْرِ الْحَقِ ) ليس قيدا احترازيا ، بل لبيان أن التكبر لا يكون إلا بغير الحق ، نحو : ( يَقْتُلُونَ النَّبِيِّينَ بِغَيْرِ الْحَقِ ) (2) . ثم وصف سبحانه أولئك بقوله : ( وَإِنْ يَرَوْا ) أي يرى المتكبرين ( كُلَّ آيَةٍ ) ومعجزة دالة على صدق الأنبياء وسائر الأمور الحقة ( لا يُؤْمِنُوا بِها ) حيث قد لجّوا في الفساد واستحوذ عليهم الشيطان ( وَإِنْ يَرَوْا سَبِيلَ الرُّشْدِ ) أي طريق الهدى والحق ، الموجب للرشد والنمو العقلي والمادي ، فإن الرشد بمعنى النمو ( لا يَتَّخِذُوهُ سَبِيلاً ) فلا يسلكوه ( وَإِنْ يَرَوْا سَبِيلَ الغَيِ ) أي طريق الغواية والضلال ( يَتَّخِذُوهُ سَبِيلاً ) لأنفسهم فيسلكوه ( ذلِكَ ) أي سبب صرفهم عن الآيات ـ على المعنى الأول ـ أو سبب اجتنابهم طريق الرشد واتخاذهم طريق الغي ( 1) الحجر : 10. ( 2) البقرة : 62. بِأَنَّهُمْ كَذَّبُوا بِآياتِنا وَكانُوا عَنْها غافِلِينَ (146) وَالَّذِينَ كَذَّبُوا بِآياتِنا وَلِقاءِ الْآخِرَةِ حَبِطَتْ أَعْمالُهُمْ هَلْ يُجْزَوْنَ إِلاَّ ما كانُوا يَعْمَلُونَ (147) وَاتَّخَذَ قَوْمُ مُوسى مِنْ بَعْدِهِ مِنْ حُلِيِّهِمْ عِجْلاً جَسَداً ( بِأَنَّهُمْ كَذَّبُوا بِآياتِنا ) أي بحججنا ومعجزات رسلنا ( وَكانُوا عَنْها غافِلِينَ ) لا يتفكرون فيها ولا يتعظون بها ، والمراد تشبيههم بالغافل الذي يغفل عن صلاحه فلا يعمل بمقتضاه.` },
            { text: "وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَلِقَآءِ ٱلْـَٔاخِرَةِ حَبِطَتْ أَعْمَٰلُهُمْ هَلْ يُجْزَوْنَ إِلَّا مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `أي المعجزات والحجج ( وَ ) كذبوا ب ( لِقاءِ الْآخِرَةِ ) بأن أنكروا القيامة والبعث والنشور ( حَبِطَتْ أَعْمالُهُمْ ) التي عملوها ، فإن كل إنسان يعمل بعض الأعمال الخيرة ، فإذا كان مؤمنا يثاب عليها ، وإن كان كافرا لم يثب عليها ، وهذا لا ينافي خفة العذاب ، كما ورد في حاتم وأنو شروان وغيرهما ( هَلْ يُجْزَوْنَ ) أي لا يجزى هؤلاء المتكبرون ، فإن الاستفهام للإنكار ( إِلَّا ما كانُوا يَعْمَلُونَ ) فليس حبط أعمالهم ظلما لهم. [149] ثم يبيّن سبحانه طرفا آخر من قصة بني إسرائيل ، وهي قصة عبادتهم للعجل حين كان موسى عليه‌السلام في الطور ( وَاتَّخَذَ قَوْمُ مُوسى مِنْ بَعْدِهِ ) أي من بعد خروج موسى عليه‌السلام إلى ميقات ربه ( مِنْ حُلِيِّهِمْ ) الذهبية التي كانت لهم ، من سوار وخلخال وقلادة وغيرها ( عِجْلاً ) أي صبّوا الحلي في صورة العجل وهو ولد البقر ( جَسَداً ) أي لا روح فيه ، فكان تمثال العجل وصورته ، لا واقعه وحقيقته ، ولعل هذا القيد لئلّا يتوهّم أن القوم ألبسوا الحلي عجلا حقيقيا ، فإن موسى عليه‌السلام لما أبطأ لَهُ خُوارٌ أَ لَمْ يَرَوْا أَنَّهُ لا يُكَلِّمُهُمْ وَلا يَهْدِيهِمْ سَبِيلاً أشاع رجل من بني إسرائيل واسمه « السامري » أن موسى قد مات ثم جمع حلي القوم وصاغها عجلا ، وقال لبني إسرائيل : إن هذا إلهكم ، وقد كان العجل من آلهة مصر ، وكانوا يألفون عبادته ، ولذا قبلوه ، وقد طلبوا سابقا من موسى عليه‌السلام أن يجعل لهم إلها. وفي بعض التفاسير : إن القوم الذين رآهم بنو إسرائيل على البحر كانوا يعبدون العجل ، حين قالوا لموسى : ( اجْعَلْ لَنا إِلهاً كَما لَهُمْ آلِهَةٌ ) (1) ، وكان العجل الذي صنعه السامري ( لَهُ خُوارٌ ) أي صوت كصوت العجل. وقد اختلف في ذلك ، ففي بعض التفاسير أن السامري صنعه بحيث إذا هبّت عليه الريح دخلت في جوفه فأحدثت صوتا. وفي تفسير آخر : إن « السامري » رأى جبريل عليه‌السلام راكبا فرسا حين عبروا البحر ، فأخذ من تحت حافر فرسه التراب ، فأدخله جوف العجل ، وكان منه الخوار ، أو أن الخوار كان منه سبحانه حيث خلقه فيه للابتلاء. ولا يستشكل : أنه كيف يخلق ذلك ، وهو موجب لافتتان الناس ؟ فإن الجواب واضح : إذ المحل لم يكن محل اشتباه فقد علموا جميعا أن الله سبحانه لا يرى وليس بجسم ، فكان ضلالهم بسوء اختيارهم. ( أَ لَمْ يَرَوْا ) أولئك الذين عبدوا العجل ( أَنَّهُ لا يُكَلِّمُهُمْ ) فمن هو عاجز عن أقل شيء وهو الكلام كيف يكون إلها ؟ ( وَلا يَهْدِيهِمْ سَبِيلاً ) أي لا يرشدهم إلى خير ليأتوه ولا إلى شر ليجتنبوه ( 1) الأعراف : 139. اتَّخَذُوهُ وَكانُوا ظالِمِينَ (148) وَلَمَّا سُقِطَ فِي أَيْدِيهِمْ وَرَأَوْا أَنَّهُمْ قَدْ ضَلُّوا قالُوا لَئِنْ لَمْ يَرْحَمْنا رَبُّنا وَيَغْفِرْ لَنا لَنَكُونَنَّ مِنَ الْخاسِرِينَ (149) وَلَمَّا رَجَعَ مُوسى إِلى قَوْمِهِ غَضْبانَ أَسِفاً ( اتَّخَذُوهُ ) أي اتخذوا العجل إلها ، فإن كثيرا منهم أطاعوا السامري في عبادة العجل ، ولم يطيعوا هارون فيما وعظهم وأنذرهم ( وَكانُوا ظالِمِينَ ) لأنفسهم بهذه العبادة حيث حرموها من خير الدنيا وسعادة الآخرة.` },
            { text: "وَٱتَّخَذَ قَوْمُ مُوسَىٰ مِنۢ بَعْدِهِۦ مِنْ حُلِيِّهِمْ عِجْلًا جَسَدًا لَّهُۥ خُوَارٌ أَلَمْ يَرَوْا۟ أَنَّهُۥ لَا يُكَلِّمُهُمْ وَلَا يَهْدِيهِمْ سَبِيلًا ٱتَّخَذُوهُ وَكَانُوا۟ ظَٰلِمِينَ", tafsir: `` },
            { text: "وَلَمَّا سُقِطَ فِىٓ أَيْدِيهِمْ وَرَأَوْا۟ أَنَّهُمْ قَدْ ضَلُّوا۟ قَالُوا۟ لَئِن لَّمْ يَرْحَمْنَا رَبُّنَا وَيَغْفِرْ لَنَا لَنَكُونَنَّ مِنَ ٱلْخَٰسِرِينَ", tafsir: `أي سقط البلاء في يدهم ، وهذا من باب التمثيل والتشبيه ، فإن الإنسان إذا عمل عملا فندم ، يقال : « سقط في يده » كأن الشيء الذي اكتسبه لم يرج ، ولم يذهب كما هو عادة المتاع الجيد ، بل سقط في يده وبقي عنده ، وكأن الأصل فيه أن المتاع يسقط من محله إلى مستقره ، وهو الذي يصرفه لأجل حوائجه ، فإذا بقي عند الواسطة ـ وهو التاجر ـ كان ساقطا في يده ، دون يد المستهلك ( وَرَأَوْا أَنَّهُمْ قَدْ ضَلُّوا ) فإنهم بعد ما عبدوا العجل ندموا فيما أفرطوا ، كما هو شأن غالب الحركات الاعتباطية فإن الناس يأتون بها من فورهم ثم يندمون حينما يتفكرون ( قالُوا لَئِنْ لَمْ يَرْحَمْنا رَبُّنا ) بقبول توبتنا ( وَيَغْفِرْ لَنا ) ما فعلناه من عبادة العجل ( لَنَكُونَنَّ مِنَ الْخاسِرِينَ ) الذين خسروا أنفسهم باستحقاق العقاب ، وفوت الثواب.` },
            { text: "وَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوْمِهِۦ غَضْبَٰنَ أَسِفًا قَالَ بِئْسَمَا خَلَفْتُمُونِى مِنۢ بَعْدِىٓ أَعَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى ٱلْأَلْوَاحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُۥٓ إِلَيْهِ قَالَ ٱبْنَ أُمَّ إِنَّ ٱلْقَوْمَ ٱسْتَضْعَفُونِى وَكَادُوا۟ يَقْتُلُونَنِى فَلَا تُشْمِتْ بِىَ ٱلْأَعْدَآءَ وَلَا تَجْعَلْنِى مَعَ ٱلْقَوْمِ ٱلظَّٰلِمِينَ", tafsir: `من الميقات ( إِلى قَوْمِهِ ) وعرف الأمر صار ( غَضْبانَ أَسِفاً ) أي حزينا على ما صدر منهم من عبادة العجل ، أو المراد رجع غضبان آسفا ، لما أعلمه الله سبحانه من عبادتهم العجل قالَ بِئْسَما خَلَفْتُمُونِي مِنْ بَعْدِي أَ عَجِلْتُمْ أَمْرَ رَبِّكُمْ وَأَلْقَى الْأَلْواحَ وَأَخَذَ بِرَأْسِ أَخِيهِ يَجُرُّهُ إِلَيْهِ قالَ ابْنَ أُمَّ إِنَّ الْقَوْمَ اسْتَضْعَفُونِي وَكادُوا يَقْتُلُونَنِي فَلا تُشْمِتْ بِيَ الْأَعْداءَ وَلا تَجْعَلْنِي مَعَ الْقَوْمِ الظَّالِمِينَ (150) ( قالَ ) لهم : ( بِئْسَما خَلَفْتُمُونِي ) أي عملتم خلفي ( مِنْ بَعْدِي ) أي بعد ذهابي إلى الميقات ، فإن عملكم بعدي كان عملا سيئا ( أَ عَجِلْتُمْ أَمْرَ رَبِّكُمْ ) أي استعجلتم قضاء الله وعقابه ، فكأن العاصي لا بد وأن يلاقي العقاب ، فإذا فعل فعلا شنيعا استعجل العقاب ( وَأَلْقَى الْأَلْواحَ ) المكتوب فيها التوراة من يده تضجرا من عملهم ( وَأَخَذَ بِرَأْسِ أَخِيهِ ) هارون ( يَجُرُّهُ إِلَيْهِ ) إما لينحّيه ناحية فيناجيه في أمر القوم ، وإما إظهارا للغضب ، ولم يكن ذلك إلا استنكارا عمليا لعمل القوم ، كما يصيح الوالد على ولده البريء ، فيما إذا عمل بعض أهل البيت عملا مخالفا ، يريد بذلك إظهار غضبه على عملهم. ( قالَ ) هارون : يا ( ابْنَ أُمَ ) هذه الكلمة للاستعطاف لأن ذكر الأم يشع في النفس حنانا ولينا ، وقد قصد هارون بهذا التعبير التسكين من غضب موسى عليه‌السلام ( إِنَّ الْقَوْمَ اسْتَضْعَفُونِي ) أي اتخذوني ضعيفا ، فلم يعملوا بكلامي ( وَكادُوا يَقْتُلُونَنِي ) أي همّوا بقتلي حين شددت عليهم في استنكاري عليهم عبادة العجل ( فَلا تُشْمِتْ بِيَ الْأَعْداءَ ) فإن فعلك هذا يوهم أنك غاضب عليّ فيفرح الأعداء حيث يظنون أنهم ألقوا الخلاف بين الأخوين وجعلوني مغضوبا عليه في نظرك. ومعنى الشماتة : إظهار الفرح بوقوع عدوهم في المحذور ( وَلا تَجْعَلْنِي مَعَ الْقَوْمِ الظَّالِمِينَ ) ( قالَ رَبِّ اغْفِرْ لِي وَلِأَخِي وَأَدْخِلْنا فِي رَحْمَتِكَ وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ (151) إِنَّ الَّذِينَ اتَّخَذُوا الْعِجْلَ سَيَنالُهُمْ غَضَبٌ مِنْ رَبِّهِمْ وَذِلَّةٌ فِي الْحَياةِ الدُّنْيا الذين عبدوا العجل ، فلا تشملني معهم في الغضب علينا جميعا ، فإن ذلك من عملهم. إن هذا النحو من إظهار الغضب على الحبيب البريء ، لتنبيه العدو الآثم ، من أساليب البلاغة العملية حيث أن الحبيب لا يحمل موجدة على حبيبه بسبب هذا العمل ، بخلاف ما لو عمل بالآثم فإنه يجعله أبعد من الصواب ، إذ يسبب مثل ذلك في نفسه بغضا وعداوة زائدة ، ومثل خطاب البريء ، ما يفعله الإنسان بنفسه عند إرادة إظهار الغضب من ضرب نفسه ، أو نتف شعره ، أو شق جيبه ، أو ما أشبه ذلك.` },
            { text: "قَالَ رَبِّ ٱغْفِرْ لِى وَلِأَخِى وَأَدْخِلْنَا فِى رَحْمَتِكَ وَأَنتَ أَرْحَمُ ٱلرَّٰحِمِينَ", tafsir: `موسى عليه‌السلام بعد ذلك : ( رَبِّ اغْفِرْ لِي وَلِأَخِي ) قال على وجه الانقطاع إلى الله سبحانه ، لا لأنه صدر منهما عصيان أو ذنب ، وقد تقدم أن هذه الكلمة تقال عند إظهار الخضوع والخشوع ، وإن كان الأصل فيها طلب غفران الذنب ( وَأَدْخِلْنا فِي رَحْمَتِكَ ) أي لطفك أو جنتك ( وَأَنْتَ أَرْحَمُ الرَّاحِمِينَ ) فإن رحمتك أكبر من رحمة كل راحم ، وهذا يذكر في آخر الدعاء استعطافا ، كما يقال : « أنت أجود الأجودين » لاستدعاء الجود ، لأنه اعتراف بالأفضلية. [153] ثم قال موسى عليه‌السلام ، أو استئناف من الله سبحانه : ( إِنَّ الَّذِينَ اتَّخَذُوا الْعِجْلَ ) إلها معبودا ( سَيَنالُهُمْ ) أي يلحقهم ( غَضَبٌ مِنْ رَبِّهِمْ ) في الآخرة ، وهو موجب للنار ( وَذِلَّةٌ فِي الْحَياةِ الدُّنْيا ) فإنهم وَكَذلِكَ نَجْزِي الْمُفْتَرِينَ (152) وَالَّذِينَ عَمِلُوا السَّيِّئاتِ ثُمَّ تابُوا مِنْ بَعْدِها وَآمَنُوا إِنَّ رَبَّكَ مِنْ بَعْدِها لَغَفُورٌ رَحِيمٌ (153) وَلَمَّا سَكَتَ عَنْ مُوسَى الْغَضَبُ أَخَذَ الْأَلْواحَ وَفِي نُسْخَتِها هُدىً وَرَحْمَةٌ لِلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ (154) يصبحون أذلاء ، يكثر فيهم القتل والطرد ، ويذكرون بسوء أبدا. وقد مر تفسير قوله تعالى : ( ضُرِبَتْ عَلَيْهِمُ الذِّلَّةُ ) (1) ، ( وَ ) كما جازينا اليهود بهذا الصنيع ( كَذلِكَ نَجْزِي ) سائر ( الْمُفْتَرِينَ ) الذين يفترون على الله سبحانه باتخاذ الأصنام شريكا له ، فإنه افتراء على الحقيقة والواقع.` },
            { text: "إِنَّ ٱلَّذِينَ ٱتَّخَذُوا۟ ٱلْعِجْلَ سَيَنَالُهُمْ غَضَبٌ مِّن رَّبِّهِمْ وَذِلَّةٌ فِى ٱلْحَيَوٰةِ ٱلدُّنْيَا وَكَذَٰلِكَ نَجْزِى ٱلْمُفْتَرِينَ", tafsir: `` },
            { text: "وَٱلَّذِينَ عَمِلُوا۟ ٱلسَّيِّـَٔاتِ ثُمَّ تَابُوا۟ مِنۢ بَعْدِهَا وَءَامَنُوٓا۟ إِنَّ رَبَّكَ مِنۢ بَعْدِهَا لَغَفُورٌ رَّحِيمٌ", tafsir: `لكن المعصية لا تسبب يأس صاحبها ، فإن من تاب ، تاب الله عليه ف ( الَّذِينَ عَمِلُوا السَّيِّئاتِ ) أي الشرك والمعاصي ( ثُمَّ تابُوا مِنْ بَعْدِها ) أي بعد السيئات ( وَآمَنُوا ) إيمانا صادقا ( إِنَّ رَبَّكَ ) يا رسول الله ( مِنْ بَعْدِها ) أي بعد السيئات ، أو بعد التوبة ، ولعل التكرار لإفادة عدم قبول التوبة مع الإصرار على المعصية ، كما أنه لا توبة مع الإصرار ( لَغَفُورٌ ) يغفر الذنب ( رَحِيمٌ ) يرحم التائب بفضله ولطفه.` },
            { text: "وَلَمَّا سَكَتَ عَن مُّوسَى ٱلْغَضَبُ أَخَذَ ٱلْأَلْوَاحَ وَفِى نُسْخَتِهَا هُدًى وَرَحْمَةٌ لِّلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ", tafsir: `أي : سكن ، وفيه من البلاغة ما لا يخفى ( عَنْ مُوسَى الْغَضَبُ ) بأن زالت فورته ، فإن فورة الغضب تكون أول ملاقاة المكروه ( أَخَذَ الْأَلْواحَ ) التي كان عليه‌السلام رماها إظهارا لضجره ، مما فيها التوراة ( وَفِي نُسْخَتِها ) أي ما نسخ ورقم فيها ( هُدىً ) يهدي إلى الحق ( وَرَحْمَةٌ ) موجب ترحّم وتنعّم ( لِلَّذِينَ هُمْ لِرَبِّهِمْ يَرْهَبُونَ ) أي ( 1) البقرة : 62. وَاخْتارَ مُوسى قَوْمَهُ سَبْعِينَ رَجُلاً لِمِيقاتِنا فَلَمَّا أَخَذَتْهُمُ الرَّجْفَةُ قالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُمْ مِنْ قَبْلُ وَإِيَّايَ أَ تُهْلِكُنا بِما فَعَلَ السُّفَهاءُ مِنَّا يخشونه ولا يعصونه. [156] ثم بيّن سبحانه قصة سبق الإشارة إليها ، وهي قصة طلب القوم أن يروا الله جهرة وقد كررت أولا لأجل ذكرها في قصة موسى ، وثانيا لأجل بيان أنها كانت من قومه ، وقيل : إنها قصة ثانية ، ذهبوا معه عليه‌السلام للاعتذار من عبادة العجل ، فإنهم طلبوا من موسى أن يصحبهم ليسمعوا كلام الله سبحانه ( وَاخْتارَ مُوسى قَوْمَهُ ) أي من قومه ( سَبْعِينَ رَجُلاً لِمِيقاتِنا ) ليسمعوا كلام الله سبحانه بأسماعهم ، فيزدادون إيمانا ، ولما سمعوا كلام الله سبحانه ، لم يقنعوا وطلبوا من موسى عليه‌السلام أن يروا الله جهرة ، رؤية الأبصار ، لا رؤية العلم بالقلب ( فَلَمَّا أَخَذَتْهُمُ الرَّجْفَةُ ) الصاعقة التي رجفت بسببها أبدانهم وقلوبهم وهلكوا جميعا لسؤالهم الشنيع وعنادهم في الأمر بعد ما نصحهم موسى عليه‌السلام ، إن ذلك غير ممكن كما تقدمت الإشارة إليه. وهنا خاف موسى عليه‌السلام أن يتهمه بنو إسرائيل أنه هو الذي قتلهم ، لمّا لم يتمكن من إسماعهم كلام الله سبحانه ، فيرتدوا عن الدين ، ولذا ( قالَ ) موسى عليه‌السلام لله : يا ( رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُمْ مِنْ قَبْلُ ) هذا الموقف حين كانوا في بلادهم ، لكن الآن ماذا أقول لبني إسرائيل إذا قالوا إنك قتلتهم ؟ ( وَإِيَّايَ ) وهذا للتخضّع والاستكانة ، وتسليم الأمر إليه سبحانه ، فإنه تعالى لو شاء أهلك الجميع وأماتهم ، فكلنا تحت إرادتك وفي قبضتك. ( أَ تُهْلِكُنا ) يا رب ( بِما فَعَلَ السُّفَهاءُ مِنَّا ) وقد جاء الرجاء بصيغة إِنْ هِيَ إِلاَّ فِتْنَتُكَ تُضِلُّ بِها مَنْ تَشاءُ وَتَهْدِي مَنْ تَشاءُ أَنْتَ وَلِيُّنا فَاغْفِرْ لَنا وَارْحَمْنا وَأَنْتَ خَيْرُ الْغافِرِينَ (155) الاستفهام ، كما أنك إذا رجوت الأمير في سماع كلامك تقول : « هل يسمع الأمير كلامي» ، أي أن الإهلاك بسبب ما طلبه السفهاء من الرؤية ، خلاف رجائنا فيك ، وإن كان بالاستحقاق ، حيث أن مثل هذا الطلب من السفهاء وسكوت العقلاء عنهم ـ بعدم إنكار المنكر ـ موجب لاستحقاق العقوبة ، وإضافة الهلاك إلى ضمير المتكلم مع الغير « نا » باعتبار كون موسى عليه‌السلام ومن معه كتلة واحدة ، فهلاك بعضهم هلاك للجميع ـ مجازا ـ. ثم بيّن عليه‌السلام أن ذلك الهلاك لم يكن اعتباطا ، حتى لا يظن الظان أن موسى عليه‌السلام في مقام الاعتراض ( إِنْ هِيَ ) ما هذه الرجفة التي أصابتهم ( إِلَّا فِتْنَتُكَ ) واختبارك ، إنك يا رب صنعت ذلك لأجل الامتحان ، والإهلاك امتحان للناس ليعتبروا ، ولنفس الهالكين بعد حياتهم ( تُضِلُّ بِها ) أي بالفتنة ( مَنْ تَشاءُ ) ممن لم تنفعه الهداية ، حيث تتركه وشأنه ليضل. وقد سبق أن الفعل ينسب إلى الله تعالى ، لأن الأسباب والآلات منه تعالى ، كما يقال : « أفسد فلان ولده » إذا أعطاه المال ولم يؤاخذه بعمله الفاسد ( وَتَهْدِي مَنْ تَشاءُ ) لم يذكر هنا « بها » لأن الهداية تكون بدون الاختبار أيضا ، فالهداية أعم من الابتدائية ومما تتعقب الاختبار ( أَنْتَ ) يا رب ( وَلِيُّنا ) مولانا وأولى بالتصرف فينا فلك ما تفعل ولا تسأل عن فعلك ( فَاغْفِرْ لَنا ) بستر ذنوب من أذنب منّا ( وَارْحَمْنا ) بفضلك ورحمتك ( وَأَنْتَ خَيْرُ الْغافِرِينَ ) فإن غفرانك بلا منة وذلة. ثم إنه سبحانه أحيى السبعين الذين هلكوا ، كما تقدم في سورة البقرة. وَاكْتُبْ لَنا فِي هذِهِ الدُّنْيا حَسَنَةً وَفِي الْآخِرَةِ إِنَّا هُدْنا إِلَيْكَ قالَ عَذابِي أُصِيبُ بِهِ مَنْ أَشاءُ وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ` },
            { text: "وَٱخْتَارَ مُوسَىٰ قَوْمَهُۥ سَبْعِينَ رَجُلًا لِّمِيقَٰتِنَا فَلَمَّآ أَخَذَتْهُمُ ٱلرَّجْفَةُ قَالَ رَبِّ لَوْ شِئْتَ أَهْلَكْتَهُم مِّن قَبْلُ وَإِيَّٰىَ أَتُهْلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآ إِنْ هِىَ إِلَّا فِتْنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهْدِى مَن تَشَآءُ أَنتَ وَلِيُّنَا فَٱغْفِرْ لَنَا وَٱرْحَمْنَا وَأَنتَ خَيْرُ ٱلْغَٰفِرِينَ", tafsir: `` },
            { text: "وَٱكْتُبْ لَنَا فِى هَٰذِهِ ٱلدُّنْيَا حَسَنَةً وَفِى ٱلْـَٔاخِرَةِ إِنَّا هُدْنَآ إِلَيْكَ قَالَ عَذَابِىٓ أُصِيبُ بِهِۦ مَنْ أَشَآءُ وَرَحْمَتِى وَسِعَتْ كُلَّ شَىْءٍ فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَٱلَّذِينَ هُم بِـَٔايَٰتِنَا يُؤْمِنُونَ", tafsir: `يا رب ( فِي هذِهِ الدُّنْيا حَسَنَةً ) الشيء الحسن ، وهو جنس شامل لأنواع الحسنات من أمن وصحة ورفاه وفضيلة وغيرها ( وَفِي الْآخِرَةِ ) حسنة ، بالجنة والرضوان ( إِنَّا هُدْنا إِلَيْكَ ) من « هاد » بمعنى « رجع » أي رجعنا بتوبتنا إليك ، فكأن العاصي يبتعد عنه سبحانه ، ثم إذا تاب يرجع إليه ، تشبيها للبعد والقرب عن الرحمة ، بالقرب والبعد الحسّيّين. وموسى عليه‌السلام وإن لم يكن داخلا في العصيان لكن العادة جرت على أن يتكلم الرؤساء عن جماعتهم ( قالَ ) الله سبحانه في جواب موسى وطلبه التوبة : ( عَذابِي أُصِيبُ بِهِ مَنْ أَشاءُ ) ممن استحق ذلك بالكفر والمعصية ، فالمشيئة ليست باعتبار الزيادة عمّن استحق ، بل باعتبار النقصان ، فإنه تعالى لا يعذب بعض المستحقين ، لا أنه يعذب المستحقين ( وَرَحْمَتِي وَسِعَتْ كُلَّ شَيْءٍ ) فإن الخلق والرزق وغيرهما كلها رحمة منه سبحانه ، و في الدعاء : « يا من سبقت رحمته غضبه » (1) ، باعتبار أن الغضب لا يكون إلا بعد الخلق والرزق والعصيان ، فالرحمة سابقة. وفي هذا الجو الرقيق ، الذي ترقّقت فيه قلوب بني إسرائيل يشير سبحانه إلى النبي الأمي ، ليتركّز في قلوبهم ، فإن الأمور تتركز في ( 1) مصباح الكفعمي : ص 667. فَسَأَكْتُبُهَا لِلَّذِينَ يَتَّقُونَ وَيُؤْتُونَ الزَّكَاةَ وَالَّذِينَ هُم بِآيَاتِنَا يُؤْمِنُونَ (157) الَّذِينَ يَتَّبِعُونَ الرَّسُولَ النَّبِيَّ الأُمِّيَّ الَّذِي يَجِدُونَهُ مَكْتُوبًا عِندَهُمْ فِي التَّوْرَاةِ وَالإِنْجِيلِ القلوب أكثر إذا رقّت ( فَسَأَكْتُبُها ) أي اكتب رحمتي. وهذا على سبيل الاستخدام ، فإن المراد بالرحمة أولا جميع أقسام الرحمة ، والمراد بها من الضمير ثانيا : الرحمة الخاصة الزائدة ( لِلَّذِينَ يَتَّقُونَ ) الكفر والمعاصي ( وَيُؤْتُونَ الزَّكاةَ ) أي يعطونها ( وَالَّذِينَ هُمْ بِآياتِنا ) أي بحججنا ودلالاتنا ( يُؤْمِنُونَ ) . ثم بيّن أولئك بقوله :` },
            { text: "ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ أُو۟لَٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ", tafsir: `أي أن الذين تكتب لهم الرحمة الكاملة هم التابعون لمحمد صلى‌الله‌عليه‌وآله‌وسلم ( الْأُمِّيَ ) نسبة إلى أم القرى « مكة » وبمعنى الذي لم يتعلم عند معلم ـ وإن كان صلى‌الله‌عليه‌وآله‌وسلم يعلم كل شيء بوحي الله وإرادته ـ والعرب تسمي من لم يتعلم ب « الأمي » ، نسبة إلى الأم ، كأنه بقي مثل ما ولدته أمه ( الَّذِي يَجِدُونَهُ مَكْتُوباً عِنْدَهُمْ فِي التَّوْراةِ وَالْإِنْجِيلِ ) فإن الكتابين بشّرا به صلى‌الله‌عليه‌وآله‌وسلم وأخبرا بنعته ، و إنما حرّفهما ـ بعد ذلك ـ اليهود والنصارى. وللشيخ محمد صادق فخر الإسلام ، في كتابه « أنيس الأعلام » قصة طويلة حول هذا الموضوع ، ولم يكن هذا بدعا ، فقد كان كل نبي سابق يبشر بالنبي اللاحق ، كما أن كل نبي لا حق يصدّق النبي السابق ، ونحن اليوم نرى صفة الإمام المهدي عليه‌السلام في كتبنا ، حيث وعدنا بظهوره « عجل الله فرجه » . ثم بيّن سبحانه سائر صفاته التي تجعل من دينه دين الفضيلة يَأْمُرُهُم بِالْمَعْرُوفِ وَيَنْهَاهُمْ عَنِ الْمُنكَرِ وَيُحِلُّ لَهُمُ الطَّيِّبَاتِ وَيُحَرِّمُ عَلَيْهِمُ الْخَبَآئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَالأَغْلاَلَ الَّتِي كَانَتْ عَلَيْهِمْ والحرية الصحيحة والسعادة ( يَأْمُرُهُمْ بِالْمَعْرُوفِ ) فما يأمرهم به يكون معروفا يقبله عرف العقلاء ويرتضيه ( وَيَنْهاهُمْ عَنِ الْمُنْكَرِ ) فما ينهاهم عنه يكون منكرا عند عرف العقلاء ، فأمره ونهيه حسب الموازين العرفية العقلية ، لا اعتباطا واشتهاء ( وَيُحِلُّ لَهُمُ الطَّيِّباتِ ) المستلذات الحسنة ، من مأكل ومشرب ومنكح ومسكن ومركب وغيرها ( وَيُحَرِّمُ عَلَيْهِمُ الْخَبائِثَ ) القبائح التي تعافها النفوس المستقيمة ، فتحليله وتحريمه ليسا اعتباطين ، بل لشيء في ذات الحلال والحرام ، بخلاف تحليل سائر الناس وتحريمهم ، فإنهم قد يحرمون الطيب ، كما حرمت الجاهلية السائبة وما إليها ، وقد يحللون الخبيث كما أن اليهودية والنصرانية ومن إليهما يحللون الخمر ولحم الخنزير. ثم لا يخفى أن الأمر والنهي أعم من التحليل والتحريم ، لكن حيث تقابلا ، كان لكل منهما مصداق غير مصداق الآخر. ( وَيَضَعُ عَنْهُمْ إِصْرَهُمْ ) أي ثقلهم ، فإن الإصر هو الحمل الثقيل ومعنى « وضعه » أن مناهجه سهلة سمحة لا ثقل فيها ولا صعوبة ( وَ ) يضع عنهم ( الْأَغْلالَ الَّتِي كانَتْ عَلَيْهِمْ ) أغلال جمع « غلّ » ، وهو ما يقيد يد الإنسان أو رجله أو غيرهما ، فإن من خواص الإسلام أنه يطلق الحريات المعقولة ، فالسفر والإقامة والتجارة والزراعة والصناعة والبيع والشراء والكلام والكتابة والتجمع وغيرها ، كلها مباحة لا قيود عليها إلا بعض الشرائط الطفيفة التي هي في صالح المجتمع والفرد ، ولا فَالَّذِينَ آمَنُواْ بِهِ وَعَزَّرُوهُ وَنَصَرُوهُ وَاتَّبَعُواْ النُّورَ الَّذِيَ أُنزِلَ مَعَهُ أُوْلَـئِكَ هُمُ الْمُفْلِحُونَ (158) قُلْ يَا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللّهِ إِلَيْكُمْ جَمِيعًا الَّذِي لَهُ مُلْكُ السَّمَاوَاتِ وَالأَرْضِ يعلم مدى ذلك إلا بالمقايسة إلى الأنظمة والمناهج الدنيوية التي كلها كبت واستعباد واستغلال ( فَالَّذِينَ آمَنُوا بِهِ ) أي بالرسول محمد صلى‌الله‌عليه‌وآله‌وسلم ( وَعَزَّرُوهُ ) أي عظّموه ووقروه ( وَنَصَرُوهُ ) على أعدائه ( وَاتَّبَعُوا النُّورَ الَّذِي أُنْزِلَ مَعَهُ ) أي القرآن ، فإنه نور يهتدى به في مسالك الحياة المظلمة ، كما أن الضياء يهتدى به في مسالك الليل المظلم ، أو المراد : علي والأئمة عليهم‌السلام كما في بعض الأحاديث ، أو الجميع ، لأنه لفظ عام ، وكل واحد من هذه الأمور مصداق ، و « الإنزال » بالنسبة إلى الأئمة ليس فيه محذور ، لما سبق ، أن التعبير بالإنزال في مثل هذه الموارد من جهة الله سبحانه الواهب لهذه الأشياء كما قال : ( وَأَنْزَلْنَا الْحَدِيدَ ) (1) ، وكما قيل في قوله سبحانه : ( اهْبِطُوا ) (2) ، ( أُولئِكَ ) الذين آمنوا بهذا النبي ( هُمُ الْمُفْلِحُونَ ) الفائزون بخير الدنيا والآخرة. [159] وقبل أن يرجع السياق إلى تتميم قصة موسى عليه‌السلام ، تتميما لما سبق من وصف النبي صلى‌الله‌عليه‌وآله‌وسلم ، فيخاطبه سبحانه بقوله : ( قُلْ ) يا رسول الله للناس : ( يا أَيُّهَا النَّاسُ إِنِّي رَسُولُ اللهِ إِلَيْكُمْ جَمِيعاً ) أرسلني إليكم لأدعوكم إلى الله ( الَّذِي لَهُ مُلْكُ السَّماواتِ وَالْأَرْضِ ) فهو المالك لهما ( 1) الحديد : 26. ( 2) البقرة : 37. لا إِلَهَ إِلاَّ هُوَ يُحْيِي وَيُمِيتُ فَآمِنُواْ بِاللّهِ وَرَسُولِهِ النَّبِيِّ الأُمِّيِّ الَّذِي يُؤْمِنُ بِاللّهِ وَكَلِمَاتِهِ وَاتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ (158) وَمِن قَوْمِ مُوسَى أُمَّةٌ يَهْدُونَ بِالْحَقِّ وَبِهِ يَعْدِلُونَ (159) المتصرف فيهما ( لا إِلهَ إِلَّا هُوَ ) فلا شريك له ( يُحيِي وَيُمِيتُ ) فالجماد يجعله حيا نباتا أو إنسانا أو حيوانا ، والأحياء يميتهم ، ولعل ذكر هذه الصفات لرد النصارى واليهود الذين جعلوا لله شريكا وولدا ، ولرد المشركين الذين كانوا ينسبون الإحياء والإماتة إلى الأصنام ( فَآمِنُوا ) أيها الناس ( بِاللهِ ) إيمانا صحيحا ( وَرَسُولِهِ ) محمد صلى‌الله‌عليه‌وآله‌وسلم ( النَّبِيِّ الْأُمِّيِ ) وكأنه أتي بهذا الوصف للتناسب مع ما في الكتابين السابقين ( الَّذِي يُؤْمِنُ بِاللهِ وَكَلِماتِهِ ) فإنه آمن أولا ثم أمركم بالإيمان ، لا مثل كثير من الرؤساء الذين هم أنفسهم لا يطبقون المبادئ التي يدعون إليها. ولعل المراد بالكلمات : الكتب السابقة والقرآن الكريم ( وَاتَّبِعُوهُ ) فيما يأمركم وينهاكم ( لَعَلَّكُمْ تَهْتَدُونَ ) أي لتكونوا مهديين ، فإن الفعل قد ينسلخ من معناه الزمني ليدل على أصل المعنى المادي ، أو المراد تهتدون إلى الجنة والرضوان ، حتى يصح تعقّب الاهتداء لما تقدم. [160] وحيث فرغ السياق عن الفذلكة المرتبطة بذكر النبي محمد صلى‌الله‌عليه‌وآله‌وسلم رجع إلى قصة موسى عليه‌السلام وقومه ، ولمّا أن وصف سبحانه قوم موسى عليه‌السلام بالكفر وعبادة العجل وغير ذلك ، ذكر أن منهم من بقوا على الإيمان والطاعة ( وَمِنْ قَوْمِ مُوسى أُمَّةٌ ) أي جماعة ( يَهْدُونَ بِالْحَقِ ) أي يدعون إلى الحق ويرشدون إليه ( وَبِهِ ) أي بالحق ( يَعْدِلُونَ ) أي يحكمون وَقَطَّعْناهُمُ اثْنَتَيْ عَشْرَةَ أَسْباطاً أُمَماً وَأَوْحَيْنا إِلى مُوسى إِذِ اسْتَسْقاهُ قَوْمُهُ أَنِ اضْرِبْ بِعَصاكَ الْحَجَرَ بالحق ويعدلون في حكمهم. وهذا واضح ، فإن كل أمة انحرفت لا بد وأن يبقى فيها أناس معتدلون ، وكذلك كان قوم موسى عليه‌السلام في زمانه وبعده إلى زمان الرسول صلى‌الله‌عليه‌وآله‌وسلم ، فكانوا إذا رأوا عيسى نبيا آمنوا به ، وإذا رأوا الرسول مبعوثا صدقوه واتبعوه ، لكن الكثرة الساحقة منهم لمّا كانت منحرفة ، كانت « عمومات الخطاب القرآني » تنصب عليهم ، فإن البلغاء غالبا يتكلمون حول الأمور بمراعاة الغالب ، فيقال : « أهل مدينة كذا حسان الوجوه ، أو قباح ، أو كرماء ، أو بخلاء أو جبناء ، أو ما أشبه » وهم يريدون الكثرة الغالبة ، لا الجميع.` },
            { text: "قُلْ يَٰٓأَيُّهَا ٱلنَّاسُ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُمْ جَمِيعًا ٱلَّذِى لَهُۥ مُلْكُ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَآ إِلَٰهَ إِلَّا هُوَ يُحْىِۦ وَيُمِيتُ فَـَٔامِنُوا۟ بِٱللَّهِ وَرَسُولِهِ ٱلنَّبِىِّ ٱلْأُمِّىِّ ٱلَّذِى يُؤْمِنُ بِٱللَّهِ وَكَلِمَٰتِهِۦ وَٱتَّبِعُوهُ لَعَلَّكُمْ تَهْتَدُونَ", tafsir: `` },
            { text: "وَمِن قَوْمِ مُوسَىٰٓ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ", tafsir: `` },
            { text: "وَقَطَّعْنَٰهُمُ ٱثْنَتَىْ عَشْرَةَ أَسْبَاطًا أُمَمًا وَأَوْحَيْنَآ إِلَىٰ مُوسَىٰٓ إِذِ ٱسْتَسْقَىٰهُ قَوْمُهُۥٓ أَنِ ٱضْرِب بِّعَصَاكَ ٱلْحَجَرَ فَٱنۢبَجَسَتْ مِنْهُ ٱثْنَتَا عَشْرَةَ عَيْنًا قَدْ عَلِمَ كُلُّ أُنَاسٍ مَّشْرَبَهُمْ وَظَلَّلْنَا عَلَيْهِمُ ٱلْغَمَٰمَ وَأَنزَلْنَا عَلَيْهِمُ ٱلْمَنَّ وَٱلسَّلْوَىٰ كُلُوا۟ مِن طَيِّبَٰتِ مَا رَزَقْنَٰكُمْ وَمَا ظَلَمُونَا وَلَٰكِن كَانُوٓا۟ أَنفُسَهُمْ يَظْلِمُونَ", tafsir: `أي فرّقنا بني إسرائيل تفريقا قبيليا ( اثْنَتَيْ عَشْرَةَ أَسْباطاً ) كل فرقة منهم قبيلة تنتهي إلى سبط من أسباط يعقوب عليه‌السلام فقد كان له اثني عشر ولدا ، كل ولد ولّد قبيلة ( أُمَماً ) بيان لاثنتي عشرة أسباطا ، فكل جماعة منهم أمة. وهذا من نعم الله سبحانه على بني إسرائيل لأن القبائل المتعددة تمشي أمورها بيسر بخلاف ما لو كان الجميع قبيلة واحدة ، فإن الرؤساء إذا تعددوا تنافسوا في المكارم ، وسهل مراجعة المرؤوسين إليهم ، كما قال سبحانه : ( وَجَعَلْناكُمْ شُعُوباً وَقَبائِلَ لِتَعارَفُوا ) (1) . ( وَأَوْحَيْنا إِلى مُوسى إِذِ اسْتَسْقاهُ قَوْمُهُ ) أي طلبوا منه السقيا ، وأن يسقيهم ماء ، وذلك حينما كانوا في التيه ( أَنِ اضْرِبْ بِعَصاكَ الْحَجَرَ ) وهو حجر كان معه فإذا أرادوا الماء وضعوه ، وضربه موسى ( 1) الحجرات : 14. فَانْبَجَسَتْ مِنْهُ اثْنَتا عَشْرَةَ عَيْناً قَدْ عَلِمَ كُلُّ أُناسٍ مَشْرَبَهُمْ وَظَلَّلْنا عَلَيْهِمُ الْغَمامَ وَأَنْزَلْنا عَلَيْهِمُ الْمَنَّ وَالسَّلْوى كُلُوا مِنْ طَيِّباتِ ما رَزَقْناكُمْ وَما ظَلَمُونا وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ (160) وَإِذْ قِيلَ لَهُمُ اسْكُنُوا هذِهِ الْقَرْيَةَ وَكُلُوا مِنْها حَيْثُ شِئْتُمْ بعصاه التي كانت تنقلب ثعبانا متى ما أراد ( فَانْبَجَسَتْ ) أي انفجرت. ولعل الفرق بينهما أن الانبجاس خروج الماء بقلّة ، والانفجار خروجه بكثرة. وفي بعض التفاسير : إن الماء كان يخرج من الحجر أولا بقلّة ثم بكثرة. ( مِنْهُ ) أي من الحجر ( اثْنَتا عَشْرَةَ عَيْناً ) لكل سبط عين ، حتى لا يزاحم بعضهم بعضا في الشرب ( قَدْ عَلِمَ كُلُّ أُناسٍ ) من الأسباط ( مَشْرَبَهُمْ ) أي محل شربهم وأخذ الماء منه ( وَظَلَّلْنا عَلَيْهِمُ الْغَمامَ ) حيث كان يؤذيهم حرّ الشمس فتأتي سحابة تظللهم ليستريحوا تحت ظلها ( وَأَنْزَلْنا عَلَيْهِمُ الْمَنَ ) هو شيء حلو كالسكر ( وَالسَّلْوى ) هو الطير السماني ـ كما تقدم ذلك في سورة البقرة ـ ( كُلُوا ) يا بني إسرائيل ( مِنْ طَيِّباتِ ما رَزَقْناكُمْ ) واتركوا خبائثه ( وَما ظَلَمُونا ) إذ كفروا وعصوا ، فإن الله لا يضره كفر الكافر وعصيان العاصي ( وَلكِنْ كانُوا أَنْفُسَهُمْ يَظْلِمُونَ ) حيث حرموها من خير الدنيا وسعادة الآخرة.` },
            { text: "وَإِذْ قِيلَ لَهُمُ ٱسْكُنُوا۟ هَٰذِهِ ٱلْقَرْيَةَ وَكُلُوا۟ مِنْهَا حَيْثُ شِئْتُمْ وَقُولُوا۟ حِطَّةٌ وَٱدْخُلُوا۟ ٱلْبَابَ سُجَّدًا نَّغْفِرْ لَكُمْ خَطِيٓـَٰٔتِكُمْ سَنَزِيدُ ٱلْمُحْسِنِينَ", tafsir: `اذكر يا رسول الله ( إِذْ قِيلَ لَهُمُ ) أي لبني إسرائيل ، والقائل هو الله سبحانه على لسان نبيه موسى عليه‌السلام : ( اسْكُنُوا هذِهِ الْقَرْيَةَ ) بيت المقدس أو أريحا ( وَكُلُوا مِنْها حَيْثُ شِئْتُمْ ) من أنواع المآكل ومختلف وَقُولُوا حِطَّةٌ وَادْخُلُوا الْبابَ سُجَّداً نَغْفِرْ لَكُمْ خَطِيئاتِكُمْ سَنَزِيدُ الْمُحْسِنِينَ (161) فَبَدَّلَ الَّذِينَ ظَلَمُوا مِنْهُمْ قَوْلاً غَيْرَ الَّذِي قِيلَ لَهُمْ فَأَرْسَلْنا عَلَيْهِمْ رِجْزاً مِنَ السَّماءِ بِما كانُوا يَظْلِمُونَ (162) وَسْئَلْهُمْ عَنِ الْقَرْيَةِ ال َّتِي كانَتْ حاضِرَةَ الْبَحْرِ المزارع والمواضع ( وَقُولُوا حِطَّةٌ ) إذ نطلب من الله سبحانه حطّ ذنوبنا ( وَادْخُلُوا الْبابَ ) أي باب القرية ( سُجَّداً ) جمع « ساجد » ، أي : في حال السجود ، بمعنى أنه إذا وصلتم إلى الباب اسجدوا وادخلوا ( نَغْفِرْ لَكُمْ خَطِيئاتِكُمْ ) متعلق بقوله : « قولوا حطة » أي إن قلتم وسجدتم نغفر لكم و ( سَنَزِيدُ الْمُحْسِنِينَ ) على غفران الخطايا بالتفضّل والتكرّم. وبين سياق هذه الآية ، وما تقدم في سورة البقرة خلاف جزئي ، وذلك من فنون البلاغة ، وأوجه الإعجاز.` },
            { text: "فَبَدَّلَ ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ قَوْلًا غَيْرَ ٱلَّذِى قِيلَ لَهُمْ فَأَرْسَلْنَا عَلَيْهِمْ رِجْزًا مِّنَ ٱلسَّمَآءِ بِمَا كَانُوا۟ يَظْلِمُونَ", tafsir: `أي غيّر العاصون الذين لم يدخل الإيمان قلوبهم ( قَوْلاً غَيْرَ الَّذِي قِيلَ لَهُمْ ) فبدلا من أن يقولوا : « حطة » قالوا : « حنطة حمراء خير لنا » ( فَأَرْسَلْنا عَلَيْهِمْ رِجْزاً ) أي عذابا ( مِنَ السَّماءِ ) من جهة العلو ( بِما كانُوا يَظْلِمُونَ ) أي بسبب ظلمهم.` },
            { text: "وَسْـَٔلْهُمْ عَنِ ٱلْقَرْيَةِ ٱلَّتِى كَانَتْ حَاضِرَةَ ٱلْبَحْرِ إِذْ يَعْدُونَ فِى ٱلسَّبْتِ إِذْ تَأْتِيهِمْ حِيتَانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعًا وَيَوْمَ لَا يَسْبِتُونَ لَا تَأْتِيهِمْ كَذَٰلِكَ نَبْلُوهُم بِمَا كَانُوا۟ يَفْسُقُونَ", tafsir: `أي اسأل يا رسول الله اليهود ، لأجل تذكيرهم بما كانوا يفعلون من المعصية فابتلوا بعذاب الله ، حتى لا يتكرّر منهم ذلك ( عَنِ الْقَرْيَةِ الَّتِي كانَتْ حاضِرَةَ الْبَحْرِ ) أي مجاورة للبحر وقريبة منه ، من « حضر » ضد « غاب » . وقد ذكر بعض المفسرين أنها كانت « إيلة » . إِذْ يَعْدُونَ فِي السَّبْتِ إِذْ تَأْتِيهِمْ حِيتانُهُمْ يَوْمَ سَبْتِهِمْ شُرَّعاً وَيَوْمَ لا يَسْبِتُونَ لا تَأْتِيهِمْ كَذلِكَ نَبْلُوهُمْ ( إِذْ يَعْدُونَ ) من التعدّي أي يتجاوزون حدود الله ( فِي ) أمر يوم ( السَّبْتِ ) فقد حرّم عليهم صيد الأسماك في هذا اليوم ـ اختبارا ـ وحلّل عليهم في سائر الأيام ، وقد كانوا يتوصلون إلى حيلة ليحلوا بها ما حرم الله ، فحفروا أخاديد تؤدي إلى حياض يتهيأ للحيتان الدخول فيها من تلك الأخاديد ولا يتهيأ لها الخروج ، فإذا كان يوم السبت جاءت الحيتان جارية على أمان لها فدخلت الأخاديد وأصبحت في الحياض والغدران ، فلما كانت عشية اليوم همّت بالرجوع منها إلى اللجج لتأمن من صائدها ، فلم تقدر فبقيت ليلها في مكان يتهيأ أخذها بلا اصطياد ، وكانوا يأخذونها يوم الأحد ويقولون ما اصطدنا في السبت إنما اصطدنا في الأحد ، ولكن كانوا كاذبين في ذلك ، فإنهم قد أخذوها يوم السبت وإنما القبض كان يوم الأحد ( إِذْ تَأْتِيهِمْ حِيتانُهُمْ ) جمع « حوت » ، والعرب تسمي السمك حوتا ونونا ( يَوْمَ سَبْتِهِمْ شُرَّعاً ) أي ظاهرة على وجه الماء ، من « الشرّع » بمعنى الظهور ، جمع « شارع » ، ك « كتّب جمع كاتب » ، وإنما كانت تأتي في هذا اليوم لما علمت من كونها آمنة لا تؤخذ ، ولما كان من عادة الحيوان أن يألف محل الأمان ( وَيَوْمَ لا يَسْبِتُونَ ) أي لا يكون السبت ، والتعبير بذلك ، لأنهم كانوا يعتدون في السبت ( لا تَأْتِيهِمْ ) لما عرفت من عدم أمنها ، ولعل الأمر كان خارقا للامتحان ، أو لعلة أخرى لا نعرفها ( كَذلِكَ ) أي بمثل ذلك الاختبار الشديد ( نَبْلُوهُمْ ) أي نختبرهم بِما كانُوا يَفْسُقُونَ (163) وَإِذْ قالَتْ أُمَّةٌ مِنْهُمْ لِمَ تَعِظُونَ قَوْماً اللهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذاباً شَدِيداً قالُوا مَعْذِرَةً إِلى رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ (164) فَلَمَّا نَسُوا ما ذُكِّرُوا بِهِ أَنْجَيْنَا الَّذِينَ يَنْهَوْنَ عَنِ السُّوءِ ( بِما كانُوا يَفْسُقُونَ ) أي بسبب فسقهم وعصيانهم ، فإنه إنما حرّم عليهم الاصطياد في السبت ، أو إنما كان تظهر يوم السبت دون غيره ، بسبب فسقهم ليشتد الامتحان عليهم. [165] وقد انقسم بنو إسرائيل أمام هذا العمل إلى ثلاثة فرق أحدها : الصائدة ، الثانية : الساكتة ، الثالثة : الناهية عن ذلك ( وَإِذْ قالَتْ أُمَّةٌ ) أي جماعة ( مِنْهُمْ ) أي من بني إسرائيل ، وهي الساكتة ، قالوا للفرقة الثالثة الناهية عن المنكر : ( لِمَ تَعِظُونَ قَوْماً اللهُ مُهْلِكُهُمْ ) أي أية فائدة في وعظكم ، فإن هؤلاء لا يرتدعون حتى يعذبهم الله ( أَوْ مُعَذِّبُهُمْ عَذاباً شَدِيداً ) دون الهلاك ( قالُوا ) أي قال الواعظون في جواب المعترضين : ( مَعْذِرَةً إِلى رَبِّكُمْ ) أي أن موعظتنا لأجل أن يكون لنا عذر عند الله سبحانه ، فنقول له يوم القيامة : « يا رب إنا نهيناهم فلم ينتهوا » ، حتى لا يقول لنا سبحانه : لماذا لم تنهوا عن المنكر ؟ ( وَلَعَلَّهُمْ ) بالوعظ ( يَتَّقُونَ ) ويرجعون عن غيّهم وعملهم المحرم ، فإن الإنسان لا يدري من يبقى إلى الأخير في عصيانه ومن يرجع عن طغيانه.` },
            { text: "وَإِذْ قَالَتْ أُمَّةٌ مِّنْهُمْ لِمَ تَعِظُونَ قَوْمًا ٱللَّهُ مُهْلِكُهُمْ أَوْ مُعَذِّبُهُمْ عَذَابًا شَدِيدًا قَالُوا۟ مَعْذِرَةً إِلَىٰ رَبِّكُمْ وَلَعَلَّهُمْ يَتَّقُونَ", tafsir: `` },
            { text: "فَلَمَّا نَسُوا۟ مَا ذُكِّرُوا۟ بِهِۦٓ أَنجَيْنَا ٱلَّذِينَ يَنْهَوْنَ عَنِ ٱلسُّوٓءِ وَأَخَذْنَا ٱلَّذِينَ ظَلَمُوا۟ بِعَذَابٍۭ بَـِٔيسٍۭ بِمَا كَانُوا۟ يَفْسُقُونَ", tafsir: `أي نسي العاصون ( ما ذُكِّرُوا بِهِ ) ما ذكّرهم به الواعظون ، بأن فعلوا فعل الناسي ، فلم يبالوا بالنهي ، بل استمروا على عادتهم في الاصطياد يوم السبت بتلك الحيلة ( أَنْجَيْنَا الَّذِينَ يَنْهَوْنَ عَنِ السُّوءِ ) وَأَخَذْنَا الَّذِينَ ظَلَمُوا بِعَذابٍ بَئِيسٍ بِما كانُوا يَفْسُقُونَ (165) فَلَمَّا عَتَوْا عَنْ ما نُهُوا عَنْهُ قُلْنا لَهُمْ كُونُوا قِرَدَةً خاسِئِينَ (166) وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلى يَوْمِ وهم الواعظون ( وَأَخَذْنَا الَّذِينَ ظَلَمُوا ) وهم الصائدون والساكتون ، فإن السكوت عن المنكر ظلم يرجع إلى الإنسان وباله ( بِعَذابٍ بَئِيسٍ ) هو « فعيل » من « بئس » ، بمعنى الشديد البأس ، أي : بعذاب شديد ( بِما كانُوا يَفْسُقُونَ ) أي بسبب فسقهم.` },
            { text: "فَلَمَّا عَتَوْا۟ عَن مَّا نُهُوا۟ عَنْهُ قُلْنَا لَهُمْ كُونُوا۟ قِرَدَةً خَٰسِـِٔينَ", tafsir: `رأينا أنه لم يفدهم الوعظ ولا العذاب الشديد الذي عذبناهم به ـ لعلهم يرجعون عن غيهم ـ و ( عَتَوْا ) أي تكبّروا ( عَنْ ما نُهُوا عَنْهُ ) أي عن قبول الوعظ ( قُلْنا ) والمراد بالقول هنا التكوين : ( لَهُمْ كُونُوا قِرَدَةً خاسِئِينَ ) أي مسخناهم قرودا ، ومعنى « خسأ » ابتعد عن الخير. ورد أن الواعظين خرجوا من المدينة مخافة أن يصيبهم البلاء ، فنزلوا قريبا منها ، فلما أصبحوا غدوا لينظروا ما حال أهل المعصية ، فأتوا باب المدينة فإذا هو مصمت ، فدقوه فلم يجابوا ولم يسمعوا منها حس لأحد ، فوضعوا سلما على سور المدينة ثم أصعدوا رجلا منهم فأشرف على المدينة فنظر فإذا هو بالقوم قردة يتعاوون ، لها أذناب ، فكسروا الباب ودخلوا المدينة ، قال الراوي : فعرفت القردة أنسابها من الإنس ، ولم يعرف الإنس أنسابهم من القردة فقال القوم للقردة : ألم ننهكم ؟` },
            { text: "وَإِذْ تَأَذَّنَ رَبُّكَ لَيَبْعَثَنَّ عَلَيْهِمْ إِلَىٰ يَوْمِ ٱلْقِيَٰمَةِ مَن يَسُومُهُمْ سُوٓءَ ٱلْعَذَابِ إِنَّ رَبَّكَ لَسَرِيعُ ٱلْعِقَابِ وَإِنَّهُۥ لَغَفُورٌ رَّحِيمٌ", tafsir: `اذكر يا رسول الله ( إِذْ تَأَذَّنَ رَبُّكَ ) أي أعلم ربك ، فإن « تأذن وأذن » بمعنى واحد ( لَيَبْعَثَنَّ عَلَيْهِمْ ) أي يرسلن على اليهود ( إِلى يَوْمِ الْقِيامَةِ مَنْ يَسُومُهُمْ سُوءَ الْعَذابِ إِنَّ رَبَّكَ لَسَرِيعُ الْعِقابِ وَإِنَّهُ لَغَفُورٌ رَحِيمٌ (167) وَقَطَّعْناهُمْ فِي الْأَرْضِ أُمَماً مِنْهُمُ الصَّالِحُونَ وَمِنْهُمْ دُونَ ذلِكَ وَبَلَوْناهُمْ بِالْحَسَناتِ الْقِيامَةِ مَنْ يَسُومُهُمْ سُوءَ الْعَذابِ ) أي من يذيقهم العذاب الشديد. وقد دل التاريخ على أن اليهود كانوا أذلاء مضطهدين ، وما تاريخ « هتلر » منّا ببعيد ، وما يرى أحيانا من دولتهم فهي مليئة بالقلق والرعب حتى تأتيهم القاضية. ثم أن إرساله سبحانه العذاب إنما هو بسبب عمل كل جيل جيل ، لا لأعمال آبائهم ( إِنَّ رَبَّكَ ) يا رسول الله ( لَسَرِيعُ الْعِقابِ ) فإن العقاب اللاحق سريع وإن أمهل الله الظالم أياما. روي أنه سئل الإمام أمير المؤمنين عليه‌السلام عن القريب والأقرب ؟ فقال : « كل آت قريب والموت أقرب » ولعله يريد عليه‌السلام أن « الآتي » يحتمل فوته ، بخلاف الموت. ( وَإِنَّهُ لَغَفُورٌ رَحِيمٌ ) فلا يأس للعاصي أنه إذا تاب وعمل صالحا غفر الله له ما أذنب ورحمه.` },
            { text: "وَقَطَّعْنَٰهُمْ فِى ٱلْأَرْضِ أُمَمًا مِّنْهُمُ ٱلصَّٰلِحُونَ وَمِنْهُمْ دُونَ ذَٰلِكَ وَبَلَوْنَٰهُم بِٱلْحَسَنَٰتِ وَٱلسَّيِّـَٔاتِ لَعَلَّهُمْ يَرْجِعُونَ", tafsir: `أي فرّقنا اليهود في البلاد فرقا مختلفة ( فِي الْأَرْضِ أُمَماً ) في كلّ مكان واتجاه ، وذلك إذلالا لهم ، فإن الاجتماع والوحدة يوجبان العزة والسعادة ( مِنْهُمُ الصَّالِحُونَ ) هم الذين إذا رأوا الحق آمنوا به كعبد الله بن أبي وغيره ( وَمِنْهُمْ دُونَ ذلِكَ ) أي دون الصلاح يعني المفسدون ( وَبَلَوْناهُمْ ) أي اختبرناهم ( بِالْحَسَناتِ ) تارة وَالسَّيِّئاتِ لَعَلَّهُمْ يَرْجِعُونَ (168) فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ وَرِثُوا الْكِتابَ يَأْخُذُونَ عَرَضَ هذَا الْأَدْنى وَيَقُولُونَ سَيُغْفَرُ لَنا وَإِنْ يَأْتِهِمْ عَرَضٌ مِثْلُهُ يَأْخُذُوهُ أَ لَمْ يُؤْخَذْ عَلَيْهِمْ مِيثاقُ الْكِتابِ أَنْ لا يَقُولُوا عَلَى اللهِ إِلاَّ الْحَقَّ ( وَالسَّيِّئاتِ ) أخرى ، أي بالنعم والنقم ( لَعَلَّهُمْ يَرْجِعُونَ ) أي لكي يرجعوا ، فإذا جاءتهم الحسنات شكروا ، وإذا أتتهم السيئات استغفروا ، فإن كلّا من النعمة والبلاء ، رحمة من جهة التذكير والإيقاظ. [170] أولئك اليهود الذين كان منهم الصالحون ومنهم دون ذلك ، ذهبوا وماتوا ( فَخَلَفَ مِنْ بَعْدِهِمْ خَلْفٌ ) قام مقامهم ( وَرِثُوا الْكِتابَ ) يعني التوراة ، و « الميراث » هو ما صار للخلف من السلف ، لكن هؤلاء غير صالحين ـ إن وجد فيهم صالح فهو نادر ـ ( يَأْخُذُونَ عَرَضَ هذَا الْأَدْنى ) أي ما وجدوه من الدنيا أخذوه بلا مراعاة للشريعة ، وسمي « عرضا » لأن الدنيا فانية فما فيها عارض زائل ، وسمي « أدنى » لأنه أقرب إلى الإنسان من الآخرة ( وَ ) إذا قيل لهم بأن فيه الإثم ( يَقُولُونَ سَيُغْفَرُ لَنا ) ونتوب بعد ذلك ( وَ ) هم لا يستغفرون ولا يتوبون ، بل يصرّون على تعاطي الحرام بدليل أنهم ( إِنْ يَأْتِهِمْ ) بعد ذلك ( عَرَضٌ مِثْلُهُ يَأْخُذُوهُ ) أيضا. ثم ينكر الله عليهم ذلك بقوله : ( أَ لَمْ يُؤْخَذْ عَلَيْهِمْ ) ولم يقل « منهم » ، لإفادة أن الأخذ كان بإكراههم ( مِيثاقُ الْكِتابِ ) أي العهد الموجود في كتاب التوراة ( أَنْ لا يَقُولُوا عَلَى اللهِ إِلَّا الْحَقَ ) فلا يحرّموا حلاله ولا يحلّلوا حرامه ، فكيف يأخذون الرشوة وسائر وَدَرَسُوا ما فِيهِ وَالدَّارُ الْآخِرَةُ خَيْرٌ لِلَّذِينَ يَتَّقُونَ أَ فَلا تَعْقِلُونَ (169) وَالَّذِينَ يُمَسِّكُونَ بِالْكِتابِ وَأَقامُوا الصَّلاةَ إِنَّا لا نُضِيعُ أَجْرَ الْمُصْلِحِينَ (170) وَإِذْ نَتَقْنَا الْجَبَلَ فَوْقَهُمْ كَأَنَّهُ ظُلَّةٌ وَظَنُّوا المحرمات ويقولون أنها محللة عليهم ؟ ( وَدَرَسُوا ما فِيهِ ) أي قرءوا ما في الكتاب فهم عالمون بذلك ، ولا مجال لهم أن يقولوا : ما كنا عالمين بالميثاق ( وَالدَّارُ الْآخِرَةُ خَيْرٌ لِلَّذِينَ يَتَّقُونَ ) أي أن الثواب الذي وعده الله خير من عرض هذه الدنيا الفانية ، وهي وإن كانت خيرا لمطلق الناس إلّا أن تخصيص « المتقين » بلحاظ انتفاعهم به فقط دونه غيرهم ( أَ فَلا تَعْقِلُونَ ) أيها اليهود أن الأمر على ما أخبرنا به والاستفهام للإنكار.` },
            { text: "فَخَلَفَ مِنۢ بَعْدِهِمْ خَلْفٌ وَرِثُوا۟ ٱلْكِتَٰبَ يَأْخُذُونَ عَرَضَ هَٰذَا ٱلْأَدْنَىٰ وَيَقُولُونَ سَيُغْفَرُ لَنَا وَإِن يَأْتِهِمْ عَرَضٌ مِّثْلُهُۥ يَأْخُذُوهُ أَلَمْ يُؤْخَذْ عَلَيْهِم مِّيثَٰقُ ٱلْكِتَٰبِ أَن لَّا يَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ وَدَرَسُوا۟ مَا فِيهِ وَٱلدَّارُ ٱلْـَٔاخِرَةُ خَيْرٌ لِّلَّذِينَ يَتَّقُونَ أَفَلَا تَعْقِلُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ يُمَسِّكُونَ بِٱلْكِتَٰبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ إِنَّا لَا نُضِيعُ أَجْرَ ٱلْمُصْلِحِينَ", tafsir: `أي يتمسكون ( بِالْكِتابِ ) بأن عملوا بما فيه من الميثاق والأحكام ( وَأَقامُوا الصَّلاةَ ) وتخصيصها بالذكر لأنها تنهى عن الفحشاء إذا أتي بها على وجهها ، فكأنها جعلت علما لسائر الأعمال ( إِنَّا ) إلى آخر الجملة ، خبر « والذين » ( لا نُضِيعُ أَجْرَ الْمُصْلِحِينَ ) الذين يصلحون أنفسهم ويقومون بما يجب عليهم ، فنثيبهم بما عملوا وأصلحوا.` },
            { text: "وَإِذْ نَتَقْنَا ٱلْجَبَلَ فَوْقَهُمْ كَأَنَّهُۥ ظُلَّةٌ وَظَنُّوٓا۟ أَنَّهُۥ وَاقِعٌۢ بِهِمْ خُذُوا۟ مَآ ءَاتَيْنَٰكُم بِقُوَّةٍ وَٱذْكُرُوا۟ مَا فِيهِ لَعَلَّكُمْ تَتَّقُونَ", tafsir: `اذكر يا رسول الله ( إِذْ نَتَقْنَا ) « النتق » قلع الشيء من الأصل ( الْجَبَلَ ) أي قلعناه ، وجعلناه ( فَوْقَهُمْ ) أي فوق بني إسرائيل ( كَأَنَّهُ ) أي كأن الجبل ( ظُلَّةٌ ) أي غمامة ، أو سقيفة ذات ظلّ. وقد كان الجبل كبيرا حتى أن في بعض التفاسير أنه كان فرسخا في فرسخ ( وَظَنُّوا ) أَنَّهُ واقِعٌ بِهِمْ خُذُوا ما آتَيْناكُمْ بِقُوَّةٍ وَاذْكُرُوا ما فِيهِ لَعَلَّكُمْ تَتَّقُونَ (171) بأن رجح في نفوسهم ( أَنَّهُ واقِعٌ بِهِمْ ) أي واقع عليهم ، ولعل الإتيان ب « الباء » لإفادة أن وقوعه عليهم يسبب وقوعهم أيضا ، وحينما رفع الجبل فوقهم قيل لهم : ( خُذُوا ما آتَيْناكُمْ ) من الأحكام ( بِقُوَّةٍ ) أي بشدة وجهد واجتهاد. وذلك أن موسى عليه‌السلام لما جاءهم بالتوراة لم يقبلوها فقطع جبرئيل عليه‌السلام قطعة من جبل الطور ورفعها فوق رؤوسهم ، مهددا أنهم إن لم يقبلوا ألقاها عليهم حتى يهلكوا عن آخرهم ، ولما رأوا ذلك خافوا وقبلوا بكل كره وإجبار ( وَاذْكُرُوا ما فِيهِ ) أي من العهود والمواثيق ( لَعَلَّكُمْ تَتَّقُونَ ) أي لكي يحصل منكم التقوى ، أو لكي تخافوا عقاب الله ، فتتجنبوا المعاصي ، فإن من بنى على العمل بالكتاب يشع في نفسه جوّ من الرهبة يبعثه على التقوى. [173] وحين انتهت قصص موسى عليه‌السلام مع قومه يبدأ السياق ليفتح قصصا جديدة حول التوحيد ، وإذ انتهى من الكلام السابق حول أخذ الله الميثاق من بني إسرائيل ، تأتي هنا قصة أخذ الله سبحانه الميثاق من البشر جميعا حول الوحدانية. وفي الآية قولان : الأول : ما روي أنه أخرج الله من ظهر آدم عليه‌السلام ذريته كالذّرّ يوم القيامة فخرجوا مثل الذر فعرّفهم نفسه وأراهم صنعه ، ولو لا ذلك لم يعرف أحد ربه فثبتت المعرفة ونسوا الموقف. الثاني : إن الآية جارية مجرى الكلام العرفي البلاغي على طريقة التمثيل. ومن المعلوم أن القول الأول لا مانع فيه إطلاقا ، فإن الله قادر وَإِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ مِنْ ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلى أَنْفُسِهِمْ أَ لَسْتُ بِرَبِّكُمْ قالُوا بَلى على كل شيء ( وَ ) اذكر يا رسول الله ( إِذْ أَخَذَ رَبُّكَ مِنْ بَنِي آدَمَ ) أي أخرج من بني آدم ( مِنْ ظُهُورِهِمْ ) بدل من « من بني آدم » أي أخرج من أصلاب الرجال ( ذُرِّيَّتَهُمْ ) أولادهم وذراريهم ( وَ ) بعد ما أخرجهم وأكملهم ( أَشْهَدَهُمْ عَلى أَنْفُسِهِمْ ) أي جعلهم شهداء على أنفسهم ، فإن من اعترف بشيء كان شهيدا على نفسه ، قائلا لهم : ( أَ لَسْتُ بِرَبِّكُمْ ) ؟ على نحو الاستفهام التقريري ، وقد كان ذلك بلسان الأنبياء ، كما في كثير من الآيات ، مثل : ( وَقُلْنا مِنْ بَعْدِهِ لِبَنِي إِسْرائِيلَ ) (1) ، والمراد : القول لهم على لسان موسى عليه‌السلام ( قالُوا بَلى ) أنت ربنا. وهذا اعتراف بالفطرة ، فإن الفطرة أذعنت بذلك ، كما قال الرسول صلى‌الله‌عليه‌وآله‌وسلم : « كل مولود يولد على الفطرة إلا أن أبويه هما اللذان يهودانه أو ينصرانه أو يمجسانه » ومن قبيل ذلك ( إِنَّا عَرَضْنَا الْأَمانَةَ عَلَى السَّماواتِ وَالْأَرْضِ وَالْجِبالِ فَأَبَيْنَ أَنْ يَحْمِلْنَها وَأَشْفَقْنَ مِنْها ) (2) ، و ( فَقالَ لَها وَلِلْأَرْضِ ائْتِيا طَوْعاً أَوْ كَرْهاً قالَتا أَتَيْنا طائِعِينَ ) (3) ، و ( إِنَّما قَوْلُنا لِشَيْءٍ إِذا أَرَدْناهُ أَنْ نَقُولَ لَهُ كُنْ فَيَكُونُ ) (4) ، وأشباه ذلك مما هو كثير في القرآن ، وهو نوع من البلاغة ، كقول الشاعر : « أيا جبلي نعمان بالله خليا » ، وقوله : « أيا شجر الخابور ما لك مورقا » وقوله : قال الحبيب وكيف لي بجوابكم و أنا رهين جنادل وتراب ( 1) الإسراء : 105. ( 2) الأحزاب : 73. ( 3) فصلت : 12. ( 4) النحل : 41. شَهِدْنا أَنْ تَقُولُوا يَوْمَ الْقِيامَةِ إِنَّا كُنَّا عَنْ هذا غافِلِينَ (172) فإن الغالب أن يصوغ البليغ الكلام في قالب جذاب لبيان المراد. ( شَهِدْنا ) فالغرض من الآية أن الفطرة تشهد على توحيد الله سبحانه بما أودع فيها من درك الحقيقة وفهم الواقع. وإنما أودعنا في الفطرة هذه الشهادة ل ( أَنْ ) لا ( تَقُولُوا ) أيها البشر ( يَوْمَ الْقِيامَةِ ) حين يعاتب المشرك على شركه ، والجاحد على جحوده : ( إِنَّا كُنَّا عَنْ هذا ) الأمر وهو التوحيد ( غافِلِينَ ) فقد أودعنا فيكم ما يزيل غفلتكم. لا يقال : فعل هذا يلزم صحة العقاب حتى بالنسبة إلى من لم تبلغه الدعوة ؟ لأنه يقال : هو كذلك ، إلّا أن الله سبحانه بلطفه لا يعذب حتى يتمّ الحجة الظاهرة ، كما قال سبحانه : ( وَما كُنَّا مُعَذِّبِينَ حَتَّى نَبْعَثَ رَسُولاً ) (1) ، وهذا التفسير للآية الكريمة إنما هو القول الثاني الذي يأخذ بالظاهر مع غض النظر عن أخبار « عالم الذر » والذي أظن أنه لا مانع من الجمع بين الأمرين ودلالة الآية عليهما ، فإنه لم يدل دليل على امتناع استعمال اللفظ في أكثر من معنى ، بل الذي يظهر في بعض الروايات أن بعض الآيات القرآنية تدل على أكثر من معنيين سواء كان المعنيان من باب المصداق أو لا ، كما أن في الآيات السابقة « إنّا عرضنا .. » يمكن الأمران ، وكان الظاهر اللفظي البلاغي يؤكد كون الألفاظ مسوقة للمعنى العرفي ، لا الخارجي ـ والله أعلم ـ. ( 1) الإسراء : 16. أَوْ تَقُولُوا إِنَّما أَشْرَكَ آباؤُنا مِنْ قَبْلُ وَكُنَّا ذُرِّيَّةً مِنْ بَعْدِهِمْ أَ فَتُهْلِكُنا بِما فَعَلَ الْمُبْطِلُونَ (173) وَكَذلِكَ نُفَصِّلُ الْآياتِ` },
            { text: "وَإِذْ أَخَذَ رَبُّكَ مِنۢ بَنِىٓ ءَادَمَ مِن ظُهُورِهِمْ ذُرِّيَّتَهُمْ وَأَشْهَدَهُمْ عَلَىٰٓ أَنفُسِهِمْ أَلَسْتُ بِرَبِّكُمْ قَالُوا۟ بَلَىٰ شَهِدْنَآ أَن تَقُولُوا۟ يَوْمَ ٱلْقِيَٰمَةِ إِنَّا كُنَّا عَنْ هَٰذَا غَٰفِلِينَ", tafsir: `` },
            { text: "أَوْ تَقُولُوٓا۟ إِنَّمَآ أَشْرَكَ ءَابَآؤُنَا مِن قَبْلُ وَكُنَّا ذُرِّيَّةً مِّنۢ بَعْدِهِمْ أَفَتُهْلِكُنَا بِمَا فَعَلَ ٱلْمُبْطِلُونَ", tafsir: `أي : لئلّا تقولوا : ( إِنَّما أَشْرَكَ آباؤُنا مِنْ قَبْلُ ) شركنا ( وَكُنَّا ذُرِّيَّةً مِنْ بَعْدِهِمْ ) فلم نكن نعرف الحق من الباطل ، فقلدنا آباءنا باعتقاد أنهم أعقل منا وأدرى ، فلا بد وأن يكون شركهم على علم ودراية فلا تقصير لنا ( أَ فَتُهْلِكُنا ) يا رب ( بِما ) لا جرم لنا فيه ، فإنا قد اتّبعنا ما ( فَعَلَ ) آباؤنا ( الْمُبْطِلُونَ ) أي الذين هم على الباطل ؟ فإنا قد جعلنا فيكم هذه الفطرة لتكون حاكمة وشاهدة على بطلان فعل الآباء ، فلا يكون للمشرك عذر يوم القيامة بأنه لم يدر. وهنا سؤال : إن الفطرة سواء جعلت في الإنسان أم لم تجعل ، لم يصح احتجاج المشرك ، إذ لو لا الأنبياء لم يعذب المشرك ، ومع وجود الأنبياء يكون احتجاج الله على المشرك بأنه لم لم يؤمن بالنبي ، لا لم لم يسمع نداء فطرته ؟ فكيف يعلّل العقاب بجعل الفطرة؟ والجواب : إنه تعليل بجزء العلة ، فإنه لو لا الفطرة لم يكن الإنسان عارفا بصحة كلام الأنبياء ، إذ ما لم يدل الباطل على شيء لا يؤخذ الإنسان بما قام عليه الدليل ، ولذا ورد أن لله حجتين : ظاهرة هي الأنبياء ، وباطنة هي العقول. وعليه فالتعليل إنما هو بجزء العلة ، كما يقول القائل : « هيأت لك دارا لتسعد » ، مع العلم أن الدار بعض من علة السعادة لا كلها.` },
            { text: "وَكَذَٰلِكَ نُفَصِّلُ ٱلْـَٔايَٰتِ وَلَعَلَّهُمْ يَرْجِعُونَ", tafsir: `كما بيّنا لكم هذه الآية الدالة على التوحيد ( كَذلِكَ نُفَصِّلُ ) سائر ( الْآياتِ ) والبراهين ونوضحها جلية ، ليعرفها كل أحد وَلَعَلَّهُمْ يَرْجِعُونَ (174) وَاتْلُ عَلَيْهِمْ نَبَأَ الَّذِي آتَيْناهُ آياتِنا فَانْسَلَخَ مِنْها ( وَلَعَلَّهُمْ يَرْجِعُونَ ) أي لكي يرجعوا عن غيّهم إلى الحق والرشاد. والظاهر أن « الواو » في « ولعلهم » عطف على المعنى المستفاد من « نفصّل » أي « ليعرفونها » و « لكي يرجعوا» . [176] إنا جعلنا هذه الفطرة في الإنسان ليكون انحراف المشرك بلا عذر ، ويكون انحراف من انحرف بلا مبرر ، وقد وقع مثل هذا الانحراف في بعض الأفراد وهو « بلعم بن باعورا » فقد أعطي « الاسم الأعظم » الذي يستجاب به الدعاء ، وكان يدعو به فيستجيب الله سبحانه له ، فمال إلى فرعون ، فلما مرّ فرعون في طلب موسى عليه‌السلام وأصحابه ، قال فرعون لبلعم : ادع الله على موسى وأصحابه ليحبسه الله علينا ، فركب بلعم حمارته ليمرّ في طلب موسى ، فامتنعت عليه حمارته ، فأقبل يضربها ، فأنطقها الله عزوجل ، فقالت : ويلك على ماذا تضربني ، أ تريد أن أجيء معك لتدعو على نبي الله وقوم مؤمنين ، فلم يزل يضربها حتى قتلها وانسلخ الاسم الأعظم من لسانه فنسيه. والآية وإن كانت في شأنه إلا أنها عامة لكل من انسلخ من آيات الله لترجيحه هوى نفسه ، كما هو شأن الآيات القرآنية. ( وَاتْلُ ) أي اقرأ يا رسول الله ( عَلَيْهِمْ ) أي على الناس ( نَبَأَ ) أي خبر ( الَّذِي آتَيْناهُ ) أي أعطيناه ( آياتِنا ) أي حججنا ودلائلنا ـ وقد تقدم أن المراد من ذلك الاسم الأعظم ـ ( فَانْسَلَخَ مِنْها ) أي خرج من تلك الآيات ، كالشيء الذي ينسلخ من جلده ، كأن الآيات كانت كالجلد الواقي له عن شرور الدنيا والآخرة فأخرج نفسه منها ، فتعرض فَأَتْبَعَهُ الشَّيْطانُ فَكانَ مِنَ الْغاوِينَ (175) وَلَوْ شِئْنا لَرَفَعْناهُ بِها وَلكِنَّهُ أَخْلَدَ إِلَى الْأَرْضِ وَاتَّبَعَ هَواهُ فَمَثَلُهُ كَمَثَلِ الْكَلْبِ إِنْ تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَثْ للخطر والهلاك ( فَأَتْبَعَهُ الشَّيْطانُ ) أي لمّا خرج عن الوقاية تبعه الشيطان ليضلّه عن طريقه ( فَكانَ مِنَ الْغاوِينَ ) أي الهالكين.` },
            { text: "وَٱتْلُ عَلَيْهِمْ نَبَأَ ٱلَّذِىٓ ءَاتَيْنَٰهُ ءَايَٰتِنَا فَٱنسَلَخَ مِنْهَا فَأَتْبَعَهُ ٱلشَّيْطَٰنُ فَكَانَ مِنَ ٱلْغَاوِينَ", tafsir: `` },
            { text: "وَلَوْ شِئْنَا لَرَفَعْنَٰهُ بِهَا وَلَٰكِنَّهُۥٓ أَخْلَدَ إِلَى ٱلْأَرْضِ وَٱتَّبَعَ هَوَىٰهُ فَمَثَلُهُۥ كَمَثَلِ ٱلْكَلْبِ إِن تَحْمِلْ عَلَيْهِ يَلْهَثْ أَوْ تَتْرُكْهُ يَلْهَث ذَّٰلِكَ مَثَلُ ٱلْقَوْمِ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا فَٱقْصُصِ ٱلْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ", tafsir: `أي اقتضت مشيئتنا أن نجبره على البقاء ( لَرَفَعْناهُ ) أي رفعنا « بلعم » ( بِها ) أي بتلك الآيات ، فلو أردنا أن يبقى بالجبر لأمكننا ذلك ، حتى ترتفع درجته ( وَلكِنَّهُ ) أي « بلعم » والضمير يرجع إلى « الذي آتيناه » كذلك الضمير السابق ( أَخْلَدَ إِلَى الْأَرْضِ ) فركن إلى الدنيا ومال إليها ، كأنه جعلها موضع خلده وإقامته وأعرض عن الدار الآخرة ، أو « أخلد » بمعنى لصق ( وَاتَّبَعَ هَواهُ ) عوض أن يتبع الحق ويسير في طريق الرشد ( فَمَثَلُهُ كَمَثَلِ الْكَلْبِ إِنْ تَحْمِلْ عَلَيْهِ ) من « الحملة » أي إن تطرده ( يَلْهَثْ ) يخرج لسانه من فمه يتنفس ( أَوْ تَتْرُكْهُ يَلْهَثْ ) بأن تركته فلم تتعرض له ، فإن كل حيوان يلهث في حال الإعياء والإكلال بخلاف الكلب فإنه يلهث في حال الراحة والإعياء. والمراد أنه ضال على كل حال سواء عارضته أم لم تعارضه ، بخلاف كثير من الناس الذين يضلون لدى المعارضة وحينما يغضبون أو يرون أن مصالحهم مهددة. إن بلعم أخرج لسانه ليدعو على موسى ـ شبيها بلهث الكلب ـ حينما لم يعارضه موسى عليه‌السلام ولم يهدد مصالحه ، بل كانت أموره أحسن تحت لواء موسى حيث يجمعهما ذلِكَ مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآياتِنا فَاقْصُصِ الْقَصَصَ لَعَلَّهُمْ يَتَفَكَّرُونَ (176) ساءَ مَثَلاً الْقَوْمُ الَّذِينَ كَذَّبُوا بِآياتِنا وَأَنْفُسَهُمْ كانُوا يَظْلِمُونَ (177) مَنْ يَهْدِ اللهُ فَهُوَ الْمُهْتَدِي وَمَنْ يُضْلِلْ فَأُولئِكَ هُمُ الْخاسِرُونَ (178) وَلَقَدْ ذَرَأْنا لِجَهَنَّمَ الدين ، لكنه شبيه بالكلب اللاهث وإن لم تطرده. ( ذلِكَ ) المثال بالكلب ( مَثَلُ الْقَوْمِ الَّذِينَ كَذَّبُوا بِآياتِنا ) فإنهم بصفة الكلب في الإيذاء واللهث وإن لم يتعرض لهم بسوء ( فَاقْصُصِ ) يا رسول الله ( الْقَصَصَ ) أي أخبار الماضين ( لَعَلَّهُمْ يَتَفَكَّرُونَ ) فيرتدعوا عن غيهم ، إذ يعلمون أن مصيرهم كمصير أولئك إلى الهلاك والدمار ، إن عاندوا الحق وعارضوا الدين.` },
            { text: "سَآءَ مَثَلًا ٱلْقَوْمُ ٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا وَأَنفُسَهُمْ كَانُوا۟ يَظْلِمُونَ", tafsir: `أي بئس مثلا مثل ( الْقَوْمُ الَّذِينَ كَذَّبُوا بِآياتِنا ) والمراد : بئس الصفة المضروب لها المثل بصفة المكذبين ، فإن سوء المثل يدل على سوء الممثل له ( وَأَنْفُسَهُمْ كانُوا يَظْلِمُونَ ) أي أنهم بالعصيان ظلموا أنفسهم حيث حرموها من خير الدنيا وسعادة الآخرة.` },
            { text: "مَن يَهْدِ ٱللَّهُ فَهُوَ ٱلْمُهْتَدِى وَمَن يُضْلِلْ فَأُو۟لَٰٓئِكَ هُمُ ٱلْخَٰسِرُونَ", tafsir: `أي : يهديه الله سبحانه ( فَهُوَ الْمُهْتَدِي ) فإن هداية الله هي الهداية الحقة التي تورث خير الدنيا والآخرة ( وَمَنْ يُضْلِلْ ) أي يضله ، بأن يقطع لطفه عنه حيث يراه في سبيل العصيان والفساد ( فَأُولئِكَ هُمُ الْخاسِرُونَ ) الذين خسروا أنفسهم وما ربحوا شيئا.` },
            { text: "وَلَقَدْ ذَرَأْنَا لِجَهَنَّمَ كَثِيرًا مِّنَ ٱلْجِنِّ وَٱلْإِنسِ لَهُمْ قُلُوبٌ لَّا يَفْقَهُونَ بِهَا وَلَهُمْ أَعْيُنٌ لَّا يُبْصِرُونَ بِهَا وَلَهُمْ ءَاذَانٌ لَّا يَسْمَعُونَ بِهَآ أُو۟لَٰٓئِكَ كَٱلْأَنْعَٰمِ بَلْ هُمْ أَضَلُّ أُو۟لَٰٓئِكَ هُمُ ٱلْغَٰفِلُونَ", tafsir: `أي خلقنا وأنشأنا ( لِجَهَنَّمَ ) اللام للعاقبة ، كما في كَثِيراً مِنَ الْجِنِّ وَالْإِنْسِ لَهُمْ قُلُوبٌ لا يَفْقَهُونَ بِها وَلَهُمْ أَعْيُنٌ لا يُبْصِرُونَ بِها وَلَهُمْ آذانٌ لا يَسْمَعُونَ بِها أُولئِكَ كَالْأَنْعامِ بَلْ هُمْ أَضَلُّ قوله تعالى : ( فَالْتَقَطَهُ آلُ فِرْعَوْنَ لِيَكُونَ لَهُمْ عَدُوًّا وَحَزَناً ) (1) ، ( كَثِيراً مِنَ الْجِنِّ وَالْإِنْسِ ) فإنه سبحانه خلقهم ليعبدوه ويدخلوا جنته كما قال : ( وَما خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ ) (2) ، وقال : ( وَما أَرْسَلْنا مِنْ رَسُولٍ إِلَّا لِيُطاعَ بِإِذْنِ اللهِ ) (3) ، لكنهم بسوء أعمالهم أوجبوا لأنفسهم الشقاء ودخول النار. والكلام تعقيب لما تقدم في الآية السابقة من ضرب الأمثال للكفار ، فكأنه قال : « مثلهم ذلك ، ومصيرهم هذا » . ثم إنه يدل على أن مصير « فلان » النار بهذه العلائم ف ( لَهُمْ قُلُوبٌ لا يَفْقَهُونَ بِها ) أي لا يفهمون الحق بسببها ، والمراد عدم إذعانهم للحق ، لأن التارك والجاهل سواء ، فقد قال سبحانه : ( يَعْرِفُونَ نِعْمَتَ اللهِ ثُمَّ يُنْكِرُونَها ) (4) ، ( وَلَهُمْ أَعْيُنٌ لا يُبْصِرُونَ بِها ) الرشد ، وإن رأوا بها الأمور المادية ، فإن التارك للطريق والأعمى سواء ( وَلَهُمْ آذانٌ لا يَسْمَعُونَ بِها ) الوعظ والإنذار سماعا مفيدا ، وإن سمعوا ألفاظهما ، فإن من لا يستجيب للوعظ هو والأصم سواء. ( أُولئِكَ ) الأشخاص ( كَالْأَنْعامِ ) من الإبل والبقر والغنم ، فكما أنها لا تفقه ولا تبصر الرشد ، ولا تسمع إلى الوعظ كذلك هؤلاء ( بَلْ هُمْ أَضَلُ ) من البهائم لأنها تهتدي إلى مصالحها ومفاسدها وتنبعث إذا ( 1) القصص : 9. ( 2) الذاريات : 57. ( 3) النساء : 65. ( 4) النحل : 84. أُولئِكَ هُمُ الْغافِلُونَ (179) وَلِلَّهِ الْأَسْماءُ الْحُسْنى فَادْعُوهُ بِها وَذَرُوا الَّذِينَ يُلْحِدُونَ فِي أَسْمائِهِ سَيُجْزَوْنَ ما كانُوا يَعْمَلُونَ (180) وَمِمَّنْ خَلَقْنا أُمَّةٌ يَهْدُونَ بِالْحَقِّ بعثت وتنزجر إذا زجرت ، بخلاف هؤلاء فإنهم يلقون بأيديهم إلى التهلكة ولا ينصاعون للأوامر والزواجر ( أُولئِكَ ) الضالون ( هُمُ الْغافِلُونَ ) عن الحق والواقع ، فإنهم كالغافل في عدم الانتفاع بالأوامر والنواهي ، وليست الأنعام غافلة ، فهم أسوأ من الأنعام. [181] وحيث ذكر سبحانه مصير الكافرين وأنهم الذين لا يعقلون ولا يهتدون ، بيّن ما يجب أن يكون عليه أهل القلوب الفاقهة من العقلاء فقال : ( وَلِلَّهِ الْأَسْماءُ الْحُسْنى ) أي الحسنة المعنى كالكريم والغفور والجواد والرحيم والعفوّ وغيرها ( فَادْعُوهُ بِها ) أي فادعوا الله بهذه الأسماء بأن يقال : يا كريم يا غفور وهكذا ( وَذَرُوا ) أي اتركوا ( الَّذِينَ يُلْحِدُونَ فِي أَسْمائِهِ ) أي ينحرفون فيها بتسمية أصنامهم بأسمائه سبحانه ، فقد كانوا يقولون لشيء : هذا إله المطر ، وهذا إله النبات ، وهذا إله الأرض .. وهكذا ، فكانوا يجعلون صفاته وأسمائه للأصنام أو الأوهام ، أو المراد : يلحدون بأسمائه كما سموا صنما ب « اللات » مخفف « الله » وصنما ب « العزى » مخفف « عزيز » ، أو المراد : يلحدون بتسمية الله بأسماء لا تليق به كتسميته « أبا » و « زوجا » وما أشبه ذلك. إنهم ( سَيُجْزَوْنَ ما كانُوا يَعْمَلُونَ ) في الدنيا بالشقاء وفي الآخرة بالنار. [182] ثم بيّن سبحانه أن ليس كل الناس منحرفين في الشرك والظلم ( وَمِمَّنْ خَلَقْنا ) من البشر ( أُمَّةٌ يَهْدُونَ ) الناس ( بِالْحَقِ ) ويرشدونهم وَبِهِ يَعْدِلُونَ (181) وَالَّذِينَ كَذَّبُوا بِآياتِنا سَنَسْتَدْرِجُهُمْ مِنْ حَيْثُ لا يَعْلَمُونَ (182) وَأُمْلِي لَهُمْ إِنَّ كَيْدِي مَتِينٌ (183) أَ وَلَمْ يَتَفَكَّرُوا ما بِصاحِبِهِمْ مِنْ جِنَّةٍ إِنْ هُوَ إِلاَّ نَذِيرٌ مُبِينٌ (184) إليه ( وَبِهِ ) أي بالحق ( يَعْدِلُونَ ) أي يحكمون بالعدل لا يزيغون عن الحق ولا يميلون نحو الباطل.` },
            { text: "وَلِلَّهِ ٱلْأَسْمَآءُ ٱلْحُسْنَىٰ فَٱدْعُوهُ بِهَا وَذَرُوا۟ ٱلَّذِينَ يُلْحِدُونَ فِىٓ أَسْمَٰٓئِهِۦ سَيُجْزَوْنَ مَا كَانُوا۟ يَعْمَلُونَ", tafsir: `` },
            { text: "وَمِمَّنْ خَلَقْنَآ أُمَّةٌ يَهْدُونَ بِٱلْحَقِّ وَبِهِۦ يَعْدِلُونَ", tafsir: `` },
            { text: "وَٱلَّذِينَ كَذَّبُوا۟ بِـَٔايَٰتِنَا سَنَسْتَدْرِجُهُم مِّنْ حَيْثُ لَا يَعْلَمُونَ", tafsir: `فلم يؤمنوا ، بل بقوا على عنادهم ، مصرّين على كفرهم ( سَنَسْتَدْرِجُهُمْ ) « الاستدراج » هو تقريب شيء إلى المقصد درجة درجة ، أي أن المكذبين نقرّبهم إلى العذاب والهلاك درجة فدرجة ( مِنْ حَيْثُ لا يَعْلَمُونَ ) أنهم آخذون في القرب من الهلاك ، فإن المؤمن كلما زلت به قدم تذكّر واستغفر وابتعد بنفسه عن الهلكة ، أما المكذب فإنه حيث لا يبالي بما عمل يتقرب إلى الهلاك شيئا فشيئا وهو لا يعلم ذلك.` },
            { text: "وَأُمْلِى لَهُمْ إِنَّ كَيْدِى مَتِينٌ", tafsir: `« الإملاء » التأخير ، أي : أمهلهم ولا أعاجلهم بالعقوبة فإنهم لا يفوتون الله سبحانه ، والإمهال لهم موجب لكثرة عذابهم لازدياد معصيتهم ( إِنَّ كَيْدِي ) « الكيد » هو معالجة الأشياء خفية ، إن عملي للانتقام منهم ( مَتِينٌ ) مستحكم لا يفوته شيء.` },
            { text: "أَوَلَمْ يَتَفَكَّرُوا۟ مَا بِصَاحِبِهِم مِّن جِنَّةٍ إِنْ هُوَ إِلَّا نَذِيرٌ مُّبِينٌ", tafsir: `أي هلّا يتفكر المشركون فيما يقولونه ويرمون به النبي صلى‌الله‌عليه‌وآله‌وسلم من الجنون ، فإنهم كانوا يقولون أنه صلى‌الله‌عليه‌وآله‌وسلم مجنون ( ما بِصاحِبِهِمْ مِنْ جِنَّةٍ ) وكيف يكون مجنونا من يأتي بما يعجز عنه البشر ، وكل أقواله وأعماله في غاية الصحة والدقة ؟! ( إِنْ هُوَ ) أي ما هو ( إِلَّا نَذِيرٌ مُبِينٌ ) أَ وَلَمْ يَنْظُرُوا فِي مَلَكُوتِ السَّماواتِ وَالْأَرْضِ وَما خَلَقَ اللهُ مِنْ شَيْءٍ وَأَنْ عَسى أَنْ يَكُونَ قَدِ اقْتَرَبَ أَجَلُهُمْ فَبِأَيِّ حَدِيثٍ بَعْدَهُ يُؤْمِنُونَ (185) منذر للناس إن عملوا شيئا يعاقبوا عليه ، فواضح كونه منذرا ، وإنما ذكر « الإنذار » فقط لأنه في مقابل المشركين الذين كانوا يعملون السيئات. [186] إنهم كيف لا يؤمنون والكون كله يدل على وجود الله سبحانه ؟ ثم كيف لا يؤمنون ومن الجائز أن يموتوا عاجلا فيبتلوا بالعقاب والعذاب ؟! ( أَ وَلَمْ يَنْظُرُوا ) نظر اعتبار وتعقّل ( فِي مَلَكُوتِ السَّماواتِ وَالْأَرْضِ ) أي آثار الملك ، فإن الأثر يدل على المؤثر حتى يعترفوا بالإله الخالق وبما يليق به من الصفات ( وَ ) أولم يتفكروا وينظروا في ( ما خَلَقَ اللهُ مِنْ شَيْءٍ ) من أصناف خلقه فيعرف أنه خالق الأشياء جميعا ( وَأَنْ عَسى أَنْ يَكُونَ قَدِ اقْتَرَبَ أَجَلُهُمْ ) حتى يعدوا للموت عدّته ويحتاطوا لما بعد الموت حتى لا يندموا ويخسروا ، فإن مجرد احتمال ذلك كاف في أن يرتدع الإنسان ، كما أشار إلى ذلك الإمام علي عليه‌السلام في الأبيات المنسوبة إليه : قال المنجم والطبيب كلاهما لم يحشر الأموات ، قلت : إليكما إن كان قولكما فلست بخاسر أو كان قولي فالخسار عليكما إنهم لم يؤمنوا بالقرآن الكريم الذي تكتنفه كل شواهد الصدق والحق ( فَبِأَيِّ حَدِيثٍ ) ومطلب وخبر ( بَعْدَهُ ) أي بعد القرآن ( يُؤْمِنُونَ ) مَنْ يُضْلِلِ اللهُ فَلا هادِيَ لَهُ وَيَذَرُهُمْ فِي طُغْيانِهِمْ يَعْمَهُونَ (186) يَسْئَلُونَكَ عَنِ السَّاعَةِ أَيَّانَ مُرْساها قُلْ إِنَّما عِلْمُها عِنْدَ رَبِّي لا يُجَلِّيها لِوَقْتِها إِلاَّ هُوَ أو بعد « محمد » صلى‌الله‌عليه‌وآله‌وسلم حيث تقدم قوله « ما بصاحبهم » . وفي الكلام مجاز سواء عاد الضمير إلى القرآن ؛ لأن ليس كل القرآن حديثا وقصة وإنما فيه إنشاء ، أو الرسول صلى‌الله‌عليه‌وآله‌وسلم ؛ لأنه صاحب حديث.` },
            { text: "أَوَلَمْ يَنظُرُوا۟ فِى مَلَكُوتِ ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ وَمَا خَلَقَ ٱللَّهُ مِن شَىْءٍ وَأَنْ عَسَىٰٓ أَن يَكُونَ قَدِ ٱقْتَرَبَ أَجَلُهُمْ فَبِأَىِّ حَدِيثٍۭ بَعْدَهُۥ يُؤْمِنُونَ", tafsir: `` },
            { text: "مَن يُضْلِلِ ٱللَّهُ فَلَا هَادِىَ لَهُۥ وَيَذَرُهُمْ فِى طُغْيَٰنِهِمْ يَعْمَهُونَ", tafsir: `بأن يخلي بينه وبين الضلال ، لما سبق منه من الإعراض عن الحق ( فَلا هادِيَ لَهُ ) إذ الهداية منحصرة بالله سبحانه ، فإذا لم تشع الهداية من قبله فلم يكن للإنسان هاد سواه ( وَيَذَرُهُمْ ) أي يترك هؤلاء المعرضين الذين لا يتفكرون ولا ينظرون إلى الحق ( فِي طُغْيانِهِمْ ) وضلالهم ، كأنهم طغوا عن الحق ( يَعْمَهُونَ ) أي يتحيّرون ، فهم دائما متردّدون بين الحق والباطل ، حيث أن الضمير يناديهم لاتباع الحق ، وشهواتهم تمنعهم. وقد تقدم أن العمى في العين ، والعمه في القلب. [188] ولما تقدم الوعيد بيوم القيامة ، الذي يسمى ب « الساعة » ، سأل جماعة عن وقت القيامة ( يَسْئَلُونَكَ ) يا رسول الله ( عَنِ السَّاعَةِ ) أي القيامة ( أَيَّانَ مُرْساها ) أي متى وقوعها ، من « رسا الشيء يرسو » إذا ثبت. و « المرسى » بمعنى المثبت ، أي متى وقت ثبوتها ؟ ( قُلْ ) يا رسول الله في جوابهم : ( إِنَّما عِلْمُها ) أي علم الساعة ( عِنْدَ رَبِّي ) فهو وحده يعلم وقتها ( لا يُجَلِّيها ) أي لا يكشفها. الظاهر أن المراد : لا يأتي بها ( لِوَقْتِها ) أي حين يكون وقتها ( إِلَّا هُوَ ) تعالى ، فعلمها عنده ، ووقتها عند إرادته ، وإنما لم يكشف الله سبحانه عن وقتها لخلقه ثَقُلَتْ فِي السَّماواتِ وَالْأَرْضِ لا تَأْتِيكُمْ إِلاَّ بَغْتَةً يَسْئَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْها قُلْ إِنَّما عِلْمُها عِنْدَ اللهِ وَلكِنَّ أَكْثَرَ النَّاسِ لا يَعْلَمُونَ (187) ليكون أدعى لهم إلى الطاعة واجتناب المعصية ، فإن الإنسان إذا لم يعرف وقت البلاء يكون خائفا دائما ، أما إذا عرف أخّر الطاعات وكان خوفه لقرب وقت الساعة. ولا يقال : إن القيامة ليس مما يخاف منه الإنسان في الدنيا ، إذ هي بعد القبر ، فعلمها وعدمه سواء بالنسبة إلى الإنسان الحي ، وإنما يصح هذا التعليل بالنسبة إلى الموت. لأننا نقول : قيام القيامة بالنسبة إلى العاصين ـ وهم في القبر ـ من أكثر الأشياء خوفا ، كما ورد في الأحاديث. ( ثَقُلَتْ ) الساعة ، أي وقوعها ( فِي السَّماواتِ وَالْأَرْضِ ) فإن أهل السماوات والأرض يخافونها خوفا عظيما لشدتها وما فيها من المحاسبة والمجازاة ( لا تَأْتِيكُمْ ) أيها البشر ، أيها الشاعرون ( إِلَّا بَغْتَةً ) أي فجأة ( يَسْئَلُونَكَ كَأَنَّكَ حَفِيٌّ عَنْها ) أي أن الناس يسألونك يا رسول الله عن الساعة وعن وقت قيامتها ، كأنك عالم بها ، فإن « الحفي » بمعنى المستقصي في السؤال ، ويقال للعالم النحرير : « حفي » باعتبار أنه من كثرة سؤاله استوعب الأمر تماما وعلم الواقع كما هو ، فالمعنى : « كأنك عالم بالقيامة قد أكثرت المساءلة عنها » ( قُلْ ) يا رسول الله في جواب السائلين : ( إِنَّما عِلْمُها ) أي علم الساعة ( عِنْدَ اللهِ ) كرّر هذا ليصل بقوله : ( وَلكِنَّ أَكْثَرَ النَّاسِ لا يَعْلَمُونَ ) إن علمها قُلْ لا أَمْلِكُ لِنَفْسِي نَفْعاً وَلا ضَرًّا إِلاَّ ما شاءَ اللهُ وَلَوْ كُنْتُ أَعْلَمُ الْغَيْبَ لاسْتَكْثَرْتُ مِنَ الْخَيْرِ وَما مَسَّنِيَ السُّوءُ خاص بالله لا يشترك معه في هذا العلم أحد. [189] إن الساعة غيب لا يعلمه إلا الله ، وكذلك سائر الأمور الغائبة عن الحواس ، وإن كنت أنا ـ الرسول ـ أعلم الغيب بذاتي ، لكنت أعلم ما يضرّني فاجتنبه وما ينفعني فارتكبه ( قُلْ ) يا رسول الله لهؤلاء السائلين : ( لا أَمْلِكُ لِنَفْسِي نَفْعاً وَلا ضَرًّا ) فإنني لا أقدر على جلب نفع ولا دفع ضرر ( إِلَّا ما شاءَ اللهُ ) فما شاء أن يملكني إياه ؛ أتمكن منه ، وما لم يملكني إياه ؛ لا أتمكن منه ، وهذا كما ملّك سبحانه الرسول بعض المنافع ودفع عنه بعض المضارّ ، نعم الرسول أكثر ملكا حيث أنه مزوّد بقسم من الحصانة وعلم الغيب ( وَلَوْ كُنْتُ أَعْلَمُ الْغَيْبَ ) علما مطلقا كما يعلمه الله سبحانه ، فإن الرسول لم يكن يعلم الغيب بذاته ، وإنما بمقدار علم الله سبحانه ، كما قال سبحانه : ( فَلا يُظْهِرُ عَلى غَيْبِهِ أَحَداً* إِلَّا مَنِ ارْتَضى مِنْ رَسُولٍ ) (1) ، ( لَاسْتَكْثَرْتُ مِنَ الْخَيْرِ ) أي أكثر من الأشياء الخيرة كالشراء الرخيص أيام الرخص لأيام الغلاء ، وغيره مما لو عرفه الإنسان لانتفع به كثيرا ( وَما مَسَّنِيَ السُّوءُ ) الذي يمكن دفعه ، فإن الإنسان إذا عرف أن هذا الغذاء يضره أو هذا الشخص يقتله ، أو هذا السفر يؤذيه ـ مثلا ـ لأجتنبها. ومن الغريب أن بعض الناس يتمسكون بمثل هذه الآية لعدم معرفة الرسول بالأشياء المستقبلية إطلاقا ، إنه ليس إلا كتمسك المجبرة بقوله ( 1) الجن : 27 و 28. إِنْ أَنَا إِلاَّ نَذِيرٌ وَبَشِيرٌ لِقَوْمٍ يُؤْمِنُونَ (188) سبحانه : ( مَنْ يُضْلِلِ اللهُ فَلا هادِيَ لَهُ ) (1) ، والمجسمة بقوله : ( يَوْمَ يُكْشَفُ عَنْ ساقٍ ) (2) ، والقدرية بقوله : ( إِنَّا كُلَّ شَيْءٍ خَلَقْناهُ بِقَدَرٍ ) (3) ، والقائلين بحجية التوراة والإنجيل بقوله : ( إِنَّا أَنْزَلْنَا التَّوْراةَ فِيها هُدىً ) (4) ، ( وَلْيَحْكُمْ أَهْلُ الْإِنْجِيلِ بِما أَنْزَلَ اللهُ فِيهِ ) (5) ، والقائلين بمعصية الأنبياء بقوله : ( وَعَصى آدَمُ رَبَّهُ فَغَوى ) (6) ، والقائل بجهل الله سبحانه وتعالى بقوله : ( قُلْ أَ تُنَبِّئُونَ اللهَ بِما لا يَعْلَمُ فِي السَّماواتِ ) (7) ، والقائل بتعدد الآلهة بقوله : ( لَوْ كانَ فِيهِما آلِهَةٌ إِلَّا اللهُ لَفَسَدَتا ) (8) ، حيث دلل على أن الآلهة مع الله لا توجب الفساد. وهكذا من أمثال هذه الاستدلالات التي إن دلت على شيء فإنما تدل على عدم اطلاع القائل بأساليب الكلام ، وعدم جمعه بين النص والظاهر ، والعام والخاص ، والمطلق والمقيد ، والحقيقة والمجاز ، ومعارض السياق. ( إِنْ أَنَا ) أي ما أنا ( إِلَّا نَذِيرٌ ) أنذر الكافر والعاصي بالعقاب ( وَبَشِيرٌ ) أبشر المؤمن المطيع بالثواب ( لِقَوْمٍ يُؤْمِنُونَ ) اللام للعاقبة ، أي أن فائدة إنذاري وبشارتي إنما هي للمؤمن ، أما غيره فالرسول بشير نذير له ، لكنه حيث لا ينتفع بقوله ، فكأنه ليس مرسلا بالنسبة إليه. وقد ورد في بعض التفاسير أن أهل مكة قالوا : يا محمد ! ألا يخبرك ربك بالسعر الرخيص قبل أن يغلو فتشتريه فتربح فيه ، ( 1) الأعراف : 187. ( 2) القلم : 43. ( 3) القمر : 50. ( 4) المائدة : 45. ( 5) المائدة : 48. ( 6) طه : 122. ( 7) يونس : 19. ( 8) الأنبياء : 23. هُوَ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ واحِدَةٍ وَجَعَلَ مِنْها زَوْجَها لِيَسْكُنَ إِلَيْها فَلَمَّا تَغَشَّاها حَمَلَتْ حَمْلاً خَفِيفاً فَمَرَّتْ بِهِ فَلَمَّا أَثْقَلَتْ دَعَوَا اللهَ رَبَّهُما وبالأرض التي تريد أن تجدب فنرتحل منها إلى أرض قد أخصبت ، فأنزل الله هذه الآية. [190] وحيث انتهى السياق من قصة المعاد ، ونبذ من يوم البعث ، يأتي دور قصة أخرى من قصص البشر الذي لا يزال ينحرف عن الفطرة ويتوجه نحو الشرك والكفر ، كما تقدمت قصة « بلعم » بهذا الصدد ( هُوَ ) الله وحده ( الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ واحِدَةٍ ) فابتداء الخلقة بآدم عليه‌السلام وحده ( وَجَعَلَ ) أي خلق ( مِنْها ) أي من جنس تلك النفس ونوعها وصورتها ( زَوْجَها ) حواء عليها‌السلام ( لِيَسْكُنَ ) آدم عليه‌السلام المفهوم من قوله « نفس واحدة » ( إِلَيْها ) أي إلى الزوجة ، فيستريح بها وتكون موضع سكونه واطمئنانه وراحته ( فَلَمَّا تَغَشَّاها ) أي قاربها ، إذ الرجل حين المقاربة يكون كالغشاء والغطاء لها ( حَمَلَتْ حَمْلاً خَفِيفاً ) هو الماء الذي يستقر في الرحم أول الأمر ، وفي هذا الحين لا يحسّان بالحمل حتى يعلّقا عليه آمالا ، وينذرا لأجل الجنين نذورا ( فَمَرَّتْ بِهِ ) أي استمرت بالحمل على الخفة ( فَلَمَّا أَثْقَلَتْ ) أي صارت ذات ثقل ، وتبيّن الحمل وظهر أثره في الزوجة ( دَعَوَا اللهَ رَبَّهُما ) أي دعا الزوج والزوجة ، فإن الكلام حول الإنسان لا حول آدم وحواء عليهما‌السلام ، فإنه سبحانه يريد بيان الطبيعة البشرية التي تستقيم في أول الأمر ثم تنحرف لنوازع ورغبات ، والكلام في مثله حيث يبتدأ بجهة ، ثم ينصرف لجهة أخرى ، يسمى استخداما ، فإن اللفظ خدم معنى ، والضمير معنى آخر لَئِنْ آتَيْتَنا صالِحاً لَنَكُونَنَّ مِنَ الشَّاكِرِينَ (189) فَلَمَّا آتاهُما صالِحاً جَعَلا لَهُ شُرَكاءَ فِيما آتاهُما فَتَعالَى اللهُ عَمَّا يُشْرِكُونَ (190) أَ يُشْرِكُونَ ما لا يَخْلُقُ شَيْئاً وَهُمْ يُخْلَقُونَ (191) كما قال : ( وَالْمُطَلَّقاتُ ) ـ إلى قوله ـ ( وَبُعُولَتُهُنَ ) (1) ، فإن الضمير يرجع إلى بعض المطلقات ، وهنّ الرجعيات فقط. ( لَئِنْ آتَيْتَنا صالِحاً ) أي ولدا صالحا كاملا صحيح الخلقة ( لَنَكُونَنَّ مِنَ الشَّاكِرِينَ ) لك وحدك لا شريك لك ، فنقدر فضلك ولطفك علينا ، ونحمدك ونشكرك على ما أعطيتنا هذا الولد الصالح.` },
            { text: "يَسْـَٔلُونَكَ عَنِ ٱلسَّاعَةِ أَيَّانَ مُرْسَىٰهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ رَبِّى لَا يُجَلِّيهَا لِوَقْتِهَآ إِلَّا هُوَ ثَقُلَتْ فِى ٱلسَّمَٰوَٰتِ وَٱلْأَرْضِ لَا تَأْتِيكُمْ إِلَّا بَغْتَةً يَسْـَٔلُونَكَ كَأَنَّكَ حَفِىٌّ عَنْهَا قُلْ إِنَّمَا عِلْمُهَا عِندَ ٱللَّهِ وَلَٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ", tafsir: `` },
            { text: "قُل لَّآ أَمْلِكُ لِنَفْسِى نَفْعًا وَلَا ضَرًّا إِلَّا مَا شَآءَ ٱللَّهُ وَلَوْ كُنتُ أَعْلَمُ ٱلْغَيْبَ لَٱسْتَكْثَرْتُ مِنَ ٱلْخَيْرِ وَمَا مَسَّنِىَ ٱلسُّوٓءُ إِنْ أَنَا۠ إِلَّا نَذِيرٌ وَبَشِيرٌ لِّقَوْمٍ يُؤْمِنُونَ", tafsir: `` },
            { text: "هُوَ ٱلَّذِى خَلَقَكُم مِّن نَّفْسٍ وَٰحِدَةٍ وَجَعَلَ مِنْهَا زَوْجَهَا لِيَسْكُنَ إِلَيْهَا فَلَمَّا تَغَشَّىٰهَا حَمَلَتْ حَمْلًا خَفِيفًا فَمَرَّتْ بِهِۦ فَلَمَّآ أَثْقَلَت دَّعَوَا ٱللَّهَ رَبَّهُمَا لَئِنْ ءَاتَيْتَنَا صَٰلِحًا لَّنَكُونَنَّ مِنَ ٱلشَّٰكِرِينَ", tafsir: `` },
            { text: "فَلَمَّآ ءَاتَىٰهُمَا صَٰلِحًا جَعَلَا لَهُۥ شُرَكَآءَ فِيمَآ ءَاتَىٰهُمَا فَتَعَٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ", tafsir: `أي أعطى الله الأبوين ولدا ( صالِحاً جَعَلا ) أي الأبوان ( لَهُ ) سبحانه ( شُرَكاءَ فِيما آتاهُما ) في الشؤون المرتبطة بالولد ، فتشكر الأصنام كما يشكر الله في إعطاء الولد ، ويسمياه بعبد العزى وعبد اللات وعبد مناة ، وأحيانا كانا ينذرانه للأصنام ذبحا أو خدمة ؛ كما ينذر لخدمة المسجد ونحوه ( فَتَعالَى اللهُ ) أي أن الله أعلى وأجل ( عَمَّا يُشْرِكُونَ ) أي يشرك البشر ، إنه سبحانه ليس له شريك ولا مثيل.` },
            { text: "أَيُشْرِكُونَ مَا لَا يَخْلُقُ شَيْـًٔا وَهُمْ يُخْلَقُونَ", tafsir: `استفهام توبيخي ، أي كيف ي شرك هؤلاء مع الله شريكا ( ما لا يَخْلُقُ شَيْئاً ) ؟ فإن الأصنام لا تتمكن من خلق شيء ( وَهُمْ يُخْلَقُونَ ) أي أولئك الشركاء ـ كالأصنام ـ هي كلها مخلوقة ، أو المراد أن الجميع من المشرك والأصنام مخلوقون. ( 1) البقرة : 229. وَلا يَسْتَطِيعُونَ لَهُمْ نَصْراً وَلا أَنْفُسَهُمْ يَنْصُرُونَ (192) وَإِنْ تَدْعُوهُمْ إِلَى الْهُدى لا يَتَّبِعُوكُمْ سَواءٌ عَلَيْكُمْ أَ دَعَوْتُمُوهُمْ أَمْ أَنْتُمْ صامِتُونَ (193)` },
            { text: "وَلَا يَسْتَطِيعُونَ لَهُمْ نَصْرًا وَلَآ أَنفُسَهُمْ يَنصُرُونَ", tafsir: `أي لا تستطيع تلك الأصنام ( لَهُمْ ) أي لعبّادها ( نَصْراً ) حيث يقعون في المشاكل ( وَلا أَنْفُسَهُمْ يَنْصُرُونَ ) لا تستطيع الأصنام نصر أنفسها إذا تعدّى عليها متعدّ ، كما قد رأى ذلك الشاعر أن الثعلب يبول على رأس صنمه ، فكسره قائلا : أرب يبول الثعلبان برأسه ؟ لقد ذلّ من بالت عليه الثعالب ولا يخفى أن الإتيان بضمير العاقل للأصنام للتشاكل بما كان يعتقده عابدوها من أنها تعقل وتفهم وتضر وتنفع.` },
            { text: "وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَتَّبِعُوكُمْ سَوَآءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنتُمْ صَٰمِتُونَ", tafsir: `أيها المسلمون إن تدعوا هؤلاء المشركين ( إِلَى الْهُدى ) ليهتدوا ويتركوا أصنامهم ( لا يَتَّبِعُوكُمْ ) حيث استحوذ الشيطان عليهم ( سَواءٌ عَلَيْكُمْ أَدَعَوْتُمُوهُمْ أَمْ أَنْتُمْ صامِتُونَ ) فإن دعاءهم إلى الإيمان والسكوت عنهم متساويان ، كما قال سبحانه : ( سَواءٌ عَلَيْهِمْ أَ أَنْذَرْتَهُمْ أَمْ لَمْ تُنْذِرْهُمْ لا يُؤْمِنُونَ ) (1) . وقد يستشكل بعض الملحدين : بأن الأمر إن كان بالنسبة إلى مرحلة الظاهر فالله « سبحانه » والأصنام متساويان من هذه الجهة ، فإنه لا يظهر أثر للنصرة وعدمها ، وإن كان بالنسبة إلى مرحلة الواقع ، فأي ( 1) البقرة : 7. إِنَّ الَّذِينَ تَدْعُونَ مِنْ دُونِ اللهِ عِبادٌ أَمْثالُكُمْ فَادْعُوهُمْ فَلْيَسْتَجِيبُوا لَكُمْ إِنْ كُنْتُمْ صادِقِينَ (194) دليل على الفرق ، وإن الأصنام تنصر في زعم عبادها كما أن الله ينصر في نظر المسلمين ؟ والجواب : إن الأدلة لما دلّت على وجوده سبحانه كانت كافية للفرق في مرحلة الواقع ، فلو كان هناك شخصان أحدهما يملك شهادة الطب ، والآخر جاهل ، ولم ينفع الدواء الذي وصفه صاحب شهادة الطب للمريض ، لا يمكن أن يقال بالتساوي مع الجاهل ، وإنما يجب أن يعلل بعلة أخرى ، وإن شئت قلت : إن الدليل في قوله تعالى : ( لا يَسْتَطِيعُونَ لَهُمْ نَصْراً ) خطاب في الظاهر ، وإنما البرهان المقنع ما ذكرنا. وبهذا يجاب عن الإشكال بالنسبة إلى التوسل بالأنبياء والأولياء مما دلّ الدليل عليه.` },
            { text: "إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ عِبَادٌ أَمْثَالُكُمْ فَٱدْعُوهُمْ فَلْيَسْتَجِيبُوا۟ لَكُمْ إِن كُنتُمْ صَٰدِقِينَ", tafsir: `أي الأصنام الذين ( تَدْعُونَ ) هم ( مِنْ دُونِ اللهِ ) أي تجعلونهم آلهة ( عِبادٌ ) أي مخلوقة لله ، فإن العبد هو المطيع. ومن المعلوم أن الجمادات تطيع الله تعالى ، كما يطيعه الإنسان ، كما قال سبحانه : ( وَإِنْ مِنْ شَيْءٍ إِلَّا يُسَبِّحُ بِحَمْدِهِ وَلكِنْ لا تَفْقَهُونَ تَسْبِيحَهُمْ ) (1) ، ( أَمْثالُكُمْ ) أيها البشر فليسوا بآلهة حتى تعبدونهم. ( فَادْعُوهُمْ ) في مهماتكم وكشف الضر عنكم ( فَلْيَسْتَجِيبُوا لَكُمْ ) الأمر هنا للتعجيز والتوهين ، كما تقول للعاجز عن القيام : « قم إن صدقت أنك قادر » ( إِنْ كُنْتُمْ صادِقِينَ ) في أنها آلهة تنفع وتضر. ( 1) الإسراء : 45. أَ لَهُمْ أَرْجُلٌ يَمْشُونَ بِها أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِها أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِها أَمْ لَهُمْ آذانٌ يَسْمَعُونَ بِها قُلِ ادْعُوا شُرَكاءَكُمْ ثُمَّ كِيدُونِ فَلا تُنْظِرُونِ (195) ومن الوهابيين من يستدل بهذه الآية بعدم صحة التوسل بالأنبياء والأئمة ، قائلا : « فادعوهم فليستجيبوا لكم » . والجواب : نقضا ؛ « فادع الله فليستجب لك » فإن قال : يستجيب ، قلنا : يستجيبون بأمر الله تعالى وإذنه. وحلا ؛ بأن الفارق هو الدليل ، وعدم الاستجابة العاجلة لا دلالة فيه لأحد الطرفين. [196] ثم بيّن سبحانه أن الأصنام لا تقدر على شيء حتى على ما يقدر الإنسان العادي عليه ، فمن لا يقدر على أقل شيء كيف يكون إلها معبودا ؟ ( أَ لَهُمْ أَرْجُلٌ يَمْشُونَ بِها ) أي : هل لهذه الأصنام أرجل يمشون بها في مصالحكم ، أو مشيا لأنفسهم ، حتى يتساووا مع أقل حيوان أو إنسان ؟ ( أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِها ) « البطش » هو الأخذ بشدة ، أي يأخذون بأيديهم بشدة ما يريدون الانتقام منه ، أو مطلق الأخذ ( أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِها ) الأشياء ؟ ( أَمْ لَهُمْ آذانٌ يَسْمَعُونَ بِها ) الأصوات والشكاوى وغيرهما ؟ إنها لا تحس إطلاقا ، فكيف تعبدون أنتم أيها البشر هذه الأشياء الفاقدة لكل حس ؟ ( قُلِ ) يا رسول الله للمشركين : ( ادْعُوا شُرَكاءَكُمْ ) أي الشركاء الذين جعلتموهم مع الله سبحانه ( ثُمَّ كِيدُونِ ) أي امكروا بي بأجمعكم عابدا ومعبودا ( فَلا تُنْظِرُونِ ) لا تأخروني ، بل أسرعوا في الكيد ، فإن ربي ينصرني عليكم جميعا. إن الرسول صلى‌الله‌عليه‌وآله‌وسلم بهذا إِنَّ وَلِيِّيَ اللهُ الَّذِي نَزَّلَ الْكِتابَ وَهُوَ يَتَوَلَّى الصَّالِحِينَ (196) وَالَّذِينَ تَدْعُونَ مِنْ دُونِهِ لا يَسْتَطِيعُونَ نَصْرَكُمْ وَلا أَنْفُسَهُمْ يَنْصُرُونَ (197) وَإِنْ تَدْعُوهُمْ إِلَى الْهُدى لا يَسْمَعُوا وَتَراهُمْ يَنْظُرُونَ إِلَيْكَ وَهُمْ لا يُبْصِرُونَ (198) يتحدّاهم ، لبيان أن الله ناصر نبيه ، لكن أصنامكم لا تنصركم.` },
            { text: "أَلَهُمْ أَرْجُلٌ يَمْشُونَ بِهَآ أَمْ لَهُمْ أَيْدٍ يَبْطِشُونَ بِهَآ أَمْ لَهُمْ أَعْيُنٌ يُبْصِرُونَ بِهَآ أَمْ لَهُمْ ءَاذَانٌ يَسْمَعُونَ بِهَا قُلِ ٱدْعُوا۟ شُرَكَآءَكُمْ ثُمَّ كِيدُونِ فَلَا تُنظِرُونِ", tafsir: `` },
            { text: "إِنَّ وَلِـِّۧىَ ٱللَّهُ ٱلَّذِى نَزَّلَ ٱلْكِتَٰبَ وَهُوَ يَتَوَلَّى ٱلصَّٰلِحِينَ", tafsir: `الذي يتولى أمري وينصرني ( اللهُ الَّذِي نَزَّلَ الْكِتابَ ) أي القرآن ، فإنه كما أمرني بالرسالة ضمن لي النصرة ( وَهُوَ يَتَوَلَّى الصَّالِحِينَ ) يتولى أمورهم وينصرهم على أعدائهم ، وهذا لا ينافي عدم الحيلولة بينهم وبين أعدائهم أحيانا لمصالح وجهات.` },
            { text: "وَٱلَّذِينَ تَدْعُونَ مِن دُونِهِۦ لَا يَسْتَطِيعُونَ نَصْرَكُمْ وَلَآ أَنفُسَهُمْ يَنصُرُونَ", tafsir: `الأصنام ( الَّذِينَ تَدْعُونَ ) هم ( مِنْ دُونِهِ ) أي غير الله سبحانه من الآلهة ( لا يَسْتَطِيعُونَ نَصْرَكُمْ ) لا يقدرون على أن ينصروكم ( وَلا أَنْفُسَهُمْ يَنْصُرُونَ ) فإذا تعدّى عليهم متعدّ لا يتمكنون من الدفاع عن أنفسهم.` },
            { text: "وَإِن تَدْعُوهُمْ إِلَى ٱلْهُدَىٰ لَا يَسْمَعُوا۟ وَتَرَىٰهُمْ يَنظُرُونَ إِلَيْكَ وَهُمْ لَا يُبْصِرُونَ", tafsir: `إن تدعوا أيها المسلمون ، المشركين ( إِلَى الْهُدى ) والحق ( لا يَسْمَعُوا ) دعاءكم فإنهم معاندون ، وقيل : المعنى إن تدعوا الأصنام لا يسمعوا لأنهم جماد ( وَتَراهُمْ ) يا رسول الله ، أو كل من يتأتى منه الرؤية ( يَنْظُرُونَ إِلَيْكَ ) أي المشركون ، أو الأصنام ، فإن الأصنام عيونها مفتوحة إلى الإنسان كالناظر ( وَهُمْ لا يُبْصِرُونَ ) إبصارا نافعا ؛ إذا كان وصفا للمشركين ، أو أصل الإبصار ؛ إذا كان وصفا للأصنام. [200] وحيث أن الإنسان إذا ورد في خضم الاحتجاج ورأى عناد الخصم خُذِ الْعَفْوَ وَأْمُرْ بِالْعُرْفِ وَأَعْرِضْ عَنِ الْجاهِلِينَ (199) وَإِمَّا يَنْزَغَنَّكَ مِنَ الشَّيْطانِ نَزْغٌ فَاسْتَعِذْ بِاللهِ إِنَّهُ سَمِيعٌ على الباطل يأخذه الغضب الموجب للخروج عن آداب المحاورة ، أوصى الله سبحانه نبيه بمكارم الأخلاق ـ بمناسبة المقام ـ فقال : ( خُذِ الْعَفْوَ ) عن الناس أي لازم العفو عنهم ، وأصفح عن السيئ منهم ، أو المراد خذ الزائد من أموالهم ، أي ما عفا وفضل من نفقاتهم ، فإن الخمس والزكاة والخراج والجزية كذلك ـ غالبا ـ والمعنى الأول أقرب إلى الظاهر ، والمعنى الثاني وارد في الحديث ، ولا يبعد إرادة الأمرين ، فإن استعمال اللفظ في أكثر من معنى جائز إذا كان هناك دليل ( وَأْمُرْ بِالْعُرْفِ ) أي ما يستحسنه العرف ، وهو ما ليس بقبيح عند العقل ، وهو ضد النكر ( وَأَعْرِضْ عَنِ الْجاهِلِينَ ) فلا تقابل جهلهم بجهل. إن المتكلم مع طبقات الناس المختلفة يحتاج إلى التزام هذه الأشياء إن أراد مراعاة الآداب ، فاللازم أولا أن يعفو عمن يخشن في الكلام ويتنكب عن طريق الحق ، ثم يأمره بالمعروف لعله يرجع ويسترشد ، فإذا رأى منه جهلا وإصرارا ، فليعرض عنه ولا يقابله بمثل عمله.` },
            { text: "خُذِ ٱلْعَفْوَ وَأْمُرْ بِٱلْعُرْفِ وَأَعْرِضْ عَنِ ٱلْجَٰهِلِينَ", tafsir: `` },
            { text: "وَإِمَّا يَنزَغَنَّكَ مِنَ ٱلشَّيْطَٰنِ نَزْغٌ فَٱسْتَعِذْ بِٱللَّهِ إِنَّهُۥ سَمِيعٌ عَلِيمٌ", tafsir: `مركبة من « إن » الشرطية و « ما » الزائدة تأتي لتجميل الكلام وفوائد أخر ( يَنْزَغَنَّكَ ) « النزغ » هو الإزعاج بالإغراء ، وأكثر ما يكون ذلك عند الغضب ، أي إن تالك ( مِنَ الشَّيْطانِ نَزْغٌ ) وسوسة ونيل ونخسه في القلب ، وحركة وإزعاج بأن ثار القلب أمام الجاهل وغضب واحتد ، حتى أراد الانتقام والسباب ( فَاسْتَعِذْ بِاللهِ ) أي سل الله سبحانه أن يعيذك ويحفظك من شر الشيطان ( إِنَّهُ ) سبحانه ( سَمِيعٌ ) عَلِيمٌ (200) إِنَّ الَّذِينَ اتَّقَوْا إِذا مَسَّهُمْ طائِفٌ مِنَ الشَّيْطانِ تَذَكَّرُوا فَإِذا هُمْ مُبْصِرُونَ (201) وَإِخْوانُهُمْ يَمُدُّونَهُمْ فِي الغَيِّ ثُمَّ لا يُقْصِرُونَ (202) لقولك ( عَلِيمٌ ) بقصدك وما عرض لك. [202] ثم بيّن سبحانه أن هذه قاعدة المؤمنين كلما ألقى الشيطان في قلوبهم ميلا وزيغا ، أدركتهم الفطنة ، فلم يميلوا إليه ( إِنَّ الَّذِينَ اتَّقَوْا ) بأن جعلوا التقوى شعارهم ، وذاقوا حلاوتها وصارت ملكة وعادة عندهم ( إِذا مَسَّهُمْ طائِفٌ مِنَ الشَّيْطانِ ) بأن أتاهم من يطوف من الشياطين على قلوب بني آدم ، فأراد إغواءهم ، وميلهم عن الحق ، وأعمى قلوبهم ، وزين في نفوسهم الشهوات. وقد دلت الأدلة الشرعية والعلمية (1) على أن في الجو أرواح شريرة شأنها الإغراء والإغواء ، ولا يراها الإنسان. ( تَذَكَّرُوا ) وأدركتهم ملكة التقوى الكامنة في نفوسهم ( فَإِذا هُمْ مُبْصِرُونَ ) يبصرون الطريق ولا يعمهون عن الحق ، ولا يتمكن الشيطان من تغشية قلوبهم بغشاء الشهوات والمغريات. [203] هذا شأن المتقين الذين لا يسايرون الشياطين في إغوائهم وإغرائهم ( وَ ) أما ( إِخْوانُهُمْ ) أي إخوان الشياطين الذين لا تقوى لهم ليرتدعوا عن المعاصي والآثام فإنهم ( يَمُدُّونَهُمْ ) أي يمدون الشياطين ويسايرونهم ( فِي الغَيِ ) والضلال ، فإذا مس العاصي طائف من الشيطان عمل بما يوحي إليه ، وكان ذلك إمدادا للشياطين ، لأنه مشى في ركابهم ، ومسايرة لهم ( ثُمَّ لا يُقْصِرُونَ ) بل يذهبون إلى آخر ( 1) المس الروحي / عبد الرزاق نوفل. وَإِذا لَمْ تَأْتِهِمْ بِآيَةٍ قالُوا لَوْ لا اجْتَبَيْتَها قُلْ إِنَّما أَتَّبِعُ ما يُوحى إِلَيَّ مِنْ رَبِّي هذا بَصائِرُ مِنْ رَبِّكُمْ وَهُدىً وَرَحْمَةٌ الشوط ، بخلاف المتقين الذين لا يمدون الشياطين ويقصّرون في المسايرة ، ولعل جملة « ثم لا يقصرون » للإشارة إلى أن المتقي إذا غفل وأغري ومشى بعض الطريق مع الشيطان أدركته بصيرته فرجع ولا يسير إلى آخر الشوط ، بخلاف إخوان الشياطين. [204] وفي سياق الكلام حول أدب الحوار مع الناس ، وأن المتقي متأدب بالآداب يأتي دور المحاورة بين الرسول والكفار حول القرآن كشاهد لأدب الرسول صلى‌الله‌عليه‌وآله‌وسلم ، وكون الكفار إخوان الشياطين الذين يمدونهم في الغي ( وَإِذا لَمْ تَأْتِهِمْ ) يا رسول الله ( بِآيَةٍ ) أي بمعجزة يقترحونها عليك ، فإن الكفار كانوا يقترحون على الرسول الأمور الخارقة للعادة لمجرد المجادلة والمعاندة ، لا لإرادة الاهتداء والاسترشاد ، فإذا لم يستجب الرسول لمطلبهم ( قالُوا ) أي الكفار : ( لَوْ لا اجْتَبَيْتَها ) أي لماذا لم تختر هذه الآية المقترحة ؟ ولماذا لم تأت بها ؟ كأنهم ، يرون الرسول صلى‌الله‌عليه‌وآله‌وسلم الفاعل لما يشاء ، فمهما اجتبى آية واختارها ، أتى بها ( قُلْ ) يا رسول الله : إن الآيات ليست باختياري واجتبائي ، بل ( إِنَّما أَتَّبِعُ ما يُوحى إِلَيَّ مِنْ رَبِّي ) فاللازم اختيار الله للآيات ، فما رآها صلاحا أرسلها وزودني بها ، وما لم يرها صلاحا لم يرسلها ، إن كنتم تريدون الحق والهدى ـ حقيقة ـ وقصدكم من طلب الآيات ، إقامة الدليل والحجة على صدقي ف ( هذا ) الذي جئت به من القرآن المعجز الذي لم تتمكنوا أن تأتوا بمثله ( بَصائِرُ ) وحجج وبراهين ( مِنْ ) قبل ( رَبِّكُمْ وَهُدىً ) يهدي من أراد الحق إلى الحق ( وَرَحْمَةٌ ) يوجب لِقَوْمٍ يُؤْمِنُونَ (203) وَإِذا قُرِئَ الْقُرْآنُ فَاسْتَمِعُوا لَهُ وَأَنْصِتُوا لَعَلَّكُمْ تُرْحَمُونَ (204) وَاذْكُرْ رَبَّكَ فِي نَفْسِكَ تَضَرُّعاً وَخِيفَةً ترحّم الله سبحانه ولطفه بالعاملين به ( لِقَوْمٍ يُؤْمِنُونَ ) اللام للعاقبة ، إذ المنتفع بهذه الآيات هم المتقون فقط. [205] وإذ تقدم ذكر القرآن تلميحا بقوله « هذا بصائر » بيّن سبحانه لزوم الأدب أمام القرآن بقوله : ( وَإِذا قُرِئَ الْقُرْآنُ ) أي قارئ كان ( فَاسْتَمِعُوا لَهُ ) أي أعيروا أسماعكم له ( وَأَنْصِتُوا ) « الإنصات » هو السكوت. ومن المعلوم أن الإنصات أخص من الاستماع ، فإن الإنسان ربما يستمع إلى الكلام وهو يتكلّم ، ولذا نص عليه ، فإن الأدب أن يستمع الإنسان ، ولا يتكلّم ، وهذا الأمر للاستحباب ، ككثير من أوامر القرآن الكريم كقوله : ( فَكاتِبُوهُمْ إِنْ عَلِمْتُمْ فِيهِمْ خَيْراً ) (1) ، كما دلّت على ذلك الأحاديث ( لَعَلَّكُمْ تُرْحَمُونَ ) أي لكي يرحمكم الله سبحانه بسبب تأدبكم أمام كتابه الكريم ، أو بسبب اتعاظكم بمواعظه ، حيث تستمعون لها. [206] وبمناسبة الإنصات عند تلاوة القرآن ، يأتي بيان كيفية دعوة الله سبحانه ، فإن القرآن كلام الله للخلق ، والدعاء كلام الخلق مع الله سبحانه ( وَاذْكُرْ ) يا رسول الله ، أو كل من يأتي منه الذكر ( رَبَّكَ فِي نَفْسِكَ ) أما المراد به حديث النفس ، وأما المراد التذكر بالهمس والإخفات ، ولعل الأول أقرب ، بقرينة ما يأتي بقوله : « ودون .. . » ( تَضَرُّعاً ) أي بنحو الضراعة والاستكانة ( وَخِيفَةً ) أي مع الخوف من ( 1) النور : 34. وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْآصالِ وَلا تَكُنْ مِنَ الْغافِلِينَ (205) إِنَّ الَّذِينَ عِنْدَ رَبِّكَ الله تعالى ، فإن ذلك أقرب إلى الإجابة ( وَ ) اذكره سبحانه ( دُونَ الْجَهْرِ مِنَ الْقَوْلِ ) فإن الكلام المتوسط خير ، وهذا لا ينافي استحباب الإجهار لدواعي أخر ، كما نزل جبرئيل على الرسول ، وقال : « يأمرك ربك بالعج والثج » (1) في باب التلبية وما ورد من أن الصلوات المجهر بها تذهب بالنفاق ، وما دل على الإتيان بالصلوات الثلاث جهرية ، إلى غير ذلك ، والقول بأن الله لا يحتاج إلى الإجهار تعليل تافه ، فإنه ينقض بأن الله لا يحتاج إلى الكلام ، فليكتف المستشكل بحديث النفس في قراءته ودعائه وأذكاره ؟ ( بِالْغُدُوِّ ) أي الصباح ( وَالْآصالِ ) جمع « أصل » ، وأصل جمع « أصيل » ، فهو جمع الجمع ، ومعناه « العشيات » ، وهو ما بين العصر إلى غروب الشمس ، وهذا كناية عن دوام الذكر ، والتفريق بين « الغدو والآصال » بالإفراد والجمع ، تفنن بلاغي لا يخفى لطفه. ( وَلا تَكُنْ ) يا رسول الله ، أو المراد العموم ، والمقصد العموم على أي حال ، وإنما الكلام في مرجع الضمير ( مِنَ الْغافِلِينَ ) الذين يغفلون عن ذكر الله سبحانه. وفي الآية الكريمة روايات كثيرة غالبها من باب بيان المصداق ، فلا تضر بعمومها. [207] ثم بيّن سبحانه أن الملائكة الذين هم أبعد عن النزوات ، وهم دائمو الذكر ، فأجدر بالإنسان أن يكون متذكّرا دائما ( إِنَّ الَّذِينَ عِنْدَ رَبِّكَ ) ( 1) راجع بحار الأنوار : ج 96 ص 286. لا يَسْتَكْبِرُونَ عَنْ عِبادَتِهِ وَيُسَبِّحُونَهُ وَلَهُ يَسْجُدُونَ (206) أي الملائكة ، والمراد بكونهم عنده سبحانه أنهم في قربه ، قرب الجاه والمكانة ، لا القرب المكاني ( لا يَسْتَكْبِرُونَ عَنْ عِبادَتِهِ ) ولا يترفعون بأنفسهم عن الخضوع والخشوع له سبحانه ( وَيُسَبِّحُونَهُ ) أي ينزهونه عما لا يليق به ، بذكر « سبحان الله » أو غيره ( وَلَهُ ) تعالى ( يَسْجُدُونَ ) كسجودنا ، أو المراد غاية الخضوع. (8)` },
            { text: "إِنَّ ٱلَّذِينَ ٱتَّقَوْا۟ إِذَا مَسَّهُمْ طَٰٓئِفٌ مِّنَ ٱلشَّيْطَٰنِ تَذَكَّرُوا۟ فَإِذَا هُم مُّبْصِرُونَ", tafsir: `` },
            { text: "وَإِخْوَٰنُهُمْ يَمُدُّونَهُمْ فِى ٱلْغَىِّ ثُمَّ لَا يُقْصِرُونَ", tafsir: `` },
            { text: "وَإِذَا لَمْ تَأْتِهِم بِـَٔايَةٍ قَالُوا۟ لَوْلَا ٱجْتَبَيْتَهَا قُلْ إِنَّمَآ أَتَّبِعُ مَا يُوحَىٰٓ إِلَىَّ مِن رَّبِّى هَٰذَا بَصَآئِرُ مِن رَّبِّكُمْ وَهُدًى وَرَحْمَةٌ لِّقَوْمٍ يُؤْمِنُونَ", tafsir: `` },
            { text: "وَإِذَا قُرِئَ ٱلْقُرْءَانُ فَٱسْتَمِعُوا۟ لَهُۥ وَأَنصِتُوا۟ لَعَلَّكُمْ تُرْحَمُونَ", tafsir: `` },
            { text: "وَٱذْكُر رَّبَّكَ فِى نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ ٱلْجَهْرِ مِنَ ٱلْقَوْلِ بِٱلْغُدُوِّ وَٱلْـَٔاصَالِ وَلَا تَكُن مِّنَ ٱلْغَٰفِلِينَ", tafsir: `` },
            { text: "إِنَّ ٱلَّذِينَ عِندَ رَبِّكَ لَا يَسْتَكْبِرُونَ عَنْ عِبَادَتِهِۦ وَيُسَبِّحُونَهُۥ وَلَهُۥ يَسْجُدُونَ", tafsir: `` }
        ]
    }
});
